window.GLOSSARY=[{"t":"\"Longitude east, UTC least; longitude west, UTC best\"","d":"LMT = UTC + d.long/15 (east); LMT = UTC − d.long/15 (west).","s":"Nav 5","ch":"Time","sec":"Conversions","h":"chapters/nav-05.html#n-conversions"},{"t":"−4° (zero-lift AoA)","d":"pressure drop on top equals that below: no lift.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Transition, separation and the creation of lift (2-12)","h":"chapters/hb-02.html#n-transition-separation-and-the-creation-of-lift-2-12"},{"t":"≈ M 0.98","d":"both shocks reach the trailing edge; the suction is restored and CL recovers; CD still rising; CP moves back again.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"What happens as Mach number rises (2-50)","h":"chapters/hb-08.html#n-what-happens-as-mach-number-rises-2-50"},{"t":"≈ M 1.4","d":"the bow wave attaches to the LE; CL falls (top and bottom pressures similar); CD falls for the first time; CP settles at about 50% chord.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"What happens as Mach number rises (2-50)","h":"chapters/hb-08.html#n-what-happens-as-mach-number-rises-2-50"},{"t":"A, B, G, R","d":"regional, not RNAV. L, M, N, P: regional RNAV. H, J, V, W: non-regional, not RNAV. Q, T, Y, Z: non-regional RNAV.","s":"Reg 5","ch":"Air Traffic Services","sec":"ATS route designators (p.148–150)","h":"chapters/reg-05.html#n-ats-route-designators-p-148-150"},{"t":"AAI","d":"formed 1 April 1995 by merging IAAI and NAA: builds and runs airports, manages Indian airspace (including beyond territorial limits as accepted by ICAO), provides ATS, CNS aids and AIS (AIP, NOTAM, AIRAC, PIB).","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Indian organisations (p.53–54)","h":"chapters/reg-02.html#n-indian-organisations-p-53-54"},{"t":"Above 8 km reversal","d":"density greater over the equator.","s":"Met 4","ch":"Air Density","sec":"Latitudinal variation (p.39)","h":"chapters/met-04.html#n-latitudinal-variation-p-39"},{"t":"Above M 1.0","d":"a bow shockwave forms ahead of the aircraft (distance depends on speed, size, air temperature) and moves closer as speed rises. No upwash or downwash in supersonic flow.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"What happens as Mach number rises (2-50)","h":"chapters/hb-08.html#n-what-happens-as-mach-number-rises-2-50"},{"t":"Absolute ceiling","d":"rate of climb zero; service ceiling: ~100 ft/min.","s":"Nav 15","ch":"Performance","sec":"Cruise, ceiling, descent, glide","h":"chapters/nav-15.html#n-cruise-ceiling-descent-glide"},{"t":"Absolute humidity","d":"actual mass of WV per volume of air (g/m³).","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Absolute zero","d":"the lowest possible temperature, same for all substances; molecular motion almost stops. 0 K = −273.16°C (book wording \"1K = −273.16°C\").","s":"Met 3","ch":"Temperature","sec":"Scales (p.27)","h":"chapters/met-03.html#n-scales-p-27"},{"t":"AC","d":"light to moderate; severe possible over mountains.","s":"Met 12","ch":"Ice Accretion","sec":"Icing by cloud (p.108)","h":"chapters/met-12.html#n-icing-by-cloud-p-108"},{"t":"ACAS RA","d":"nothing relieves the PIC of taking avoiding action, including following resolution advisories.","s":"Reg 4","ch":"Rules of the Air","sec":"General rules (p.78–81)","h":"chapters/reg-04.html#n-general-rules-p-78-81"},{"t":"Acceleration/deceleration","d":"max on E/W headings, nil on N/S. APDE: Acceleration → apparent turn towards the nearer Pole; Deceleration → towards the Equator. NH: accelerating on west, card turns clockwise, under-reads, shows a turn to the right/north.","s":"Nav 8","ch":"Magnetism and Compasses","sec":"Errors due to dip (direct-reading compass)","h":"chapters/nav-08.html#n-errors-due-to-dip-direct-reading-compass"},{"t":"Acceptance","d":"the first ATS unit checks format and data conventions, completeness and accuracy, makes it acceptable if needed and indicates acceptance to the originator.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Submission","h":"chapters/nav-16.html#n-submission"},{"t":"Accident","d":"between boarding with intention of flight and disembarkation: a person fatally or seriously injured, aircraft damage/structural failure, or aircraft missing/inaccessible. Serious incident: an accident nearly occurred. Incident: anything else affecting or able to affect safety.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Emergency and SAR words (p.8–31)","h":"chapters/reg-01.html#n-emergency-and-sar-words-p-8-31"},{"t":"Accumulator","d":"stores fluid under pressure, damps pressure surges, allows thermal expansion, provides emergency pressure.","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Hydraulic components (3-7)","h":"chapters/hb-10.html#n-hydraulic-components-3-7"},{"t":"Active spells and breaks","d":"break = trough shifts to the Himalayan foothills → rain drops over the plains, pressure rises, heavy rain over the foothills (sub-Himalayan WB, Nepal, Bhutan) → floods in NE India and Bihar; strong surface westerlies over E UP/Bihar; pre-monsoon-type weather with dust haze; hot and humid.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"AD","d":"aerodrome availability, rescue and fire-fighting, lists, grouping, licensing status, then each aerodrome.","s":"Reg 10","ch":"Aeronautical Information Services","sec":"India (p.240–245)","h":"chapters/reg-10.html#n-india-p-240-245"},{"t":"ADF on an RBI","d":"needle shows relative bearing; QDM = relative bearing + magnetic heading; QDR = QDM ± 180; QTE = QDR ± variation at the aircraft.","s":"Nav 13","ch":"In-flight Navigation","sec":"Fixes and position lines","h":"chapters/nav-13.html#n-fixes-and-position-lines"},{"t":"Adiabatic change","d":"no heat exchanged with the surroundings. Isothermal change: at constant temperature.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Physical terms (2-3)","h":"chapters/hb-01.html#n-physical-terms-2-3"},{"t":"Adiabatic process","d":"no heat exchange. Rising parcel → lower pressure → expands → cools (work done from internal energy); sinking parcel → compressed → warms. Adiabatic processes largely determine the vertical temperature distribution.","s":"Met 9","ch":"Stability and Instability","sec":"Processes (p.87)","h":"chapters/met-09.html#n-processes-p-87"},{"t":"ADIZ","d":"airspace with special identification/reporting procedures beyond ATS ones.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Airspace and ATS (p.5–35)","h":"chapters/reg-01.html#n-airspace-and-ats-p-5-35"},{"t":"ADS-B","d":"broadcast via data link. ADS-C: by contract (event, demand, periodic, emergency). ACAS: SSR-transponder based, independent of ground equipment.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Navigation words (p.12–38)","h":"chapters/reg-01.html#n-navigation-words-p-12-38"},{"t":"ADS-B","d":"aircraft automatically broadcast position and data to ATC and to other equipped aircraft. ADS-C: the same on-board data sent only to specific ATSUs/AOC under a contract (which data, when); the aircraft can also send unsolicited emergency reports.","s":"Reg 9","ch":"Use of ATS Surveillance Systems","sec":"Surveillance systems (p.221–223)","h":"chapters/reg-09.html#n-surveillance-systems-p-221-223"},{"t":"ADS-B","d":"aircraft identification in the ADS-B label; transfer of identification; compliance with \"TRANSMIT ADS-B IDENT\".","s":"Reg 9","ch":"Use of ATS Surveillance Systems","sec":"Identification (p.224–226)","h":"chapters/reg-09.html#n-identification-p-224-226"},{"t":"Advantages","d":"transmits high forces, rapid precise response, good power/weight, simple, reliable, self-lubricating. Disadvantages: contamination, heat and aeration; hazardous fluid; leaks; heavier than pneumatics.","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Hydraulics — principles (3-6)","h":"chapters/hb-10.html#n-hydraulics-principles-3-6"},{"t":"Advantages","d":"non-flammable, light, air freely available, minor leaks harmless, no return lines/filtration needs. Disadvantages: not precise or rapid, low working pressure, cannot handle high power (air is compressible).","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Pneumatic system (3-8)","h":"chapters/hb-10.html#n-pneumatic-system-3-8"},{"t":"Advantages","d":"shortest landing distance, less tyre wear, touchdown protection (no braking until the wheels spin up), skid prevention, locked-wheel protection.","s":"Handbook 11","ch":"Landing Gear, Brakes, Tyres and Powered Controls","sec":"Brakes (3-11)","h":"chapters/hb-11.html#n-brakes-3-11"},{"t":"Advection fog","d":"warm moist air moves over a colder surface (land or sea) whose temperature is below the air's dew point. Land and sea; any time of day or night. Coastal Bengal and Orissa winter fogs = advection + radiation; Brahmaputra valley, Sundarbans, coastal belts and peninsular hills.","s":"Met 7","ch":"Visibility and Fog","sec":"Other fogs (p.72)","h":"chapters/met-07.html#n-other-fogs-p-72"},{"t":"Adverse aileron yaw (yaw due to roll)","d":"rolling right, the down-going left aileron adds lift and induced drag on the left wing → the nose yaws left, away from the turn.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Secondary effects (2-39)","h":"chapters/hb-06.html#n-secondary-effects-2-39"},{"t":"Adverse pressure gradient","d":"behind the transition point velocity falls and pressure rises; this leads to separation and adds to form drag.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Transition, separation and the creation of lift (2-12)","h":"chapters/hb-02.html#n-transition-separation-and-the-creation-of-lift-2-12"},{"t":"Aerobatics","d":"licensed pilot (or trainee with an instructor); passengers' written consent; everyone strapped in; complete the manoeuvre by 600 m (2,000 ft) AGL (or higher if the C of A says). Not hazardous to traffic; not within 2 NM of an aerodrome perimeter below 1,800 m (6,000 ft); not over a city, town, village or populous area, nor over a public gathering unless the promoters applied in writing to the DG.","s":"Reg 4","ch":"Rules of the Air","sec":"General rules (p.78–81)","h":"chapters/reg-04.html#n-general-rules-p-78-81"},{"t":"Aerodrome","d":"defined area on land or water (with buildings and equipment) for arrival, departure and surface movement of aircraft. Aerodrome elevation = elevation of the highest point of the landing area.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aerodrome areas (p.4–36)","h":"chapters/reg-01.html#n-aerodrome-areas-p-4-36"},{"t":"Aerodrome traffic","d":"all traffic on the manoeuvring area and all aircraft in the vicinity (in, entering or leaving the circuit). Air traffic: all aircraft in flight or on the manoeuvring area.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Airspace and ATS (p.5–35)","h":"chapters/reg-01.html#n-airspace-and-ats-p-5-35"},{"t":"Aerodrome warning","d":"by AMOs, weather affecting aircraft on the ground and facilities (picketing, mooring); validity ≤ 4 h. Wind ≥ 30 kt, or direction of a 20-kt wind changing by 45°; squall, TC, DS, SS, TS, hail, frost, snow, hoar frost/rime, freezing precipitation, rising sand/dust, VA, tsunami.","s":"Met 21","ch":"Met Services for Aviation","sec":"Warnings (p.200)","h":"chapters/met-21.html#n-warnings-p-200"},{"t":"Aerodynamic centre (AC)","d":"the point about which the pitching moment stays constant with AoA; the point where all changes of lift effectively act. Below about 0.4 Mach it is at 25% chord for any aerofoil, whatever its camber, thickness or AoA. Calculations use the fixed AC instead of the moving CP.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Centre of pressure and aerodynamic centre (2-10)","h":"chapters/hb-01.html#n-centre-of-pressure-and-aerodynamic-centre-2-10"},{"t":"Aerodynamic pitching moments — anti-spin","d":"positive longitudinal stability (nose-down); damping in pitch; down elevator.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Moments in a spin (2-25 to 2-26)","h":"chapters/hb-03.html#n-moments-in-a-spin-2-25-to-2-26"},{"t":"Aerodynamic rolling moments — pro-spin","d":"sideslip with dihedral effect (relative air from the outer-wing side); auto-rotative rolling (damping in roll reverses above the stall); outer wing faster and at a more favourable CL; in-spin aileron.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Moments in a spin (2-25 to 2-26)","h":"chapters/hb-03.html#n-moments-in-a-spin-2-25-to-2-26"},{"t":"Aerodynamic symptom","d":"buffet — separated turbulent air striking the tailplane; the amount depends on where the tail sits in the wake. Trailing-edge flaps may reduce the buffet (more downwash over the tail).","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"What a stall is (2-20)","h":"chapters/hb-03.html#n-what-a-stall-is-2-20"},{"t":"Aerodynamic twisting moment (ATM)","d":"the blade CP lies ahead of the pitch-change axis, so lift turns the blade towards coarse pitch; more AoA → CP further forward → more ATM.","s":"Handbook 9","ch":"Propellers","sec":"Forces on a blade (2-59)","h":"chapters/hb-09.html#n-forces-on-a-blade-2-59"},{"t":"Aerodynamic yawing moments — anti-spin","d":"fin and rudder behind the CG (directional stability), damping in yaw, out-spin rudder (in-spin rudder is pro-spin; vertical surfaces ahead of the CG are pro-spin).","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Moments in a spin (2-25 to 2-26)","h":"chapters/hb-03.html#n-moments-in-a-spin-2-25-to-2-26"},{"t":"Aerodynamically assisted","d":"tabs and balances (chapter 6).","s":"Handbook 11","ch":"Landing Gear, Brakes, Tyres and Powered Controls","sec":"Flight-control systems (3-14)","h":"chapters/hb-11.html#n-flight-control-systems-3-14"},{"t":"Aerodyne","d":"support derived dynamically from surfaces moving relative to the air: aeroplanes, helicopters, gyroplanes, gliders and kites.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aircraft and their kinds (p.3–38)","h":"chapters/reg-01.html#n-aircraft-and-their-kinds-p-3-38"},{"t":"Aerofoil","d":"a shape that produces lift. Chord line: straight line from leading edge (LE) to trailing edge (TE); chord: its length. Root chord Cr, tip chord Ct, mean chord c̄. Span b: tip to tip. Wing area S = chord × span.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Aeroplane","d":"power-driven heavier-than-air, lift chiefly from surfaces that remain fixed. Glider: the same but non-power-driven. Airship: power-driven lighter-than-air. Helicopter: heavier-than-air, supported by power-driven rotors on substantially vertical axes.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aircraft and their kinds (p.3–38)","h":"chapters/reg-01.html#n-aircraft-and-their-kinds-p-3-38"},{"t":"Aeroplane reference field length","d":"minimum length at MTOM, sea level, ISA, nil wind, zero slope.","s":"Nav 15","ch":"Performance","sec":"Declared distances","h":"chapters/nav-15.html#n-declared-distances"},{"t":"Aft CG","d":"less stable, lighter controls, lower stall speed but risk of stall/spin (flat spin) recovery problems, overstress risk; rapid rotation on take-off; range and endurance reduced if grossly outside; glide hard to sustain.","s":"Nav 14","ch":"Mass and Balance","sec":"CG position effects","h":"chapters/nav-14.html#n-cg-position-effects"},{"t":"Aileron droop","d":"on the ground, controls neutral, ailerons hang slightly below the wing line; in flight the upper-surface suction lifts them into line. Some types droop both ailerons with the flaps to add flap area.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Primary controls (2-38)","h":"chapters/hb-06.html#n-primary-controls-2-38"},{"t":"Aileron reversal","d":"ailerons near the tips on a flexible wing; at high IAS a down-going aileron twists the wing nose-down, so the tip loses more lift than the aileron adds → roll the opposite way. Most likely with fully powered controls. Cures: inboard ailerons (or spoilers) at high speed, stiffer wings.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Aeroelastic problems (2-57)","h":"chapters/hb-08.html#n-aeroelastic-problems-2-57"},{"t":"Aileron–rudder interconnect","d":"rudder moves automatically with aileron.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Secondary effects (2-39)","h":"chapters/hb-06.html#n-secondary-effects-2-39"},{"t":"AIP Amendment","d":"permanent change; consecutive serial numbers; AIRAC AMDT pages show an effective date; if none is due at the usual time, a NIL notification goes out via the monthly NOTAM list.","s":"Reg 10","ch":"Aeronautical Information Services","sec":"AIP (p.233–235)","h":"chapters/reg-10.html#n-aip-p-233-235"},{"t":"AIP Supplement","d":"temporary changes of long duration (3 months or more) and short-duration information with extensive text/graphics. Serial numbers consecutive per calendar year; kept while any part is valid; references the NOTAM it replaces; checklist at least monthly (via the monthly NOTAM list); printed on yellow pages; kept as the first item in each AIP part; errors or validity changes → a new supplement. If there isn't time to…","s":"Reg 10","ch":"Aeronautical Information Services","sec":"AIP (p.233–235)","h":"chapters/reg-10.html#n-aip-p-233-235"},{"t":"Air mass","d":"large body of air (thousands of km²) with nearly uniform horizontal and vertical distribution of temperature (density) and moisture. Moves with the wind and is modified by the surfaces it crosses.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Air masses (p.129–130)","h":"chapters/met-14.html#n-air-masses-p-129-130"},{"t":"Air Navigation Commission","d":"19 members appointed by the Council. Also Air Transport Committee, Legal Committee, Committee on Joint Support (9–11), Finance Committee (9–13), Committee on Unlawful Interference (15).","s":"Reg 2","ch":"International Organisations and Conventions","sec":"ICAO (p.45–47)","h":"chapters/reg-02.html#n-icao-p-45-47"},{"t":"Air pocket","d":"local up- or downdraught from warm/cool pockets or high/low pressure.","s":"Met 13","ch":"Thunderstorms","sec":"Air pockets, downbursts, microbursts (p.121–123)","h":"chapters/met-13.html#n-air-pockets-downbursts-microbursts-p-121-123"},{"t":"Air-mass (heat) TS","d":"intense surface heating + convergence in a low; also cold air over a warm sea. Random, relatively weak; afternoons over plains; night/morning in valleys and hills.","s":"Met 13","ch":"Thunderstorms","sec":"Types (p.112–113)","h":"chapters/met-13.html#n-types-p-112-113"},{"t":"Air-taxiing","d":"helicopter/VTOL above the aerodrome surface, normally in ground effect, below 20 kt (37 km/h) groundspeed.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Airspace and ATS (p.5–35)","h":"chapters/reg-01.html#n-airspace-and-ats-p-5-35"},{"t":"Aircraft","d":"any machine that can derive support in the atmosphere from the reactions of the air other than reactions of the air against the earth's surface (so a hovercraft is not an aircraft). Includes balloons (fixed or free), airships, kites, gliders and flying machines.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aircraft and their kinds (p.3–38)","h":"chapters/reg-01.html#n-aircraft-and-their-kinds-p-3-38"},{"t":"Aircraft","d":"any device intended for flight in the air (gliders, aeroplanes, helicopters, balloons). Aerofoil: a structure made to produce lift by moving through air (wings, rotor blades, propellers). Fuselage: the body holding crew, cargo, passengers.","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Terms and loads (3-3)","h":"chapters/hb-10.html#n-terms-and-loads-3-3"},{"t":"AIREP / PIREP","d":"with air-ground data link, automated observations every 15 min en route and every 30 s during climb-out for the first 10 min. Special observations whenever SIGMET-criteria weather is met; wind shear, icing, turbulence passed to ATS ASAP; volcanic activity report submitted to the AMO on arrival → MWO of that region.","s":"Met 21","ch":"Met Services for Aviation","sec":"Observations and reports","h":"chapters/met-21.html#n-observations-and-reports"},{"t":"AIRMET","d":"SIGMET-type information for low-level flights, issued by the MWO for an FIR or sub-area (prepared by AMOs, exchanged with adjacent FIRs). GAMET: area forecast in abbreviated plain language for low-level flights.","s":"Met 21","ch":"Met Services for Aviation","sec":"SIGMET (p.199)","h":"chapters/met-21.html#n-sigmet-p-199"},{"t":"Albedo","d":"reflected ÷ incident radiation = reflecting power of the earth (~30%).","s":"Met 3","ch":"Temperature","sec":"Heat budget and albedo (p.31–32)","h":"chapters/met-03.html#n-heat-budget-and-albedo-p-31-32"},{"t":"ALERFA","d":"inquiries after INCERFA reveal nothing; cleared to land but not landed within 5 minutes of estimated landing time and no contact; efficiency impaired but forced landing not likely; or unlawful interference.","s":"Reg 5","ch":"Air Traffic Services","sec":"Alerting service and emergency phases (p.147–148)","h":"chapters/reg-05.html#n-alerting-service-and-emergency-phases-p-147-148"},{"t":"Alerting","d":"the tower alerts rescue and fire-fighting when an accident occurs on or near the aerodrome, when an aircraft's safety may be or has been impaired, when the crew asks, or whenever else desirable.","s":"Reg 8","ch":"Procedures for Aerodrome Control Service","sec":"Functions of the tower (p.205–206)","h":"chapters/reg-08.html#n-functions-of-the-tower-p-205-206"},{"t":"Alternate aerodrome","d":"where an aircraft may go when it is impossible or inadvisable to proceed to or land at the intended aerodrome:","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Alternate static source","d":"inside the cockpit (unpressurised aircraft only) or outside; selected by the pilot (switch) if the main source is blocked by ice etc. Cabin pressure is lower than outside (airflow over the cabin), so on the alternate source:","s":"Nav 17","ch":"Air Data Systems","sec":"The pitot-static system","h":"chapters/nav-17.html#n-the-pitot-static-system"},{"t":"Altimeter","d":"an aneroid barometer graduated in altitude, with a sub-scale for the pressure setting.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Measurement (p.15)","h":"chapters/met-02.html#n-measurement-p-15"},{"t":"Altimeter","d":"rapid height changes beat the capsule's response (hysteresis); plus temperature errors (colder than ISA → reads too high). Don't trust it for terrain clearance.","s":"Met 16","ch":"CAT and Mountain Waves","sec":"Turbulence and altimetry (p.151)","h":"chapters/met-16.html#n-turbulence-and-altimetry-p-151"},{"t":"Altimetry system error (ASE)","d":"indicated altitude (correct setting) minus pressure altitude of the undisturbed air.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Vertical references (p.8–36)","h":"chapters/reg-01.html#n-vertical-references-p-8-36"},{"t":"Altitude","d":"vertical distance from MSL. Height: from a specified datum (e.g. ground). Elevation: of a point on the earth's surface, from MSL.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Altimetry definitions (p.17)","h":"chapters/met-02.html#n-altimetry-definitions-p-17"},{"t":"Altitude","d":"higher → less dense. Temperature: warmer → less dense. Humidity: humid air is lighter (minor factor).","s":"Met 4","ch":"Air Density","sec":"Factors affecting density (p.38)","h":"chapters/met-04.html#n-factors-affecting-density-p-38"},{"t":"Altitude","d":"vertical distance from MSL. Height: from a specified datum. Elevation: of a point on or affixed to the earth, from MSL.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Vertical references (p.8–36)","h":"chapters/reg-01.html#n-vertical-references-p-8-36"},{"t":"Altitude","d":"climbing at constant TAS → IAS falls → AoA rises → Di rises; at constant IAS, Di is constant.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Factors affecting induced drag (2-17)","h":"chapters/hb-02.html#n-factors-affecting-induced-drag-2-17"},{"t":"Altitude","d":"the aircraft stalls at the same IAS at any height (density alone), so stalling TAS increases.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Basic stalling speed and what changes it (2-21)","h":"chapters/hb-03.html#n-basic-stalling-speed-and-what-changes-it-2-21"},{"t":"Ambient temperature","d":"temperature of the surroundings.","s":"Met 3","ch":"Temperature","sec":"Definitions (p.28)","h":"chapters/met-03.html#n-definitions-p-28"},{"t":"Ana (unstable) warm front","d":"CU/CB embedded in the layer cloud → bursts of heavy rain.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Warm front (p.133–134)","h":"chapters/met-14.html#n-warm-front-p-133-134"},{"t":"Ana cold front","d":"slope ~1:50, > 30 kt; warm air rises, unstable; CU/CB, violent TS, hail, short showers in a 100–150 km belt; sky clears rapidly after passage; isolated showers behind.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Cold front (p.132–133)","h":"chapters/met-14.html#n-cold-front-p-132-133"},{"t":"Anabatic","d":"daytime upslope wind (heated slope); weak, masked by convection; stronger when funnelled = valley wind; helped by sea breeze on coasts.","s":"Met 6","ch":"Winds","sec":"Local winds (p.55–58)","h":"chapters/met-06.html#n-local-winds-p-55-58"},{"t":"Aneroid barometer","d":"less accurate but convenient, widely used.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Measurement (p.15)","h":"chapters/met-02.html#n-measurement-p-15"},{"t":"Angle of climb","d":"between horizontal and flight path. Angle of attack: between relative airflow and chord. Climb gradient = height gained ÷ horizontal distance × 100%.","s":"Nav 15","ch":"Performance","sec":"Terms","h":"chapters/nav-15.html#n-terms"},{"t":"Angle of incidence","d":"between the chord line and the aircraft's longitudinal datum (fixed). Angle of attack: between the chord line and the relative airflow (varies).","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Anti-balance tab","d":"moves the same way as the surface; increases stick force (more feel) and effectiveness.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Aerodynamic balance (2-40)","h":"chapters/hb-06.html#n-aerodynamic-balance-2-40"},{"t":"Anti-skid","d":"maximum braking without locking. Senses rapid wheel deceleration (flywheel inertia or electrical sensors) and releases pressure at the onset of a skid, then reapplies — brake modulation. Electrical systems improve braking ~15%. Usually inoperative below ~20 kt.","s":"Handbook 11","ch":"Landing Gear, Brakes, Tyres and Powered Controls","sec":"Brakes (3-11)","h":"chapters/hb-11.html#n-brakes-3-11"},{"t":"AoA","d":"as it rises the BL loses energy to friction and the separation point moves forward, until CL falls.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Lift curves and factors affecting CL (2-13 to 2-14)","h":"chapters/hb-02.html#n-lift-curves-and-factors-affecting-cl-2-13-to-2-14"},{"t":"AoA","d":"at low AoA drag is mostly parasite. Shape: thin, low-camber high-speed sections have the lowest CD; low-drag sections put maximum thickness 40–50% aft of the LE to keep laminar flow over more of the wing. Rough LE: immediate transition, more skin friction.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Factors affecting CD (2-17)","h":"chapters/hb-02.html#n-factors-affecting-cd-2-17"},{"t":"Apparent solar day","d":"between two transits of the true sun (varies 23 h 44 min – 24 h 14 min, because the orbit is elliptical, not because rotation varies).","s":"Nav 1","ch":"The Solar System","sec":"Year and day","h":"chapters/nav-01.html#n-year-and-day"},{"t":"Approach","d":"sequencing, vectoring to a pilot-interpreted aid, and surveillance radar approaches. Aerodrome: surveillance radar as an approach monitor; surface movement radar for ground traffic.","s":"Reg 9","ch":"Use of ATS Surveillance Systems","sec":"Radar services (p.223–224)","h":"chapters/reg-09.html#n-radar-services-p-223-224"},{"t":"Apron","d":"for loading/unloading, fuelling, parking or maintenance. Aircraft stand: designated parking area on an apron.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aerodrome areas (p.4–36)","h":"chapters/reg-01.html#n-aerodrome-areas-p-4-36"},{"t":"Area rule","d":"much of the transonic drag rise is interference drag; make the total cross-sectional area change smoothly along the aircraft → \"waist\" (coke-bottle) the fuselage where the wings and tail join.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Designs for high-speed flight (2-53 to 2-54)","h":"chapters/hb-08.html#n-designs-for-high-speed-flight-2-53-to-2-54"},{"t":"ARFOR","d":"area forecast (coded/tabular): upper winds/temps, sig weather, cloud, freezing level, turbulence, icing, jet, tropopause, max wind, wind shear, warnings.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"Arm (balance arm)","d":"distance from the datum to a mass's CG. Moment = mass × arm. CG = total moment ÷ total mass.","s":"Nav 14","ch":"Mass and Balance","sec":"Definitions","h":"chapters/nav-14.html#n-definitions"},{"t":"Art 1 Sovereignty","d":"every State has complete and exclusive sovereignty over the airspace above its territory. Art 2 Territory: land areas and territorial waters adjacent.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 10","d":"landing/departure at a designated customs airport may be required.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 11","d":"a State's air regulations apply to all aircraft equally, regardless of nationality.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 12 Rules of the Air","d":"every aircraft over a State follows that State's rules; aircraft carrying its nationality mark follow them wherever they are; over the high seas the rules are those established under the Convention (Annex 2).","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 15 Airport charges","d":"facilities open to all; charges to foreign aircraft not higher than to national aircraft.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 16","d":"authorities may search aircraft on landing or departure and inspect documents.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 17","d":"aircraft have the nationality of the State of registry. Art 18: no dual registration (registration may be transferred). Art 19: registration under national law. Art 20: must bear nationality and registration marks. Art 21: report registration/ownership to ICAO.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 25","d":"assist aircraft in distress. Art 26 Accident investigation: the State of occurrence investigates; the State of registry may appoint observers and receives the report.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 27","d":"aircraft in flight cannot be seized for patent claims. Art 28: States provide airports, navigation, met, radio, charts to Convention standards.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 3","d":"military, customs and police aircraft = state aircraft; they may not overfly or land in another State without special agreement.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 30","d":"radio licensed by the State of registry, used only by licensed flight crew. Art 31: C of A issued or rendered valid by the State of registry. Art 32: crew licences issued or rendered valid by the State of registry; a State may refuse to recognise licences given to its own nationals by another State for flight over its territory.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 33","d":"certificates and licences of the State of registry are recognised by others if issued to at least ICAO minimum standards.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 37","d":"ICAO adopts SARPs. Art 38 Departures from standards: a State that cannot comply gives immediate notification to ICAO; after an amendment, notice to the Council within 60 days; the Council notifies all States.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 39–40","d":"non-compliant certificates/licences must be endorsed; endorsed ones fly internationally only with permission of the States entered.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 4","d":"no misuse of civil aviation.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 41","d":"airworthiness standards don't apply to prototypes submitted within 3 years of adoption. Art 42: licensing standards don't apply to licences first issued within 1 year of adoption, but do apply to all licences still valid 5 years after.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 5 Non-scheduled flights","d":"may fly into/across and make non-traffic stops without prior permission (1st and 2nd freedoms), but the State may require landing, routes or permission.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 6 Scheduled services","d":"need special permission of the State.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 7 Cabotage","d":"a State may refuse foreign aircraft the right to carry traffic between two points within its own territory.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 8 Pilotless aircraft","d":"need special authorisation.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"Art 9 Prohibited areas","d":"for military necessity or public safety, applied uniformly to aircraft of other States.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Chicago Convention, 1944: key articles (p.39–45)","h":"chapters/reg-02.html#n-chicago-convention-1944-key-articles-p-39-45"},{"t":"AS, NS","d":"supercooled drops + ice → light to moderate.","s":"Met 12","ch":"Ice Accretion","sec":"Icing by cloud (p.108)","h":"chapters/met-12.html#n-icing-by-cloud-p-108"},{"t":"ASI compressibility error","d":"air brought to rest in the pitot tube is compressed, raising pitot pressure → ASI over-reads (IAS too high). Negligible at or below 300 kt TAS and ignored.","s":"Nav 17","ch":"Air Data Systems","sec":"Errors specific to the ASI and VSI","h":"chapters/nav-17.html#n-errors-specific-to-the-asi-and-vsi"},{"t":"ASI density error","d":"flying from high to low density, the ASI under-reads (dynamic pressure = ½ρV²). For the same IAS, TAS increases as density falls, and vice versa.","s":"Nav 17","ch":"Air Data Systems","sec":"Errors specific to the ASI and VSI","h":"chapters/nav-17.html#n-errors-specific-to-the-asi-and-vsi"},{"t":"ASI principle","d":"pitot (total) pressure = ½ ρ V² + S; ASI measures total − static = dynamic pressure. By Bernoulli the total pressure in a streamline flow is the same everywhere, so the pitot head can sit anywhere in the flow; the static source must sense true ambient pressure.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Density and pressures (2-5)","h":"chapters/hb-01.html#n-density-and-pressures-2-5"},{"t":"Aspect ratio","d":"lower AR → stronger tip vortices and induced downwash → lower effective AoA → lower CL at a given AoA. Higher AR: steeper curve, slightly higher CLmax, lower stalling AoA. An infinite wing has no induced downwash.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Lift curves and factors affecting CL (2-13 to 2-14)","h":"chapters/hb-02.html#n-lift-curves-and-factors-affecting-cl-2-13-to-2-14"},{"t":"Aspect ratio","d":"Di ∝ 1/AR — doubling AR halves Di; infinite AR → zero Di.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Factors affecting induced drag (2-17)","h":"chapters/hb-02.html#n-factors-affecting-induced-drag-2-17"},{"t":"Assembly","d":"highest body, all contracting States, one vote each, meets at least once in 3 years.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"ICAO (p.45–47)","h":"chapters/reg-02.html#n-icao-p-45-47"},{"t":"Asymmetric blade effect (P-factor)","d":"at high AoA (take-off, slow flight) the down-going blade meets the air at a larger AoA and gives more thrust than the up-going blade → yaw left. Worst at low speed, high power, high AoA.","s":"Handbook 9","ch":"Propellers","sec":"Propeller effects on the aircraft (2-60) — clockwise propeller seen from behind","h":"chapters/hb-09.html#n-propeller-effects-on-the-aircraft-2-60-clockwise-propeller-seen-from-behind"},{"t":"At Mcrit (book example M 0.81)","d":"flow over the top at maximum camber reaches M 1 → a normal shockwave on the upper surface (none underneath yet, flow still subsonic there). CL maximum; CP moves back a little.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"What happens as Mach number rises (2-50)","h":"chapters/hb-08.html#n-what-happens-as-mach-number-rises-2-50"},{"t":"At the start of final approach","d":"significant changes in mean surface wind (as components: headwind 10 kt, tailwind 2 kt, crosswind 5 kt); wind shear/turbulence on final; visibility/RVR and trend.","s":"Reg 7","ch":"Separation in the Vicinity of Aerodromes","sec":"Information for arriving aircraft (p.200–201)","h":"chapters/reg-07.html#n-information-for-arriving-aircraft-p-200-201"},{"t":"ATFM","d":"balances demand with capacity. AAI's Central ATFM: Central Command Centre at Delhi with Flow Management Positions; phase I at 6 airports (Delhi, Mumbai, Bengaluru, Chennai, Kolkata, Hyderabad, ~60% of traffic), phase II 30 more.","s":"Reg 5","ch":"Air Traffic Services","sec":"ATC service (p.142–144)","h":"chapters/reg-05.html#n-atc-service-p-142-144"},{"t":"ATIS","d":"continuous broadcast of half-hourly current weather at important aerodromes.","s":"Met 21","ch":"Met Services for Aviation","sec":"Exchange of met messages (p.201)","h":"chapters/met-21.html#n-exchange-of-met-messages-p-201"},{"t":"ATIS","d":"automatic routine information for arriving and departing aircraft. VOLMET: met information for aircraft in flight (METAR, SPECI, TAF, SIGMET by continuous voice broadcast). D-ATIS / D-VOLMET: by data link.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Airspace and ATS (p.5–35)","h":"chapters/reg-01.html#n-airspace-and-ats-p-5-35"},{"t":"Atlantic Niño","d":"Atlantic warming weakens the monsoon; cooling strengthens it.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"G. Other systems influencing the SW monsoon","h":"chapters/met-30.html#n-g-other-systems-influencing-the-sw-monsoon"},{"t":"ATS reporting office","d":"unit that receives reports on ATS and flight plans submitted before departure.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"ATS surveillance system","d":"generic term for ADS-B, PSR, SSR or any comparable ground system that identifies aircraft.","s":"Reg 9","ch":"Use of ATS Surveillance Systems","sec":"Surveillance systems (p.221–223)","h":"chapters/reg-09.html#n-surveillance-systems-p-221-223"},{"t":"ATZ","d":"around an aerodrome to protect aerodrome traffic. Advisory airspace / advisory route: air traffic advisory service available.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Airspace and ATS (p.5–35)","h":"chapters/reg-01.html#n-airspace-and-ats-p-5-35"},{"t":"Autobrakes","d":"automatic braking on landing and RTO; on landing applies the selected deceleration when thrust levers are closed (book: < 85 kt for maximum); disengage below 20 kt, on anti-skid failure, or if thrust levers are advanced (go-around) or the pilot brakes.","s":"Handbook 11","ch":"Landing Gear, Brakes, Tyres and Powered Controls","sec":"Brakes (3-11)","h":"chapters/hb-11.html#n-brakes-3-11"},{"t":"Avoidance","d":"whatever the course, strong wind from port means the centre is ahead → alter course until the wind is from starboard and weakening.","s":"Met 18","ch":"Tropical Systems","sec":"Indian cyclones (p.162–163)","h":"chapters/met-18.html#n-indian-cyclones-p-162-163"},{"t":"Axis","d":"line of maximum speed; core = tube around it. Speed along the axis is not uniform: centres of maximum speed = jet streaks (located near ridges in a wavy jet). Where speed drops below 60 kt = breaks. Jets can split or merge.","s":"Met 15","ch":"Jet Streams","sec":"Definition (p.140)","h":"chapters/met-15.html#n-definition-p-140"},{"t":"B — Barometric","d":"sub-scale differs from the actual pressure at the point → wrong indication.","s":"Nav 18","ch":"Altimeter","sec":"Errors — \"BLIP PBT\"","h":"chapters/nav-18.html#n-errors-blip-pbt"},{"t":"B — Blockage","d":"indicates a constant altitude in climb or descent; the pointer freezes (static blocked at 9000 ft, aircraft at 10 000 ft → reads 9000 ft).","s":"Nav 18","ch":"Altimeter","sec":"Errors — \"BLIP PBT\"","h":"chapters/nav-18.html#n-errors-blip-pbt"},{"t":"Backing","d":"direction changes anticlockwise (090 → 060). Veering = clockwise (060 → 090). Example: 310° → 020° veers; 270° → 250° backs.","s":"Met 6","ch":"Winds","sec":"Backing and veering, Buys Ballot (p.47)","h":"chapters/met-06.html#n-backing-and-veering-buys-ballot-p-47"},{"t":"Balance tab","d":"on the control's TE, geared to move opposite to the surface; reduces stick force but reduces control effectiveness. Not pilot-operated: pilot moves surface, surface moves tab.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Aerodynamic balance (2-40)","h":"chapters/hb-06.html#n-aerodynamic-balance-2-40"},{"t":"Balanced field length","d":"V1 chosen so that ASDR = TODR; the shortest field length for given conditions, allowing the maximum take-off mass. Raising V1 lowers TODR and raises ASDR.","s":"Nav 15","ch":"Performance","sec":"Declared distances","h":"chapters/nav-15.html#n-declared-distances"},{"t":"Bank","d":"Vs × √(1/cos φ): 30° ×1.07, 45° ×1.2, 60° ×1.4, 75° ×2.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Basic stalling speed and what changes it (2-21)","h":"chapters/hb-03.html#n-basic-stalling-speed-and-what-changes-it-2-21"},{"t":"Barograph","d":"continuous record (daily or weekly).","s":"Met 2","ch":"Atmospheric Pressure","sec":"Measurement (p.15)","h":"chapters/met-02.html#n-measurement-p-15"},{"t":"Base turn","d":"turn between outbound and final track, tracks not reciprocal. Procedure turn: turn away then opposite turn to intercept the reciprocal. Racetrack: to lose height or establish inbound when reversal entry is impractical. Reversal procedure: to reverse direction in the initial segment.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Approaches and runways (p.16–19)","h":"chapters/reg-01.html#n-approaches-and-runways-p-16-19"},{"t":"Basic empty mass (BEM)","d":"aeroplane + unusable fuel and fluids, engine/APU oil, fire extinguishers, pyrotechnics, emergency oxygen, supplementary electronics (from the latest weighing schedule).","s":"Nav 14","ch":"Mass and Balance","sec":"Mass terms","h":"chapters/nav-14.html#n-mass-terms"},{"t":"Basic stalling speed (VsB)","d":"the speed below which a clean aircraft, at a stated weight, with engines throttled back, can no longer maintain straight and level flight. From L = CL½ρV²S: Vs = √(W ÷ (CLmax ½ρS)).","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Basic stalling speed and what changes it (2-21)","h":"chapters/hb-03.html#n-basic-stalling-speed-and-what-changes-it-2-21"},{"t":"Before entering the circuit or starting the approach","d":"runway, surface wind, QNH (and QFE as above).","s":"Reg 8","ch":"Procedures for Aerodrome Control Service","sec":"Information from the tower (p.208–211)","h":"chapters/reg-08.html#n-information-from-the-tower-p-208-211"},{"t":"Before take-off","d":"significant changes in wind, temperature, visibility/RVR, and significant weather in the take-off/climb-out area (CB/TS, moderate or severe turbulence, wind shear, hail, icing, severe squall line, freezing precipitation, mountain waves, sand/dust storm, blowing snow, tornado, waterspout).","s":"Reg 8","ch":"Procedures for Aerodrome Control Service","sec":"Information from the tower (p.208–211)","h":"chapters/reg-08.html#n-information-from-the-tower-p-208-211"},{"t":"Below Mcrit (0.4–0.75)","d":"pressure waves build up ahead, density rises; upwash becomes very steep; CL rises steadily; CP ≈ 30% chord.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"What happens as Mach number rises (2-50)","h":"chapters/hb-08.html#n-what-happens-as-mach-number-rises-2-50"},{"t":"Bending","d":"compression on top + tension underneath. Torsion = twisting (e.g. propeller drive). Torsional strength resists twisting.","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Terms and loads (3-3)","h":"chapters/hb-10.html#n-terms-and-loads-3-3"},{"t":"Bernoulli's theorem","d":"in steady streamline flow of an ideal fluid, pressure + kinetic + potential energy = constant; for aircraft, P + ½ ρ V² = constant. Where flow speeds up, static pressure falls (total pressure unchanged).","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Streamline flow and lift theories (2-6 to 2-7)","h":"chapters/hb-01.html#n-streamline-flow-and-lift-theories-2-6-to-2-7"},{"t":"Best endurance","d":"props — VMP; jets — VMD. Specific endurance = 1 ÷ (SFC × drag) → needs max L/D, minimum weight, least fuel flow.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Cruise, range and endurance (2-48)","h":"chapters/hb-07.html#n-cruise-range-and-endurance-2-48"},{"t":"Best range","d":"props — VMD; jets — 1.32 VMD at constant altitude; 1.19 VMD in a cruise climb.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Cruise, range and endurance (2-48)","h":"chapters/hb-07.html#n-cruise-range-and-endurance-2-48"},{"t":"Beyond Mcrit (≈ M 0.89)","d":"the upper shock moves aft towards the TE; a lower-surface shock forms; separation behind the upper shock gives negative lift aft → a sudden drop in CL (shock stall); CD keeps rising; CP forward.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"What happens as Mach number rises (2-50)","h":"chapters/hb-08.html#n-what-happens-as-mach-number-rises-2-50"},{"t":"Bishop's ring","d":"faint whitish ring, bluish inside, reddish-brown outside, radius ~22°; diffraction by fine dust high in the atmosphere (often volcanic).","s":"Met 10","ch":"Optical Phenomena","sec":"Other phenomena (p.97–98)","h":"chapters/met-10.html#n-other-phenomena-p-97-98"},{"t":"Black body","d":"a body that emits radiation (at its temperature) over a wide range of wavelengths.","s":"Met 3","ch":"Temperature","sec":"Insolation and radiation laws (p.30)","h":"chapters/met-03.html#n-insolation-and-radiation-laws-p-30"},{"t":"Blade angle (pitch)","d":"between the blade chord and the plane of rotation. Typical ranges: feathered 85–90°, in-flight (coarse) 20–35°, flight idle (fine) 10–12°, start locks 1–2°, ground idle 0°, reverse −2° to −8°.","s":"Handbook 9","ch":"Propellers","sec":"Pitch and angles (2-58)","h":"chapters/hb-09.html#n-pitch-and-angles-2-58"},{"t":"Blade angle of attack","d":"between the chord and the relative airflow (set by rotation + forward speed). Blade angle = helix angle + AoA.","s":"Handbook 9","ch":"Propellers","sec":"Pitch and angles (2-58)","h":"chapters/hb-09.html#n-pitch-and-angles-2-58"},{"t":"Blade twist","d":"sections near the tip travel further per revolution, so the blade angle is reduced towards the tip to keep a constant geometric pitch and even thrust along the blade.","s":"Handbook 9","ch":"Propellers","sec":"Pitch and angles (2-58)","h":"chapters/hb-09.html#n-pitch-and-angles-2-58"},{"t":"Blocking anticyclone","d":"near-stationary high that blocks migratory cyclones.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure patterns (p.21–22) (isobars at 2 hPa)","h":"chapters/met-02.html#n-pressure-patterns-p-21-22-isobars-at-2-hpa"},{"t":"Bora","d":"cold katabatic, Yugoslavia/NE Italy → Adriatic. Mistral: katabatic down the Rhône valley (France) to the Gulf of Lyons.","s":"Met 6","ch":"Winds","sec":"Named winds (p.61–62)","h":"chapters/met-06.html#n-named-winds-p-61-62"},{"t":"Boundary layer (BL)","d":"the layer next to the surface where flow speed is less than 99% of free-stream speed. Typically 2 mm thick at the LE, 20 mm at the TE. Its behaviour is set by surface condition and RN.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Subsonic airflow over an aerofoil (2-11)","h":"chapters/hb-02.html#n-subsonic-airflow-over-an-aerofoil-2-11"},{"t":"Boundary-layer suction","d":"removes the slow BL from the top surface.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Stall behaviour and how designers tame it (2-20)","h":"chapters/hb-03.html#n-stall-behaviour-and-how-designers-tame-it-2-20"},{"t":"Buran (Purga with snow)","d":"strong NE wind, Russia/central Asia, winter. Chinook: warm dry westerly, east of the Rockies.","s":"Met 6","ch":"Winds","sec":"Named winds (p.61–62)","h":"chapters/met-06.html#n-named-winds-p-61-62"},{"t":"Buys Ballot's law","d":"in the NH, stand with your back to the wind — low pressure is on your left, high on the right. Opposite in SH.","s":"Met 6","ch":"Winds","sec":"Backing and veering, Buys Ballot (p.47)","h":"chapters/met-06.html#n-backing-and-veering-buys-ballot-p-47"},{"t":"Cabotage","d":"traffic between two points in the same foreign State (Art 7).","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Exam traps","h":"chapters/reg-02.html#n-exam-traps"},{"t":"Calvus","d":"CB without cirrus top yet. Capillatus: CB with a distinct anvil → SH, TS, squalls, hail, virga.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Species (p.83)","h":"chapters/met-08.html#n-species-p-83"},{"t":"Camber up","d":"curve moves up and left, CLmax higher, stalling AoA lower, stall speed lower.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Lift curves and factors affecting CL (2-13 to 2-14)","h":"chapters/hb-02.html#n-lift-curves-and-factors-affecting-cl-2-13-to-2-14"},{"t":"Cambered aerofoil","d":"as AoA increases the suction peak grows and moves forward, TR grows and CP moves forward (nose-up, destabilising); CP is furthest forward at CLmax; at the stall TR drops and CP moves back. In normal use CP stays around 20–30% of chord.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Centre of pressure and aerodynamic centre (2-10)","h":"chapters/hb-01.html#n-centre-of-pressure-and-aerodynamic-centre-2-10"},{"t":"Canards","d":"longer moment arm, less trim drag, no control buzz.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Designs for high-speed flight (2-53 to 2-54)","h":"chapters/hb-08.html#n-designs-for-high-speed-flight-2-53-to-2-54"},{"t":"Carburettor icing","d":"pressure drop through the venturi (choke) and past the throttle butterfly → adiabatic cooling, plus fuel evaporation cooling → ice even in clear air at +30°C. Serious range +30°C to −10°C. Below −10°C negligible unless liquid water present; unlikely when RH < 60%.","s":"Met 12","ch":"Ice Accretion","sec":"Engine icing (p.109)","h":"chapters/met-12.html#n-engine-icing-p-109"},{"t":"Cardinal points","d":"N, S, E, W.","s":"Nav 2","ch":"The Earth","sec":"Longitude and meridians","h":"chapters/nav-02.html#n-longitude-and-meridians"},{"t":"Castellanus","d":"CI/CC/AC with turret-like cumuliform tops in lines → mid-level instability.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Species (p.83)","h":"chapters/met-08.html#n-species-p-83"},{"t":"CAT","d":"bumpiness at high altitude in cloud-free air (or in cirrus), where air moving at very different speeds meets.","s":"Met 16","ch":"CAT and Mountain Waves","sec":"Clear Air Turbulence (p.147–148)","h":"chapters/met-16.html#n-clear-air-turbulence-p-147-148"},{"t":"Cat I","d":"DH not lower than 60 m (200 ft) and visibility ≥ 800 m or RVR ≥ 550 m.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Approaches and runways (p.16–19)","h":"chapters/reg-01.html#n-approaches-and-runways-p-16-19"},{"t":"Cat II","d":"DH below 60 m but not below 30 m (100 ft), RVR ≥ 300 m.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Approaches and runways (p.16–19)","h":"chapters/reg-01.html#n-approaches-and-runways-p-16-19"},{"t":"Cat III","d":"DH below 30 m (100 ft) or no DH, and RVR below 300 m or no RVR limit.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Approaches and runways (p.16–19)","h":"chapters/reg-01.html#n-approaches-and-runways-p-16-19"},{"t":"CB","d":"light to severe up to the −20°C level; below that severe icing not significant.","s":"Met 12","ch":"Ice Accretion","sec":"Icing by cloud (p.108)","h":"chapters/met-12.html#n-icing-by-cloud-p-108"},{"t":"CB/TS coverage","d":"ISOL < 50% · OCNL 50–75% · FRQ > 75%.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"D. Miscellaneous terms","h":"chapters/met-30.html#n-d-miscellaneous-terms"},{"t":"CDFA","d":"NPA final segment flown as a continuous descent, no level-off, from FAF altitude to about 15 m (50 ft) above threshold.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Approaches and runways (p.16–19)","h":"chapters/reg-01.html#n-approaches-and-runways-p-16-19"},{"t":"CDi ∝ 1/AR","d":"minimum induced drag needs maximum AR. Lower AR needs more AoA for the same lift.","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Effect of aspect ratio (2-30)","h":"chapters/hb-04.html#n-effect-of-aspect-ratio-2-30"},{"t":"Ceiling","d":"height of the lowest layer below 6000 m (20,000 ft) covering more than half the sky (≥ 5/8).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Reporting (p.80–82)","h":"chapters/met-08.html#n-reporting-p-80-82"},{"t":"Ceiling","d":"height of the base of the lowest cloud layer below 6,000 m (20,000 ft) covering more than half the sky.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Flight plans and times (p.13–35)","h":"chapters/reg-01.html#n-flight-plans-and-times-p-13-35"},{"t":"Celsius","d":"ice 0°C, boiling 100°C (international, aviation, science). Fahrenheit: 32°F and 212°F (a few English-speaking countries).","s":"Met 3","ch":"Temperature","sec":"Scales (p.27)","h":"chapters/met-03.html#n-scales-p-27"},{"t":"Centre of pressure (CP)","d":"the point through which the total reaction acts; its position depends on camber, CL and angle of attack. The book treats TR as roughly perpendicular to the chord.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Centre of pressure and aerodynamic centre (2-10)","h":"chapters/hb-01.html#n-centre-of-pressure-and-aerodynamic-centre-2-10"},{"t":"Centrifugal force","d":"stretches the blade outwards. Torque bending force: bends it against the direction of rotation. Thrust bending force: bends it forward.","s":"Handbook 9","ch":"Propellers","sec":"Forces on a blade (2-59)","h":"chapters/hb-09.html#n-forces-on-a-blade-2-59"},{"t":"Centrifugal twisting moment (CTM)","d":"centrifugal force on the LE and TE masses turns the blade about its pitch-change axis towards fine pitch.","s":"Handbook 9","ch":"Propellers","sec":"Forces on a blade (2-59)","h":"chapters/hb-09.html#n-forces-on-a-blade-2-59"},{"t":"Certification requirements","d":"no abnormal pitch-up; roll and yaw obtainable with un-reversed controls; positive longitudinal control retained; stall-induced roll not more than 20°; stall warning at least 5 kt or 5% CAS above the stall.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Stall behaviour and how designers tame it (2-20)","h":"chapters/hb-03.html#n-stall-behaviour-and-how-designers-tame-it-2-20"},{"t":"CG","d":"point through which the weight acts (vertically, along the gravity vector); point of balance; the point the aircraft manoeuvres about and the three axes pass through. Must stay within forward and aft (and lateral) limits — the CG range/envelope.","s":"Nav 14","ch":"Mass and Balance","sec":"Definitions","h":"chapters/nav-14.html#n-definitions"},{"t":"Change of section","d":"more thickness and camber near the LE.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Stall behaviour and how designers tame it (2-20)","h":"chapters/hb-03.html#n-stall-behaviour-and-how-designers-tame-it-2-20"},{"t":"Changes","d":"all changes to an IFR flight plan or a controlled VFR flight must be reported as soon as practicable; for other VFR flights, significant changes. Incorrect fuel endurance or persons on board at departure is a significant change.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Adherence, changes and deviations","h":"chapters/nav-16.html#n-adherence-changes-and-deviations"},{"t":"Changes","d":"IFR and controlled VFR flights report all changes; other VFR report significant changes. Wrong endurance or persons on board at departure is a significant change.","s":"Reg 4","ch":"Rules of the Air","sec":"Flight plans (p.83–84)","h":"chapters/reg-04.html#n-flight-plans-p-83-84"},{"t":"Character of echoes","d":"EYE (eye wall of a TC), SPRL BAND (spiral band), SQL LN (squall line ≥ 60 km long, length:width ≈ 10:1), BRKN LN broken line, SLD area fully covered, BRKN 4/8–7/8 covered, SCT 1/8–4/8, WDLY SCT < 1/8, ISLTD isolated solid echo, ECHO ALOFT seen only at elevations above the beam width.","s":"Met 27","ch":"Radar Report, SIGMET and Satellite Bulletin","sec":"RAREP — radar report (p.255–257)","h":"chapters/met-27.html#n-rarep-radar-report-p-255-257"},{"t":"CI, CS, CC","d":"ice crystals → negligible icing.","s":"Met 12","ch":"Ice Accretion","sec":"Icing by cloud (p.108)","h":"chapters/met-12.html#n-icing-by-cloud-p-108"},{"t":"Circling approach","d":"extension of an IAP giving visual circling before landing.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Approaches and runways (p.16–19)","h":"chapters/reg-01.html#n-approaches-and-runways-p-16-19"},{"t":"Circular motion","d":"angular velocity ω = v / r; centripetal acceleration = v² / r; centripetal force = m v² / r = W v² / (g r). Moment of inertia I = Σ m r². Angular momentum = I ω.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Laws (2-4)","h":"chapters/hb-01.html#n-laws-2-4"},{"t":"Circulation (Magnus effect)","d":"a non-spinning cylinder has equal flow above and below — no lift. Spinning it speeds the flow on one side and slows it on the other, moving the stagnation points, so pressure is lower on the fast side → lift. A rough surface drags more air round → more circulation → more lift (golf ball dimples).","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Streamline flow and lift theories (2-6 to 2-7)","h":"chapters/hb-01.html#n-streamline-flow-and-lift-theories-2-6-to-2-7"},{"t":"Clearance limit","d":"point to which a clearance is granted. Downstream clearance: from a unit that is not the current controlling unit.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Airspace and ATS (p.5–35)","h":"chapters/reg-01.html#n-airspace-and-ats-p-5-35"},{"t":"Clearway","d":"area beyond the runway (under aerodrome control) over which the initial climb may be made; ≤ half TORA long; at least 75 m each side of the extended centre line (instrument runway); up-slope ≤ 1.25%; obstacle-free; may include the stopway; within the airport boundary; its centre line is imaginary, shown on diagrams/charts. Counts in TODA.","s":"Nav 15","ch":"Performance","sec":"Declared distances","h":"chapters/nav-15.html#n-declared-distances"},{"t":"Clearway","d":"area beyond the runway over which an aeroplane may make part of its initial climb. Stopway: area beyond the TORA prepared for stopping after an abandoned take-off.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aerodrome areas (p.4–36)","h":"chapters/reg-01.html#n-aerodrome-areas-p-4-36"},{"t":"Climb","d":"find the distance gone in the climb; subtract from the stage length → distance left in cruise.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Principles of fuel planning (p.278)","h":"chapters/nav-16.html#n-principles-of-fuel-planning-p-278"},{"t":"Climbing/descending through another's level, same track","d":"15 min; 10 min with frequent fixing; 5 min if the level change starts within 10 min of the second aircraft reporting over an exact reporting point.","s":"Reg 6","ch":"Separation Methods and Minima","sec":"Longitudinal separation by time (p.172–176)","h":"chapters/reg-06.html#n-longitudinal-separation-by-time-p-172-176"},{"t":"Climbing/descending, same track","d":"10 NM, one aircraft maintaining level, simultaneous readings.","s":"Reg 6","ch":"Separation Methods and Minima","sec":"Longitudinal separation by DME/GNSS distance (p.176–179)","h":"chapters/reg-06.html#n-longitudinal-separation-by-dme-gnss-distance-p-176-179"},{"t":"CLmax boundary","d":"curved lines (top and bottom) — maximum lift/load factor at each EAS. Pulling beyond it stalls the aircraft but does not overstress it. Where it meets n = 1 is the basic stalling speed.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Manoeuvre envelope (2-56)","h":"chapters/hb-08.html#n-manoeuvre-envelope-2-56"},{"t":"Closed system — constant delivery","d":"pump output ∝ RPM whether needed or not; an automatic cut-out valve returns fluid to the reservoir at full pressure; an accumulator boosts pressure when low.","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Hydraulics — principles (3-6)","h":"chapters/hb-10.html#n-hydraulics-principles-3-6"},{"t":"Closed system — constant pressure (variable volume)","d":"the pump varies its delivery to hold pressure; needs a pressure switch but no accumulator.","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Hydraulics — principles (3-6)","h":"chapters/hb-10.html#n-hydraulics-principles-3-6"},{"t":"Closing","d":"an arrival report in person, by RTF or data link, at the earliest moment after landing, for any flight whose plan covered the whole flight or the rest of it to destination.","s":"Reg 4","ch":"Rules of the Air","sec":"Flight plans (p.83–84)","h":"chapters/reg-04.html#n-flight-plans-p-83-84"},{"t":"Cloud","d":"visible aggregate of water droplets or ice particles, formed by adiabatic lifting and cooling until WV condenses (or deposits directly as ice). Height of condensation = lifting condensation level (LCL).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Clouds: formation and classification (p.77)","h":"chapters/met-08.html#n-clouds-formation-and-classification-p-77"},{"t":"Cloud","d":"BKN/OVC base passes 30, 60, 150, 300, 450 m; amount below 450 m changes between SKC/FEW/SCT and BKN/OVC.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"SPECI criteria (p.230–231) — deterioration at once, improvement after 10 min","h":"chapters/met-25.html#n-speci-criteria-p-230-231-deterioration-at-once-improvement-after-10-min"},{"t":"Cloud base steps","d":"30 m (100 ft) up to 3000 m; 300 m above. Amounts FEW 1–2, SCT 3–4, BKN 5–7, OVC 8 octas; SKC clear; NSC no significant cloud. Layers: lowest regardless of amount; next if ≥ 3/8; next if ≥ 5/8; CB always. Height in hundreds of feet: SCT015 = 3–4/8 at 1500 ft; FEW020CB. Sky obscured: VVhhh (vertical visibility).","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Cloud burst","d":"very heavy rain/showers over an area in a short time. Flash flood: sudden rise of rivers/streams.","s":"Met 11","ch":"Precipitation","sec":"Snow, sleet and terms (p.104)","h":"chapters/met-11.html#n-snow-sleet-and-terms-p-104"},{"t":"Cloud discharge (sheet lightning)","d":"within the cloud. Air discharge: cloud to air.","s":"Met 10","ch":"Optical Phenomena","sec":"Atmospheric electricity and lightning (p.99–100)","h":"chapters/met-10.html#n-atmospheric-electricity-and-lightning-p-99-100"},{"t":"Cloud of operational significance","d":"base below 1500 m (5000 ft) or below the highest minimum sector altitude, whichever is greater (or any CB/TCU).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Reporting (p.80–82)","h":"chapters/met-08.html#n-reporting-p-80-82"},{"t":"Clouds","d":"by day they reflect sunlight (thin cirrostratus cuts some; thick low cloud/fog may cut all) → cooler days; by night they absorb outgoing radiation and their bases radiate back → cloudy nights are warmer.","s":"Met 3","ch":"Temperature","sec":"Diurnal variation of surface temperature (p.32–33)","h":"chapters/met-03.html#n-diurnal-variation-of-surface-temperature-p-32-33"},{"t":"CO₂","d":"from burning fuel/wood; high in industrial areas, negligible over poles and at height; large amounts dissolved in oceans; plants absorb CO₂, release O₂.","s":"Met 1","ch":"Atmosphere","sec":"CO₂, ozone and particles (p.3)","h":"chapters/met-01.html#n-co-ozone-and-particles-p-3"},{"t":"CODAR","d":"upper-air report from an aircraft (not a weather-reconnaissance aircraft), figure code.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"CODAR","d":"aircraft upper-air report; WINTEM = forecast wind/temp; ROBEX = outside India.","s":"Met 21","ch":"Met Services for Aviation","sec":"Exam traps","h":"chapters/met-21.html#n-exam-traps"},{"t":"Col","d":"between two highs and two lows; uniform pressure, light variable winds, mixed weather.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure patterns (p.21–22) (isobars at 2 hPa)","h":"chapters/met-02.html#n-pressure-patterns-p-21-22-isobars-at-2-hpa"},{"t":"Col","d":"two lows and two highs.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Exam traps","h":"chapters/met-02.html#n-exam-traps"},{"t":"Cold anticyclone","d":"forms over cold ground behind a departing cyclone; subsidence later warms it.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure patterns (p.21–22) (isobars at 2 hPa)","h":"chapters/met-02.html#n-pressure-patterns-p-21-22-isobars-at-2-hpa"},{"t":"Cold occlusion","d":"air behind the cold front colder than the cool air ahead → undercuts and lifts both; warm-front weather then cold-front showers; common in summer.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Occlusions and others (p.134–135)","h":"chapters/met-14.html#n-occlusions-and-others-p-134-135"},{"t":"Combined surfaces","d":"tailerons (all-moving tailplane halves: together for pitch, differentially for roll); elevons (delta-wing TE: together for pitch, separately for roll); ruddervators (V-tail: together for pitch, separately for yaw); flaperons (flaps + ailerons, where TE length is short).","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Secondary effects (2-39)","h":"chapters/hb-06.html#n-secondary-effects-2-39"},{"t":"Commercial air transport","d":"passengers, cargo or mail for remuneration. Aerial work: industrial/commercial work, not air transport. General aviation: everything else.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Operations and people (p.4–34)","h":"chapters/reg-01.html#n-operations-and-people-p-4-34"},{"t":"Common mark","d":"for aircraft of an international operating agency registered jointly by two or more States; symbols 4YA to 4YZ allotted by the ITU; the common mark is assigned to the common mark registering authority by ICAO.","s":"Reg 3","ch":"Aircraft Nationality and Registration Marks","sec":"Annex 7 basics (p.69)","h":"chapters/reg-03.html#n-annex-7-basics-p-69"},{"t":"Communications","d":"controlled flights keep a continuous air-ground voice watch; SELCAL satisfies this; the watch continues after CPDLC is established.","s":"Reg 4","ch":"Rules of the Air","sec":"ATC clearances and deviations (p.85–86)","h":"chapters/reg-04.html#n-atc-clearances-and-deviations-p-85-86"},{"t":"Compass direction (°C)","d":"measured from compass north — where the aircraft's compass actually points, disturbed by the aircraft's own magnetic fields.","s":"Nav 6","ch":"Compass and Directions","sec":"Three norths","h":"chapters/nav-06.html#n-three-norths"},{"t":"Composite separation","d":"vertical + horizontal combined, each element may be reduced to not less than half its normal value; only by regional agreement.","s":"Reg 6","ch":"Separation Methods and Minima","sec":"General (p.169)","h":"chapters/reg-06.html#n-general-p-169"},{"t":"Compressibility","d":"higher altitude → higher Mach number → lower CLmax → higher IAS stall speed; constant at first, rising markedly above about 20,000 ft.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Basic stalling speed and what changes it (2-21)","h":"chapters/hb-03.html#n-basic-stalling-speed-and-what-changes-it-2-21"},{"t":"Compression (ellipticity) ≈ 1/297","d":"(major axis − minor axis) / major axis. Satellite geodesy shows a slight pear shape, more mass in the SH.","s":"Nav 2","ch":"The Earth","sec":"Shape and size","h":"chapters/nav-02.html#n-shape-and-size"},{"t":"Computer","d":"calculates TAS, Mach number, corrected static pressure and corrected OAT; originates correction signals to transducers; drives displays; feeds navigation computers; controls pressurisation; gives inputs to the AFCS and engine fuel control units.","s":"Nav 17","ch":"Air Data Systems","sec":"Air data system","h":"chapters/nav-17.html#n-air-data-system"},{"t":"Conduction","d":"molecule-to-molecule by contact; important very close to the ground. (Air is a poor conductor.)","s":"Met 3","ch":"Temperature","sec":"Heat transfer (p.29–30)","h":"chapters/met-03.html#n-heat-transfer-p-29-30"},{"t":"Configuration","d":"high-lift devices raise CLmax → flaps lower Vs. Forward sweep raises Vs.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Basic stalling speed and what changes it (2-21)","h":"chapters/hb-03.html#n-basic-stalling-speed-and-what-changes-it-2-21"},{"t":"Constant-speed unit (CSU)","d":"the pilot sets RPM; the CSU (flyweight governor) varies the blade angle between the fine and coarse stops to hold it. Overspeed → blade angle increased (more torque absorbed); as TAS rises the blade angle rises and the AoA stays roughly constant.","s":"Handbook 9","ch":"Propellers","sec":"Fixed, variable and constant-speed propellers (2-59)","h":"chapters/hb-09.html#n-fixed-variable-and-constant-speed-propellers-2-59"},{"t":"Contamination","d":"lower stalling AoA and CLmax. Ice/snow: Vs +30%, lift −30%, drag +40%. Frost: Vs +15%. Rain: Vs up (extra water weight).","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Basic stalling speed and what changes it (2-21)","h":"chapters/hb-03.html#n-basic-stalling-speed-and-what-changes-it-2-21"},{"t":"Contour (isohypse)","d":"line of equal height of a pressure surface; acts like an isobar.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Contours and thickness (p.16)","h":"chapters/met-02.html#n-contours-and-thickness-p-16"},{"t":"Control-surface flutter","d":"control oscillation coupled with wing/tail bending and twisting — develops when the control's CG is behind its hinge.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Aeroelastic problems (2-57)","h":"chapters/hb-08.html#n-aeroelastic-problems-2-57"},{"t":"Controlled airspace","d":"Classes A, B, C, D and E.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Airspace and ATS (p.5–35)","h":"chapters/reg-01.html#n-airspace-and-ats-p-5-35"},{"t":"Controls in the transonic range","d":"a down-going control surface accelerates the flow (lowers local Mcrit), puts a shock ahead of itself, and separates the BL → less effectiveness. Control buzz: a shock near the hinge → rapid oscillation of the controls. Cures: vortex generators (re-attach flow behind the shock), all-moving tailplane, roll-control spoilers.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Effects of shockwaves (2-52)","h":"chapters/hb-08.html#n-effects-of-shockwaves-2-52"},{"t":"Convection","d":"hot fluid bodily moves to the colder part. Free convection = intense solar heating; forced convection = topography/mechanical lifting. >70% of earth is water → convection important.","s":"Met 3","ch":"Temperature","sec":"Heat transfer (p.29–30)","h":"chapters/met-03.html#n-heat-transfer-p-29-30"},{"t":"Convection (thermals)","d":"from ground heating; used by gliders; bumpiness; CU/CB with strong up- and downdraughts.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Vertical motion (p.75–76)","h":"chapters/met-08.html#n-vertical-motion-p-75-76"},{"t":"Convective cloud","d":"sharp-edged echoes; blurring of edges = first sign of decay; squall lines show as line echoes. Exceptionally intense echo or top reaching about −40 °C level → CB.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Cloud echoes (p.208–209)","h":"chapters/met-22.html#n-cloud-echoes-p-208-209"},{"t":"Convergence","d":"net horizontal inflow → ascent near the ground (aloft, can go up or down below the tropopause). Lows, cyclones, depressions, troughs → bad weather, better visibility (except in precipitation).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Convergence and divergence (p.76–78)","h":"chapters/met-08.html#n-convergence-and-divergence-p-76-78"},{"t":"Convergence","d":"zero on the chart; correct only at the equator.","s":"Nav 3","ch":"Projections","sec":"Mercator (direct)","h":"chapters/nav-03.html#n-mercator-direct"},{"t":"Convergency","d":"the angle of inclination between two meridians at a given latitude = the change of great-circle track between them. Zero at the equator, equal to d.long at the poles; varies as sin latitude.","s":"Nav 4","ch":"Convergency","sec":"Definitions","h":"chapters/nav-04.html#n-definitions"},{"t":"Conversion angle (CA)","d":"angle between the GC and the RL at either end = ½ convergency (maximum near the poles).","s":"Nav 4","ch":"Convergency","sec":"Definitions","h":"chapters/nav-04.html#n-definitions"},{"t":"Council","d":"36 States elected by the Assembly; President elected by the Council. Adopts SARPs.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"ICAO (p.45–47)","h":"chapters/reg-02.html#n-icao-p-45-47"},{"t":"CP movement","d":"tip lift is lost (tips are aft on a swept wing) → CP moves forward → shorter CP–CG arm → more nose-up.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Tip stall and pitch-up (2-23)","h":"chapters/hb-03.html#n-tip-stall-and-pitch-up-2-23"},{"t":"Creep","d":"the tyre slowly rotates on the rim — can tear a tube's valve; most likely on new tyres or with low pressure; checked by paint marks on tyre and rim; tubeless tyres are not affected.","s":"Handbook 11","ch":"Landing Gear, Brakes, Tyres and Powered Controls","sec":"Tyres (3-12)","h":"chapters/hb-11.html#n-tyres-3-12"},{"t":"Crepuscular rays","d":"dark bluish streaks radiating from the sun = shadows of clouds at/below the horizon.","s":"Met 10","ch":"Optical Phenomena","sec":"Other phenomena (p.97–98)","h":"chapters/met-10.html#n-other-phenomena-p-97-98"},{"t":"Critical angle of attack","d":"the AoA at which the flow over the wing breaks down. An aircraft always stalls at the same critical AoA, whatever its speed or attitude. Not all lift is lost there — just not enough to support the aircraft.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"What a stall is (2-20)","h":"chapters/hb-03.html#n-what-a-stall-is-2-20"},{"t":"Crossing","d":"everything else (45–135° and 225–315°).","s":"Reg 6","ch":"Separation Methods and Minima","sec":"Track definitions (p.172)","h":"chapters/reg-06.html#n-track-definitions-p-172"},{"t":"Crossing tracks, climbing/descending","d":"15 min; 10 min with ground aids or GNSS; 5 min if the level change starts within 10 min of the second aircraft reporting over the common point (third-party/CPDLC clearances get a restriction to ensure it).","s":"Reg 6","ch":"Separation Methods and Minima","sec":"Longitudinal separation by time (p.172–176)","h":"chapters/reg-06.html#n-longitudinal-separation-by-time-p-172-176"},{"t":"Cruise climb","d":"as fuel burns the drag curve drops, so best TAS/drag would need a lower speed; instead the aircraft climbs slowly at constant TAS (book: 1.19 VMD, IAS falling) — until about M 0.8, after which it holds altitude and lets TAS fall. Efficient but impractical in busy airspace.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Cruise climb and step climb (2-44)","h":"chapters/hb-07.html#n-cruise-climb-and-step-climb-2-44"},{"t":"Cruise relief pilot","d":"performs pilot tasks in cruise so PIC or co-pilot can rest.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Operations and people (p.4–34)","h":"chapters/reg-01.html#n-operations-and-people-p-4-34"},{"t":"Cruising levels","d":"flight levels at or above the lowest usable FL / above TA; altitudes below the lowest usable FL / at or below TA.","s":"Reg 4","ch":"Rules of the Air","sec":"General rules (p.78–81)","h":"chapters/reg-04.html#n-general-rules-p-78-81"},{"t":"Cumuliform","d":"CC, AC some turbulence; fair-weather CU and SC bumpy; CU, TCU, CB serious: severe turbulence, hail, up/downdraughts, gusts, icing, lightning. Turbulence up to 10–20 km around an active CB. Avoid landing/take-off in TS squalls. Hail can fall in clear air under the anvil.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Flying conditions (p.81–82)","h":"chapters/met-08.html#n-flying-conditions-p-81-82"},{"t":"Current flight plan","d":"including changes brought about by subsequent clearances.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Cyclostrophic","d":"strongly curved flow where Coriolis is negligible; PGF balances centripetal (ρV²/r). Good near the centre of a tropical revolving storm or a tornado (e.g. 2000 ft wind in an intense TRS).","s":"Met 6","ch":"Winds","sec":"Cyclostrophic, gradient, isallobaric, inertial winds (p.50–51)","h":"chapters/met-06.html#n-cyclostrophic-gradient-isallobaric-inertial-winds-p-50-51"},{"t":"d.lat (ch.lat)","d":"same hemisphere → subtract; opposite hemispheres → add (40°N to 30°S = 70°).","s":"Nav 2","ch":"The Earth","sec":"Change of latitude and longitude","h":"chapters/nav-02.html#n-change-of-latitude-and-longitude"},{"t":"d.long (ch.long)","d":"same hemisphere → subtract; opposite hemispheres → add, but if the sum exceeds 180° take 360° − sum (go the short way across 180°). Direction: anticlockwise seen from above N pole = east, clockwise = west.","s":"Nav 2","ch":"The Earth","sec":"Change of latitude and longitude","h":"chapters/nav-02.html#n-change-of-latitude-and-longitude"},{"t":"DA/H","d":"in a 3D approach, the point where a missed approach must be initiated if the visual reference is not established. DA from MSL, DH from threshold elevation.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Minimum altitudes (p.18–21)","h":"chapters/reg-01.html#n-minimum-altitudes-p-18-21"},{"t":"Datum","d":"point on the longitudinal axis (or its extension) from which all arms are measured (set by the manufacturer; may be ahead of the nose; small helicopters often 100 in ahead of the rotor mast to keep arms positive). Aft of datum = positive arm, forward = negative.","s":"Nav 14","ch":"Mass and Balance","sec":"Definitions","h":"chapters/nav-14.html#n-definitions"},{"t":"Day","d":"thermals deepen the friction layer and bring stronger upper wind down → surface wind stronger, gustier and veered towards the gradient wind (NH).","s":"Met 6","ch":"Winds","sec":"Diurnal variation of surface wind (p.53–54)","h":"chapters/met-06.html#n-diurnal-variation-of-surface-wind-p-53-54"},{"t":"Deep (super) stall","d":"on a swept wing the CP stays forward at the stall and the nose pitches up; with a high T-tail the mainplane's turbulent wake blankets the tail and the elevator becomes ineffective, holding the aircraft stalled; the high rate of descent raises the AoA further and recovery may be impossible. Causes: swept wing + T-tail. Cure: a stick pusher pushes the stick forward before the stall.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Types of stall (2-22)","h":"chapters/hb-03.html#n-types-of-stall-2-22"},{"t":"Delay","d":"30 minutes beyond EOBT (controlled flight) or 1 hour (uncontrolled) → amend the plan or file a new one and cancel the old.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Submission","h":"chapters/nav-16.html#n-submission"},{"t":"Density","d":"mass per unit volume (kg/m³). Pressure: force per unit area (N/m²).","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Physical terms (2-3)","h":"chapters/hb-01.html#n-physical-terms-2-3"},{"t":"Density altitude","d":"the altitude in ISA at which the prevailing density occurs.","s":"Met 4","ch":"Air Density","sec":"Definition and density altitude (p.37)","h":"chapters/met-04.html#n-definition-and-density-altitude-p-37"},{"t":"Density altitude","d":"PA corrected for non-ISA temperature ≈ PA + 118–120 ft × ISA deviation (e.g. PA 10 000, +12 °C → ≈ 12 000 ft; PA 0, 10 °C → −593 ft). DA is the PA at which the prevailing density occurs in ISA.","s":"Nav 10","ch":"DR Elements: Pressure and Altimetry","sec":"Altimeter settings and altitudes","h":"chapters/nav-10.html#n-altimeter-settings-and-altitudes"},{"t":"Denunciation","d":"written notification to ICAO as Depositary. Security conventions (Tokyo, Hague, Montreal 1971, 1988 Protocol, Beijing): 6 months. Montreal 1999: 90 days.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Liability conventions (p.54–56)","h":"chapters/reg-02.html#n-liability-conventions-p-54-56"},{"t":"Depression / cyclone","d":"intense low with 2 or more closed isobars at 2 hPa interval and strong winds.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"A. Synoptic systems","h":"chapters/met-30.html#n-a-synoptic-systems"},{"t":"Descent","d":"work out the descent path → time and distance.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Principles of fuel planning (p.278)","h":"chapters/nav-16.html#n-principles-of-fuel-planning-p-278"},{"t":"Destination alternate","d":"if it becomes impossible or inadvisable to land at the intended destination.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Detector unit (flux valve)","d":"three flux valves at 120°, pendulously mounted to stay horizontal, fixed in azimuth, mounted at a wing tip or fin top away from aircraft magnetism. It senses (not seeks) the magnetic meridian → works to higher latitudes.","s":"Nav 8","ch":"Magnetism and Compasses","sec":"Remote indicating (gyro-magnetic / slaved) compass","h":"chapters/nav-08.html#n-remote-indicating-gyro-magnetic-slaved-compass"},{"t":"DETRESFA","d":"wider inquiries fail and distress is probable; fuel considered exhausted or insufficient; efficiency impaired so a forced landing is likely; or a forced landing is about to happen or has happened.","s":"Reg 5","ch":"Air Traffic Services","sec":"Alerting service and emergency phases (p.147–148)","h":"chapters/reg-05.html#n-alerting-service-and-emergency-phases-p-147-148"},{"t":"Deviation","d":"angle between magnetic and compass north caused by metal, magnets and electrics in the aircraft. Compass north east of magnetic = easterly (+), west = westerly (−).","s":"Nav 6","ch":"Compass and Directions","sec":"Variation and deviation","h":"chapters/nav-06.html#n-variation-and-deviation"},{"t":"Dew point (DP)","d":"temperature to which air must be cooled at constant pressure to saturate it (with respect to water). Cooling below DP → condensation.","s":"Met 5","ch":"Humidity","sec":"Wet bulb, dew point, frost point (p.42)","h":"chapters/met-05.html#n-wet-bulb-dew-point-frost-point-p-42"},{"t":"DGCA","d":"the regulator, primarily safety: registration, airworthiness and C of A, licensing of pilots, AMEs, flight engineers and ATCOs, aerodrome and CNS/ATM certification, AOCs, accident prevention, amending rules/CARs to match ICAO, noise and emissions, dangerous goods approvals.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Indian organisations (p.53–54)","h":"chapters/reg-02.html#n-indian-organisations-p-53-54"},{"t":"Differential ailerons","d":"the up-going aileron moves through a larger angle than the down-going one → more drag on the up side, less on the down side.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Secondary effects (2-39)","h":"chapters/hb-06.html#n-secondary-effects-2-39"},{"t":"Digital data sets","d":"AIP, terrain, obstacle, aerodrome mapping, instrument flight procedure data sets. Aeronautical information products: AIP, AIC, NOTAM, charts, digital data sets.","s":"Reg 10","ch":"Aeronautical Information Services","sec":"Charts, pre- and post-flight (p.239–240)","h":"chapters/reg-10.html#n-charts-pre-and-post-flight-p-239-240"},{"t":"Dihedral","d":"upward angle of the wing (book measures it along the quarter-chord line) relative to the lateral axis. Sweepback: angle between the quarter-chord line and a line perpendicular to the root chord (the lateral axis).","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Dihedral effect","d":"in a sideslip the wing on the side of the slip meets the air at more AoA, gains lift and rolls the aircraft away from the slip → stabilising. Anhedral reduces it.","s":"Handbook 5","ch":"Stability","sec":"Lateral stability (2-36)","h":"chapters/hb-05.html#n-lateral-stability-2-36"},{"t":"Dip (inclination)","d":"angle of a freely suspended magnet below the horizontal. 0° at the magnetic equator, 90° at the magnetic poles. H is greatest at the magnetic equator and zero at the poles → compasses useless near the poles; a direct-reading compass is unreliable beyond ~70° N/S.","s":"Nav 8","ch":"Magnetism and Compasses","sec":"Earth's magnetism","h":"chapters/nav-08.html#n-earth-s-magnetism"},{"t":"Direction","d":"where the wind blows from (a southerly blows S → N). Given on 16 compass points or in degrees (10° steps), measured from True North (in met reports).","s":"Met 6","ch":"Winds","sec":"Basics (p.45)","h":"chapters/met-06.html#n-basics-p-45"},{"t":"Directional divergence","d":"a small sideslip grows until the aircraft is broadside on — from too little directional stability.","s":"Handbook 5","ch":"Stability","sec":"Coupled directional and lateral stability (2-37)","h":"chapters/hb-05.html#n-coupled-directional-and-lateral-stability-2-37"},{"t":"Directional: decreases","d":"the fin loses effectiveness; in a sideslip the stronger shock on the windward side yaws the aircraft away; worse with aft CG/rear engines.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Transonic and supersonic stability (2-55)","h":"chapters/hb-08.html#n-transonic-and-supersonic-stability-2-55"},{"t":"Disadvantages","d":"longer take-off/landing run and higher speeds, prone to tip stall, super stall, pitch-up and Mach tuck, less trailing-edge space for controls, lower CLmax, higher stall speed.","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Wing planforms (2-28)","h":"chapters/hb-04.html#n-wing-planforms-2-28"},{"t":"Disc brakes","d":"more contact area, better heat dissipation; single or multiple discs and callipers. Brake fade: efficiency falls when too hot. Brake drag: wrongly adjusted or air in the system.","s":"Handbook 11","ch":"Landing Gear, Brakes, Tyres and Powered Controls","sec":"Brakes (3-11)","h":"chapters/hb-11.html#n-brakes-3-11"},{"t":"Distrails","d":"clear lanes cut through cloud by exhaust heat.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Condensation trails (p.83–84)","h":"chapters/met-08.html#n-condensation-trails-p-83-84"},{"t":"Ditching","d":"forced landing on water.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Emergency and SAR words (p.8–31)","h":"chapters/reg-01.html#n-emergency-and-sar-words-p-8-31"},{"t":"Divergence","d":"net outflow (e.g. W wind 10 kt to the west of a station, 20 kt to the east) → subsidence. Anticyclones, ridges → fine weather, poor visibility.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Convergence and divergence (p.76–78)","h":"chapters/met-08.html#n-convergence-and-divergence-p-76-78"},{"t":"Divergence","d":"low torsional stiffness and the CP ahead of the flexural axis → lift twists the wing nose-up → more AoA → CP further forward → twist increases until the wing breaks. Nothing to do with control movement. Cures: stiffer wing (heavier), mass balance — engines mounted ahead of and below the wing — and shorter chord.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Aeroelastic problems (2-57)","h":"chapters/hb-08.html#n-aeroelastic-problems-2-57"},{"t":"DME","d":"arc of range around the station (slant range normally ignored). TACAN = military DME; VORTAC = VOR + TACAN co-located.","s":"Nav 13","ch":"In-flight Navigation","sec":"Fixes and position lines","h":"chapters/nav-13.html#n-fixes-and-position-lines"},{"t":"DME distance","d":"slant range. Change-over point (COP): where you switch from the VOR behind to the VOR ahead.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Navigation words (p.12–38)","h":"chapters/reg-01.html#n-navigation-words-p-12-38"},{"t":"DME/GNSS","d":"20 NM same level same/crossing track; 10 NM with leader 20 kt faster, climb/descent same track, reciprocal after passing.","s":"Reg 6","ch":"Separation Methods and Minima","sec":"Summary (p.179–180)","h":"chapters/reg-06.html#n-summary-p-179-180"},{"t":"Doldrums","d":"calm belt ~5°N–5°S between the trades; low pressure, cloud and rain = ITCZ.","s":"Met 6","ch":"Winds","sec":"Named winds (p.61–62)","h":"chapters/met-06.html#n-named-winds-p-61-62"},{"t":"Double white cross","d":"gliders operating.","s":"Reg 4","ch":"Rules of the Air","sec":"Visual ground signals (p.97–98)","h":"chapters/reg-04.html#n-visual-ground-signals-p-97-98"},{"t":"Downburst","d":"intense damaging downdraught > 4 km across.","s":"Met 13","ch":"Thunderstorms","sec":"Air pockets, downbursts, microbursts (p.121–123)","h":"chapters/met-13.html#n-air-pockets-downbursts-microbursts-p-121-123"},{"t":"Downwash change","d":"lift concentrated inboard → more downwash over the tailplane → less tail effectiveness → more pitch-up. Reduced by placing the tail in line with or below the wing.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Tip stall and pitch-up (2-23)","h":"chapters/hb-03.html#n-tip-stall-and-pitch-up-2-23"},{"t":"DR","d":"navigating by computation from airspeed, heading, wind and time alone. Errors accumulate with time (INS is also a DR system).","s":"Nav 9","ch":"Dead Reckoning","sec":"Terms","h":"chapters/nav-09.html#n-terms"},{"t":"Drag","d":"the sum of aerodynamic forces parallel and opposite to the direction of flight; two families — parasite and induced.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Parasite drag (2-15)","h":"chapters/hb-02.html#n-parasite-drag-2-15"},{"t":"Drag","d":"needs more AoA for the same lift → more downwash and induced drag. On approach raising the nose adds far more drag than lift → high rate of descent; some types add high-drag devices to bring VMD closer to the approach speed.","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Wing planforms (2-28)","h":"chapters/hb-04.html#n-wing-planforms-2-28"},{"t":"Draughts","d":"updraughts stronger and deeper (can suck up gliders); downdraughts strongest from mid-cloud down; height changes 3,000–5,000 ft; > 1 km wide.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"Drift","d":"angle from heading to track. Track right of heading = starboard (S); left = port (P). TR = HDG + S drift − P drift. WCA = drift applied the other way (drift 7°S ⇒ WCA 7°P).","s":"Nav 9","ch":"Dead Reckoning","sec":"Triangle of velocities","h":"chapters/nav-09.html#n-triangle-of-velocities"},{"t":"Dropping or spraying","d":"only under Rule 26 of the Aircraft Rules 1937 and as cleared by ATS. Parachute descents: only in emergency or by written order of the Central Government.","s":"Reg 4","ch":"Rules of the Air","sec":"General rules (p.78–81)","h":"chapters/reg-04.html#n-general-rules-p-78-81"},{"t":"Drum brakes","d":"pads pressed against the drum. Drawbacks: vibration if the drum distorts, water reduces effectiveness, poor heat dissipation (small area), thermal expansion → more pedal travel, grabbing from rust.","s":"Handbook 11","ch":"Landing Gear, Brakes, Tyres and Powered Controls","sec":"Brakes (3-11)","h":"chapters/hb-11.html#n-brakes-3-11"},{"t":"Dry air","d":"no WV at all (upper troposphere, stratosphere).","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Dry operating mass (DOM / BOM / APS)","d":"ready for a specific operation excluding usable fuel and traffic load — includes crew and their baggage, catering and removable passenger service equipment, potable water and lavatory chemicals, food and beverages.","s":"Nav 14","ch":"Mass and Balance","sec":"Mass terms","h":"chapters/nav-14.html#n-mass-terms"},{"t":"Drytra level","d":"so cold that contrails form even at 0% RH; about 2 km above the mintra level.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Condensation trails (p.83–84)","h":"chapters/met-08.html#n-condensation-trails-p-83-84"},{"t":"Ducts","d":"subsonic flow speeds up in a convergent duct and slows in a divergent one; supersonic flow speeds up in a divergent duct and slows in a convergent one (beyond M 1 the air expands into the extra area, density and pressure fall and Mach rises).","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Shockwaves (2-51)","h":"chapters/hb-08.html#n-shockwaves-2-51"},{"t":"Dust devil","d":"whirl over a hot spot; up to ~2 km high, ~10 m across; short-lived (willy-willy).","s":"Met 13","ch":"Thunderstorms","sec":"Tornado, waterspout, dust devil (p.124–125)","h":"chapters/met-13.html#n-tornado-waterspout-dust-devil-p-124-125"},{"t":"Dutch roll","d":"directional stability < lateral stability. Sideslip right → right wing gains AoA and is lifted strongly → its extra induced drag yaws the aircraft right → oscillating roll-and-yaw. More dangerous than spiral divergence. Prevented by yaw dampers; without one, correct with ailerons, not rudder.","s":"Handbook 5","ch":"Stability","sec":"Coupled directional and lateral stability (2-37)","h":"chapters/hb-05.html#n-coupled-directional-and-lateral-stability-2-37"},{"t":"Dynamic (wind) pressure","d":"extra pressure when air moves, exerted in the direction opposite to the flow.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Static and dynamic pressure (p.12)","h":"chapters/met-02.html#n-static-and-dynamic-pressure-p-12"},{"t":"Dynamic pressure = ½ ρ V²","d":"the kinetic energy of moving air turned into pressure when brought to rest in a pitot tube. Double the speed → 4× the dynamic pressure.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Density and pressures (2-5)","h":"chapters/hb-01.html#n-density-and-pressures-2-5"},{"t":"Dynamic stability","d":"the motion over time after the disturbance. Positive: oscillations die out. Neutral: steady oscillation. Negative: oscillations grow.","s":"Handbook 5","ch":"Stability","sec":"Dynamic stability (2-34)","h":"chapters/hb-05.html#n-dynamic-stability-2-34"},{"t":"eAIP","d":"AIP, AMDT, SUP and AIC in a format for screen display and printing.","s":"Reg 10","ch":"Aeronautical Information Services","sec":"AIP (p.233–235)","h":"chapters/reg-10.html#n-aip-p-233-235"},{"t":"EAT (expected approach time)","d":"when ATC expects an aircraft that has been delayed to leave the holding fix to complete its approach or landing.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"EET (estimated elapsed time)","d":"estimated time from one significant point to another.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Effective pitch","d":"the distance it actually advances in one revolution. Slip = geometric − effective pitch; zero slip would be 100% efficiency.","s":"Handbook 9","ch":"Propellers","sec":"Pitch and angles (2-58)","h":"chapters/hb-09.html#n-pitch-and-angles-2-58"},{"t":"El Niño","d":"unusual warming of the eastern tropical Pacific, the warm phase of ENSO (La Niña = cool phase), every 2–7 years; weak SE trades → weak Indian monsoon (severe Indian droughts occur in El Niño years, but not every El Niño gives drought); fewer cyclones in our region. La Niña → strong trades → active monsoon. Normally trades push warm water west and cause upwelling off Ecuador/Peru/Chile.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Elastic limit","d":"beyond it the body takes a permanent set and does not return to shape.","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Terms and loads (3-3)","h":"chapters/hb-10.html#n-terms-and-loads-3-3"},{"t":"Elliptical","d":"least induced drag; constant CL (≈ 1.0) root to tip — every section gives the same lift. Cons: hard to build, no stall warning, ailerons lose effect at the stall (whole span stalls together).","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Wing planforms (2-28)","h":"chapters/hb-04.html#n-wing-planforms-2-28"},{"t":"Em","d":"from the Indian Ocean (crosses the equator); south of 25°N in the monsoon; very humid, sultry, small diurnal range, good visibility except in showers.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Air masses over India (p.130–131)","h":"chapters/met-14.html#n-air-masses-over-india-p-130-131"},{"t":"Emergency landing","d":"give way to an aircraft known to be compelled to land.","s":"Reg 4","ch":"Rules of the Air","sec":"Right of way (p.80–81)","h":"chapters/reg-04.html#n-right-of-way-p-80-81"},{"t":"En-route alternate","d":"to land after an abnormal or emergency condition en route.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"ENR","d":"general rules (VFR, IFR, airspace classes, procedures, surveillance, altimeter setting, SUPPS, ATFM, flight plans, interception, unlawful interference, incidents); FIR/CTA/TMA; ATS, RNAV and helicopter routes, en-route holding; nav-aids and GNSS; navigation warnings (P/R/D areas, military areas, obstacles, aerial sports); en-route charts.","s":"Reg 10","ch":"Aeronautical Information Services","sec":"India (p.240–245)","h":"chapters/reg-10.html#n-india-p-240-245"},{"t":"Entering ground effect","d":"the same lift needs less AoA; induced drag falls → slower deceleration → longer float; less downwash on the tailplane → nose-down pitch; local pressure at the static ports rises → ASI and altimeter under-read.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"L/D ratio and ground effect (2-19)","h":"chapters/hb-02.html#n-l-d-ratio-and-ground-effect-2-19"},{"t":"EOBT","d":"estimated time the aircraft starts moving for departure. EAT: time ATC expects a delayed arrival to leave the holding fix.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Flight plans and times (p.13–35)","h":"chapters/reg-01.html#n-flight-plans-and-times-p-13-35"},{"t":"EOBT (estimated off-block time)","d":"when the aircraft will start moving for departure.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Equation of time","d":"apparent solar time − mean solar time (= sundial − clock). Mean time is ahead by about 14 min near 6 February and behind by about 16 min near 3 November; EOT = 0 four times a year (April, June, September, December).","s":"Nav 1","ch":"The Solar System","sec":"Year and day","h":"chapters/nav-01.html#n-year-and-day"},{"t":"Equations of motion","d":"v = u + at; s = ut + ½at²; v² = u² + 2as; s = ½(u + v) t.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Laws (2-4)","h":"chapters/hb-01.html#n-laws-2-4"},{"t":"Essential local traffic","d":"any aircraft, vehicle or person on or near the manoeuvring area, or traffic nearby, that may be a hazard.","s":"Reg 8","ch":"Procedures for Aerodrome Control Service","sec":"Information from the tower (p.208–211)","h":"chapters/reg-08.html#n-information-from-the-tower-p-208-211"},{"t":"Essential traffic","d":"controlled traffic that should be separated by ATC but, relative to a particular flight, is not (or will not be) separated by the minimum. Essential traffic information must be given to both flights.","s":"Reg 6","ch":"Separation Methods and Minima","sec":"Essential traffic (p.182)","h":"chapters/reg-06.html#n-essential-traffic-p-182"},{"t":"ETA","d":"IFR — time over the designated navaid point from which the instrument approach will start (or over the aerodrome if no navaid); VFR — time over the aerodrome.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"ETA (IFR)","d":"over the point from which the instrument approach starts (or over the aerodrome if no aid). ETA (VFR): over the aerodrome. Total EET is defined the same way from take-off.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Flight plans and times (p.13–35)","h":"chapters/reg-01.html#n-flight-plans-and-times-p-13-35"},{"t":"Evening waves","d":"after sunset low-level stability + weaker wind → waves behind small/medium hills, until morning heating.","s":"Met 16","ch":"CAT and Mountain Waves","sec":"Variation and extent (p.152)","h":"chapters/met-16.html#n-variation-and-extent-p-152"},{"t":"Exhaust trails","d":"moisture from engine exhaust condensing, at about 9 km and above; long, persistent, reveal position and track.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Condensation trails (p.83–84)","h":"chapters/met-08.html#n-condensation-trails-p-83-84"},{"t":"Expansion wave","d":"the opposite — flow turns gradually, speeds up; pressure, density and temperature fall; no energy loss.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Shockwaves (2-51)","h":"chapters/hb-08.html#n-shockwaves-2-51"},{"t":"Experimental mean pitch (EMP)","d":"advance per revolution when producing no thrust (AoA below zero); EMP is always greater than GMP.","s":"Handbook 9","ch":"Propellers","sec":"Pitch and angles (2-58)","h":"chapters/hb-09.html#n-pitch-and-angles-2-58"},{"t":"Fail-safe","d":"redundant load paths + inspections; safe-life = fixed life then replace.","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Exam traps","h":"chapters/hb-10.html#n-exam-traps"},{"t":"Feet per hPa","d":"27 ft at MSL, 34 ft at 10 000 ft, 50 ft at 18 000 ft, 100 ft at 40 000 ft (book: 30 ft used in many sums).","s":"Nav 10","ch":"DR Elements: Pressure and Altimetry","sec":"ISA and density","h":"chapters/nav-10.html#n-isa-and-density"},{"t":"Ferrel cell (30–60°)","d":"surface air from 30° flows poleward, turned east → surface westerlies; rises near 60° (clouds, rain) = polar front region; some returns equatorward aloft.","s":"Met 20","ch":"General Circulation","sec":"Three-cell model (p.188–190)","h":"chapters/met-20.html#n-three-cell-model-p-188-190"},{"t":"Fibratus","d":"filaments without hooks. Lenticularis: lens-shaped CC/AC/SC (orographic, or lee of CB/TCU).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Species (p.83)","h":"chapters/met-08.html#n-species-p-83"},{"t":"Filed flight plan","d":"as filed by the pilot or representative, without subsequent changes.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Filed flight plan","d":"as filed, without later changes. Current flight plan: filed plan + later ATC clearances. Repetitive flight plan (RPL): for regular recurring flights with identical features. Operational flight plan: the operator's plan for safe conduct of the flight.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Flight plans and times (p.13–35)","h":"chapters/reg-01.html#n-flight-plans-and-times-p-13-35"},{"t":"Fin","d":"effective at small yaw angles, less at large ones. Dorsal/ventral fins: overcome the fuselage's destabilising effect; effective at large sideslip. Dorsal fin adds both directional and lateral stability; ventral fin adds directional but reduces lateral stability — so dorsal fins are preferred.","s":"Handbook 5","ch":"Stability","sec":"Directional stability (2-35)","h":"chapters/hb-05.html#n-directional-stability-2-35"},{"t":"Fin stall","d":"in a large sideslip the fin can stall; a dorsal fin lowers its aspect ratio and raises its stalling angle.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Primary controls (2-38)","h":"chapters/hb-06.html#n-primary-controls-2-38"},{"t":"Find latitude from departure","d":"cos lat = departure / d.long′ (250 NM over 4°50′ → cos lat 0.86 → 30°41′).","s":"Nav 7","ch":"Distances on the Earth","sec":"Departure (rhumb-line distance along a parallel)","h":"chapters/nav-07.html#n-departure-rhumb-line-distance-along-a-parallel"},{"t":"FIR","d":"airspace where FIS and alerting service are provided. Control area (CTA): controlled airspace from a specified limit above the earth. Control zone (CTR): controlled airspace from the surface to a specified upper limit. TMA: control area at the confluence of ATS routes near major aerodromes. Airway: control area in the form of a corridor.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Airspace and ATS (p.5–35)","h":"chapters/reg-01.html#n-airspace-and-ats-p-5-35"},{"t":"Fix","d":"accurate position from visual, radio or radar means. DR circle of error ≈ 5% of TAS-ish per the book's rule of thumb; Doppler DR error ellipse ≈ 0.1% along / 0.2% across distance since the fix.","s":"Nav 9","ch":"Dead Reckoning","sec":"Terms","h":"chapters/nav-09.html#n-terms"},{"t":"Fix","d":"aircraft's exact position at a time, from visual, radio or radar observations (simultaneous or transferred to a common time).","s":"Nav 13","ch":"In-flight Navigation","sec":"Fixes and position lines","h":"chapters/nav-13.html#n-fixes-and-position-lines"},{"t":"Fixed pitch","d":"AoA rises when RPM rises or forward speed falls; the blade angle is chosen for one condition (typically cruise). In a glide, higher windmilling RPM → more drag → less glide range.","s":"Handbook 9","ch":"Propellers","sec":"Fixed, variable and constant-speed propellers (2-59)","h":"chapters/hb-09.html#n-fixed-variable-and-constant-speed-propellers-2-59"},{"t":"Fixed tabs","d":"ground-adjustable, usually on ailerons and rudder.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Aerodynamic balance (2-40)","h":"chapters/hb-06.html#n-aerodynamic-balance-2-40"},{"t":"Flaps","d":"raise CLmax and lower Vs → smaller radius possible, provided the flap limit speed is respected and there is enough thrust for the extra drag.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Steady turn (2-46)","h":"chapters/hb-07.html#n-steady-turn-2-46"},{"t":"Flaps, gear","d":"worse L/D, less range. Altitude: no effect on glide angle/range (if VMD is flown), but higher ROD at height (higher TAS).","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Descent and glide (2-45)","h":"chapters/hb-07.html#n-descent-and-glide-2-45"},{"t":"Flat plate","d":"CP moves back as AoA increases (nose-down, stable).","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Centre of pressure and aerodynamic centre (2-10)","h":"chapters/hb-01.html#n-centre-of-pressure-and-aerodynamic-centre-2-10"},{"t":"Flexural aileron flutter","d":"the wing flaps up and down (bending) instead of twisting. Cures: mass balance, stiffer wings.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Aeroelastic problems (2-57)","h":"chapters/hb-08.html#n-aeroelastic-problems-2-57"},{"t":"Flight level","d":"surface of constant pressure related to 1013.2 hPa. QNH → altimeter shows altitude; QFE → height above the QFE datum; 1013.2 → flight levels.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Vertical references (p.8–36)","h":"chapters/reg-01.html#n-vertical-references-p-8-36"},{"t":"Flight levels","d":"surfaces of constant pressure referenced to 1013.25 hPa, separated by 500 ft intervals (FL50 = 5,000 ft; FL300 = 30,000 ft).","s":"Met 2","ch":"Atmospheric Pressure","sec":"Altimetry definitions (p.17)","h":"chapters/met-02.html#n-altimetry-definitions-p-17"},{"t":"Flight plan","d":"specified information given to ATS units about an intended flight or part of a flight.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Flight time (aeroplane)","d":"from first moving for take-off until finally coming to rest = block to block / chock to chock. Helicopter: from rotors starting to turn until rest with rotors stopped.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Flight plans and times (p.13–35)","h":"chapters/reg-01.html#n-flight-plans-and-times-p-13-35"},{"t":"Fluid pressure at rest","d":"acts equally in all directions; acts at right angles to any surface it touches; increases with depth.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Laws (2-4)","h":"chapters/hb-01.html#n-laws-2-4"},{"t":"Flutter","d":"aerodynamic forces (gust, control input) couple with the natural vibration of the structure → rapid, growing oscillation and catastrophic failure. Caused by structural flexibility and high aerodynamic and inertial forces.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Aeroelastic problems (2-57)","h":"chapters/hb-08.html#n-aeroelastic-problems-2-57"},{"t":"Fly-by waypoint","d":"turn anticipation, tangential interception. Fly-over waypoint: turn starts over the waypoint.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Navigation words (p.12–38)","h":"chapters/reg-01.html#n-navigation-words-p-12-38"},{"t":"Flying","d":"smooth in layer cloud, turbulent in embedded CU/CB; visibility exceptionally good except in rain; gaps between layers usually give a cloud-free level except near depressions.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Föhn","d":"moist air forced over a range; cools at SALR while cloud forms and rain falls on the windward side; descends dry on the lee and warms at DALR → warm, dry lee wind (Alps); 10°C or more warmer. Chinook (Rockies). Needs (a) a substantial mountain range, (b) wind blowing within 30° of the range's perpendicular (book: \"within 30° of the range\"), (c) high moisture content. Dry air may not give a Föhn.","s":"Met 6","ch":"Winds","sec":"Local winds (p.55–58)","h":"chapters/met-06.html#n-local-winds-p-55-58"},{"t":"Foreign aircraft","d":"registered in a country other than India.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aircraft and their kinds (p.3–38)","h":"chapters/reg-01.html#n-aircraft-and-their-kinds-p-3-38"},{"t":"Form (pressure) drag","d":"difference between the high pressure at the front and the low pressure behind. Profile drag = skin friction + form drag. Streamlining raises the fineness ratio and eases curvature → smaller adverse gradient → less form drag.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Parasite drag (2-15)","h":"chapters/hb-02.html#n-parasite-drag-2-15"},{"t":"Formation flight","d":"not allowed for civil aircraft in India. ICAO allows it by pre-arrangement: formation acts as a single aircraft for navigation and reporting, separation within it is the leader's and pilots' responsibility, each aircraft within 1 km (0.5 NM) laterally/longitudinally and 30 m (100 ft) vertically of the leader.","s":"Reg 4","ch":"Rules of the Air","sec":"General rules (p.78–81)","h":"chapters/reg-04.html#n-general-rules-p-78-81"},{"t":"Formation needs","d":"(a) warm sea > 26°C to ~60 m depth; (b) high RH up to ~7000 m; (c) instability and enough Coriolis; (d) very little vertical wind shear (< 20 kt between 850 and 200 hPa).","s":"Met 18","ch":"Tropical Systems","sec":"Tropical cyclones (TC / TRS) (p.159–162)","h":"chapters/met-18.html#n-tropical-cyclones-tc-trs-p-159-162"},{"t":"Forward CG","d":"more stable, heavier elevator, larger tail download → more induced drag, higher stall speed, more fuel, less range/endurance, slow pitch response.","s":"Nav 14","ch":"Mass and Balance","sec":"CG position effects","h":"chapters/nav-14.html#n-cg-position-effects"},{"t":"Forward CG limit","d":"maximum stick forces, minimum manoeuvrability (set by maximum permissible stability). Aft CG limit: minimum stick forces, maximum manoeuvrability (minimum permissible stability); the aircraft tends to neutral there.","s":"Handbook 5","ch":"Stability","sec":"Longitudinal static stability (2-32 to 2-33)","h":"chapters/hb-05.html#n-longitudinal-static-stability-2-32-to-2-33"},{"t":"Fractus","d":"ragged ST/CU. Congestus: CU with strong sprouting, cauliflower (TCU).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Species (p.83)","h":"chapters/met-08.html#n-species-p-83"},{"t":"Frangible object","d":"low mass, designed to break, distort or yield on impact. FOD: object on the movement area with no aeronautical function that can harm aircraft.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aerodrome areas (p.4–36)","h":"chapters/reg-01.html#n-aerodrome-areas-p-4-36"},{"t":"Free-stream Mach (MFS)","d":"aircraft speed ÷ LSS — what the Machmeter shows. Local Mach (ML): differs over the airframe; at a given MFS it is highest at the point of maximum camber.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Mach number and speed regimes (2-49)","h":"chapters/hb-08.html#n-mach-number-and-speed-regimes-2-49"},{"t":"Friction","d":"static (limiting) friction acts before movement starts; sliding (kinetic) friction is less than static.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Laws (2-4)","h":"chapters/hb-01.html#n-laws-2-4"},{"t":"Frictional eddies","d":"horizontal, vertical or slant; grow in unstable air up to ~1 km.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Vertical motion (p.75–76)","h":"chapters/met-08.html#n-vertical-motion-p-75-76"},{"t":"Frise ailerons","d":"asymmetric LE; the up-going aileron's nose protrudes below the wing → extra drag on that side; the down-going aileron's nose stays shrouded.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Secondary effects (2-39)","h":"chapters/hb-06.html#n-secondary-effects-2-39"},{"t":"Front","d":"narrow transition zone between two air masses of contrasting density (temperature/humidity); change of temperature, wind, cloud and precipitation across it.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Fronts (p.131–132)","h":"chapters/met-14.html#n-fronts-p-131-132"},{"t":"Frontal fog","d":"in the continuous rain ahead of a (warm) front, saturating the surface air; or cloud lowering to the surface as the front passes.","s":"Met 7","ch":"Visibility and Fog","sec":"Other fogs (p.72)","h":"chapters/met-07.html#n-other-fogs-p-72"},{"t":"Frontal surface","d":"the sloping boundary; front = where it meets the ground.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Fronts (p.131–132)","h":"chapters/met-14.html#n-fronts-p-131-132"},{"t":"Frontal TS","d":"mainly at cold fronts (occasionally warm fronts); more violent than air-mass TS; any time of day or night. A line ahead of a cold front = squall line.","s":"Met 13","ch":"Thunderstorms","sec":"Types (p.112–113)","h":"chapters/met-13.html#n-types-p-112-113"},{"t":"Frontogenesis","d":"formation/strengthening; frontolysis = weakening/dissipation. Weather only with significant density contrast.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Fronts (p.131–132)","h":"chapters/met-14.html#n-fronts-p-131-132"},{"t":"Fronts","d":"warm front = gradual ascent over a large area; cold front = abrupt sharp ascent → convection, TS, squalls.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Vertical motion (p.75–76)","h":"chapters/met-08.html#n-vertical-motion-p-75-76"},{"t":"Frost point","d":"saturation with respect to ice; cooling below it → hoar frost.","s":"Met 5","ch":"Humidity","sec":"Wet bulb, dew point, frost point (p.42)","h":"chapters/met-05.html#n-wet-bulb-dew-point-frost-point-p-42"},{"t":"Fujita scale (tornado winds)","d":"F0 35–62 kt light · F1 63–95 moderate (cars pushed off roads) · F2 96–135 considerable (roofs off, trees uprooted) · F3 136–180 severe (heavy cars thrown) · F4 181–225 devastating (houses levelled) · F5 226–275 incredible.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"B. Meteorological scales","h":"chapters/met-30.html#n-b-meteorological-scales"},{"t":"Full opposite rudder","d":"anti-spin moment and stops the sideslip; the rudder is not stalled.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Spin recovery (2-26)","h":"chapters/hb-03.html#n-spin-recovery-2-26"},{"t":"Fully powered / fly-by-wire","d":"hydraulics supply all the force; transducers send stick movement as electrical signals to computers. Air loads cannot move the stick — irreversible — so artificial feel is needed. Typical Airbus-type set: 2 ELAC (elevator/aileron computers), 3 SEC (spoiler/elevator), 2 FAC (rudder/yaw damping).","s":"Handbook 11","ch":"Landing Gear, Brakes, Tyres and Powered Controls","sec":"Flight-control systems (3-14)","h":"chapters/hb-11.html#n-flight-control-systems-3-14"},{"t":"Fuselage","d":"truss (welded tubes in triangles — light, unpressurised aircraft); monocoque (the skin carries all loads, light frames only — cannot tolerate dents); semi-monocoque (skin reinforced by longerons, stringers and frames — sturdier; standard).","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Airframe construction (3-5)","h":"chapters/hb-10.html#n-airframe-construction-3-5"},{"t":"Fuselage and nacelles","d":"destabilising.","s":"Handbook 5","ch":"Stability","sec":"Longitudinal static stability (2-32 to 2-33)","h":"chapters/hb-05.html#n-longitudinal-static-stability-2-32-to-2-33"},{"t":"g limits","d":"maximum positive and negative load factors, with a further 50% safety margin before permanent deformation (beyond it, failure). Heavier → lower allowable g (the structure carries g × weight).","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Manoeuvre envelope (2-56)","h":"chapters/hb-08.html#n-manoeuvre-envelope-2-56"},{"t":"Gale","d":"persistent mean wind ≥ 34 kt, with depressions and cyclonic storms. A parked aircraft can survive a gale but not necessarily a sudden 60 kt squall.","s":"Met 6","ch":"Winds","sec":"Gust, lull, squall, gale (p.46–47)","h":"chapters/met-06.html#n-gust-lull-squall-gale-p-46-47"},{"t":"Gas laws","d":"Boyle — constant temperature: P ∝ 1/V (PV = constant). Charles — constant pressure: V ∝ T (volume changes by 1/273 of its 0 °C value per °C). Gay-Lussac — constant volume: P ∝ T. Avogadro — more gas, more volume (V/n = constant). Combined: PV = nRT.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Laws (2-4)","h":"chapters/hb-01.html#n-laws-2-4"},{"t":"GEN","d":"national regulations and requirements (authorities, entry/transit/departure of aircraft, people, cargo; instruments, equipment, documents; differences from ICAO), tables and codes (units, time, geodetic reference, marks, holidays, abbreviations, chart symbols, location indicators, nav-aid list, conversion and sunrise/sunset tables), services (AIS, charts, ATS, comms, met, SAR), charges.","s":"Reg 10","ch":"Aeronautical Information Services","sec":"India (p.240–245)","h":"chapters/reg-10.html#n-india-p-240-245"},{"t":"Geneva 1948","d":"rights in aircraft (seller's rights under hire purchase, lease, mortgage). Cape Town 2001 convention and protocol: international interests in mobile equipment (aircraft finance); India ratified in 2008.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Liability conventions (p.54–56)","h":"chapters/reg-02.html#n-liability-conventions-p-54-56"},{"t":"Geocentric latitude","d":"angle at the earth's centre. Geodetic (geographic) latitude: angle between the normal to the spheroid and the equatorial plane — used on charts. Maximum difference ~11.6′ at about 45° N/S.","s":"Nav 2","ch":"The Earth","sec":"Latitude","h":"chapters/nav-02.html#n-latitude"},{"t":"Geoid","d":"equipotential surface coinciding with undisturbed MSL extended through the continents. Geoid undulation: geoid above (+) or below (−) the reference ellipsoid (WGS-84).","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Vertical references (p.8–36)","h":"chapters/reg-01.html#n-vertical-references-p-8-36"},{"t":"Geometric mean pitch (GMP)","d":"advance per revolution when the blade AoA is zero (still some thrust from camber).","s":"Handbook 9","ch":"Propellers","sec":"Pitch and angles (2-58)","h":"chapters/hb-09.html#n-pitch-and-angles-2-58"},{"t":"Geometric pitch","d":"distance the propeller would advance in one revolution if it moved through the air at its blade angle like a screw in wood.","s":"Handbook 9","ch":"Propellers","sec":"Pitch and angles (2-58)","h":"chapters/hb-09.html#n-pitch-and-angles-2-58"},{"t":"Geostationary","d":"~36 000 km above the equator, period = earth's rotation, stays over one spot; 5 cover the globe; round-the-clock (e.g. METEOSAT, INSAT). Imagery interval 30 min, but generally 3-hourly pictures supplied.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Met satellites (p.210–213)","h":"chapters/met-22.html#n-met-satellites-p-210-213"},{"t":"GFC (gross fuel consumption)","d":"fuel per unit time. SFC (specific fuel consumption): fuel per unit time per unit thrust (or power).","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Cruise, range and endurance (2-48)","h":"chapters/hb-07.html#n-cruise-range-and-endurance-2-48"},{"t":"Glide","d":"range set by L/D; best glide speed at max L/D; weight changes only the glide time (and best-glide speed), not the ratio; wind changes ground distance.","s":"Nav 15","ch":"Performance","sec":"Cruise, ceiling, descent, glide","h":"chapters/nav-15.html#n-cruise-ceiling-descent-glide"},{"t":"Glide","d":"only lift, drag and weight; the weight component along the path balances drag. Glide angle: tan θ = D ÷ L (cot θ = L/D) — smallest at maximum L/D.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Descent and glide (2-45)","h":"chapters/hb-07.html#n-descent-and-glide-2-45"},{"t":"Glory","d":"coloured rings around your own shadow (often the aircraft's shadow) on cloud/fog of small droplets; diffraction (arranged like a corona).","s":"Met 10","ch":"Optical Phenomena","sec":"Other phenomena (p.97–98)","h":"chapters/met-10.html#n-other-phenomena-p-97-98"},{"t":"GMT / UTC","d":"LMT of the Greenwich meridian; UTC is kept by atomic clocks (≈ GMT); the same everywhere. GD/UD = Greenwich/universal date.","s":"Nav 5","ch":"Time","sec":"Basics","h":"chapters/nav-05.html#n-basics"},{"t":"Good L/D","d":"efficiency, load-carrying, low fuel burn. High maximum CL³ᐟ²/CD ratio (book: CL/CD) — less power required, more endurance.","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Requirements of an ideal aerofoil (2-27)","h":"chapters/hb-04.html#n-requirements-of-an-ideal-aerofoil-2-27"},{"t":"Gradient wind","d":"parallel to curved isobars; balance of PGF, Coriolis and centripetal; better than geostrophic in mid-latitudes (friction ignored).","s":"Met 6","ch":"Winds","sec":"Cyclostrophic, gradient, isallobaric, inertial winds (p.50–51)","h":"chapters/met-06.html#n-cyclostrophic-gradient-isallobaric-inertial-winds-p-50-51"},{"t":"Graticule","d":"network of meridians and parallels on a map/chart (they are imaginary lines, not marked on the earth).","s":"Nav 2","ch":"The Earth","sec":"Longitude and meridians","h":"chapters/nav-02.html#n-longitude-and-meridians"},{"t":"Great circle (GC)","d":"circle whose plane passes through the earth's centre, dividing it into two equal halves; radius, centre and diameter = the earth's. The shorter arc of a GC is the shortest distance between two points. Only one GC through two points unless they are diametrically opposite (then infinitely many). Radio waves follow GC paths.","s":"Nav 2","ch":"The Earth","sec":"Great circle, small circle, rhumb line","h":"chapters/nav-02.html#n-great-circle-small-circle-rhumb-line"},{"t":"Green","d":"light precipitation, little/no turbulence, reduced visibility.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Airborne weather radar (p.209)","h":"chapters/met-22.html#n-airborne-weather-radar-p-209"},{"t":"Greenhouse gases","d":"WV, CO₂, O₃, methane — transparent to solar (short-wave) radiation but partly absorb terrestrial (long-wave) radiation and re-radiate it → keep the earth warmer. Excess → global warming.","s":"Met 1","ch":"Atmosphere","sec":"Variable gases and greenhouse gases (p.2)","h":"chapters/met-01.html#n-variable-gases-and-greenhouse-gases-p-2"},{"t":"Gross performance","d":"average fleet performance when well maintained and flown to the book. Net performance = gross reduced for contingencies (technique, below-average aircraft); it is improbable that net performance won't be achieved. Gross height used for PA in obstacle calculations and flap-retraction height; net height/flight path must clear obstacles by the statutory margin.","s":"Nav 15","ch":"Performance","sec":"Terms","h":"chapters/nav-15.html#n-terms"},{"t":"Ground discharge (thunderbolt)","d":"cloud to ground, branching (streak/ribbon lightning). Ball lightning: luminous ball 10–20 cm, moves slowly, ends with an explosion.","s":"Met 10","ch":"Optical Phenomena","sec":"Atmospheric electricity and lightning (p.99–100)","h":"chapters/met-10.html#n-atmospheric-electricity-and-lightning-p-99-100"},{"t":"Ground effect","d":"within about ½ wingspan of the ground vortices are squeezed, upwash and downwash weaken and effective AoA rises, so CDi falls.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"L/D ratio and ground effect (2-19)","h":"chapters/hb-02.html#n-l-d-ratio-and-ground-effect-2-19"},{"t":"Ground visibility ≥ 1,500 m","d":"may enter a CTR to land, take off and depart, cross, or operate locally. Performance Class 1 and 2 helicopters: ≥ 1,000 m (state it in field 18 and on RTF).","s":"Reg 4","ch":"Rules of the Air","sec":"Special VFR (p.89)","h":"chapters/reg-04.html#n-special-vfr-p-89"},{"t":"GS","d":"TAS ± wind component. ETE = distance ÷ GS. ETA (IFR: over the IAF/nav aid; VFR: over the aerodrome).","s":"Nav 9","ch":"Dead Reckoning","sec":"Terms","h":"chapters/nav-09.html#n-terms"},{"t":"Gust","d":"rapid, irregular, transient increase lasting seconds (friction turbulence, uneven heating, hot afternoons). Negative fluctuation = lull.","s":"Met 6","ch":"Winds","sec":"Gust, lull, squall, gale (p.46–47)","h":"chapters/met-06.html#n-gust-lull-squall-gale-p-46-47"},{"t":"Gusts","d":"worst near the up/downdraught boundary; abrupt attitude changes.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"Gyroscopic precession","d":"only when the aircraft pitches or yaws; worst at low speed, high power. Tail-wheel aircraft raising the tail on take-off → yaw left. In flight (book): a left yaw → pitch up, a pitch up → yaw right. Cured by contra-rotation.","s":"Handbook 9","ch":"Propellers","sec":"Propeller effects on the aircraft (2-60) — clockwise propeller seen from behind","h":"chapters/hb-09.html#n-propeller-effects-on-the-aircraft-2-60-clockwise-propeller-seen-from-behind"},{"t":"h (cloud base)","d":"0 = 0–49 m, 1 = 50–99, 2 = 100–199, 3 = 200–299, 4 = 300–599, 5 = 600–999, 6 = 1000–1499, 7 = 1500–1999, 8 = 2000–2500, 9 = no cloud below 2500.","s":"Met 24","ch":"Station Models","sec":"Codes","h":"chapters/met-24.html#n-codes"},{"t":"H → L → H","d":"High to Low, look out below = over-read. Warm to cold = over-read.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Over-reading and under-reading (p.19–20)","h":"chapters/met-02.html#n-over-reading-and-under-reading-p-19-20"},{"t":"Haboob","d":"sand-raising wind, Sudan. Harmattan: hot dusty NE wind (book: central Asia). Khamsin: hot dry sandy southerly over Egypt, Apr–Jun.","s":"Met 6","ch":"Winds","sec":"Named winds (p.61–62)","h":"chapters/met-06.html#n-named-winds-p-61-62"},{"t":"Hadley cell (0–30°)","d":"strong equatorial heating → rising air, convective cloud, heavy rain = ITCZ (NE and SE trades converge; follows the sun). Air rises to the tropopause, flows poleward, is turned east by Coriolis → zonal westerlies by ~30°, strengthening with height (angular momentum + S–N temperature gradient) → subtropical jet just below the tropopause. Air piles up and subsides at ~30° → subtropical high belt; subsidence suppress…","s":"Met 20","ch":"General Circulation","sec":"Three-cell model (p.188–190)","h":"chapters/met-20.html#n-three-cell-model-p-188-190"},{"t":"Hague 1970","d":"suppression of unlawful seizure (hijacking); severe penalties and extradition.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Unlawful acts conventions (p.50–53)","h":"chapters/reg-02.html#n-unlawful-acts-conventions-p-50-53"},{"t":"Hail","d":"starts as an ice crystal, grows by collision with supercooled drops while tossed up and down; onion layers of clear (near freezing level) and rime ice. Worst from the freezing level to ~25,000 ft; damaging hail up to 45,000 ft and under the anvil (even in clear air). Max ~5.5 in; 4.5 kg (China), 3.4 kg (India) recorded. Large hail dents airframes, breaks windscreens, rips de-icer boots.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"Hazards","d":"poor visibility (fog, mist, haze, smoke, inversion) — worst after a WD over NW India, UP, Bihar, central India, N Bengal, Assam (S bank of the Brahmaputra); can persist days at polluted airfields like Palam (Delhi) with only 1000–2000 m at noon. Advection fog on coasts lifts by 1000–1100 IST. CAT near the STJ (NE India); mountain waves over N and E India. Freezing level lower → icing at lower levels.","s":"Met 19","ch":"Climatology of India","sec":"Winter (Jan–Feb) (p.171–173)","h":"chapters/met-19.html#n-winter-jan-feb-p-171-173"},{"t":"Hazards","d":"very low cloud (150–200 m) and strong winds in strong monsoon and depressions; visibility good except in rain (dust haze in breaks, monsoon haze on the west coast); CAT near the TEJ; long-lived TS at onset, in breaks and revivals.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Hazards","d":"visibility deteriorating near industry at dawn/dusk, fog after WDs; low cloud, gales, heavy rain and TS with cyclones in the south; CAT (STJ) in the north.","s":"Met 19","ch":"Climatology of India","sec":"Post-monsoon / NE monsoon (Oct–Dec) (p.180–182)","h":"chapters/met-19.html#n-post-monsoon-ne-monsoon-oct-dec-p-180-182"},{"t":"Hazards — most hazardous flying season","d":"violent TS, DS, line squalls; dust haze to 7–8 km; dust-raising winds 30–50 kt (0900–1700 h), visibility a few hundred metres.","s":"Met 19","ch":"Climatology of India","sec":"Summer / pre-monsoon (Mar–May) (p.173–175)","h":"chapters/met-19.html#n-summer-pre-monsoon-mar-may-p-173-175"},{"t":"Head-on","d":"both alter heading to the right.","s":"Reg 4","ch":"Rules of the Air","sec":"Right of way (p.80–81)","h":"chapters/reg-04.html#n-right-of-way-p-80-81"},{"t":"Heading","d":"direction the longitudinal axis points. Track: projection of the path on the earth.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Navigation words (p.12–38)","h":"chapters/reg-01.html#n-navigation-words-p-12-38"},{"t":"Heading (HDG)","d":"where the nose points (°C/M/T/Grid). Course: intended direction of flight (US usage: course = required track, track = actual path).","s":"Nav 9","ch":"Dead Reckoning","sec":"Terms","h":"chapters/nav-09.html#n-terms"},{"t":"Headwind","d":"less range (higher best-range glide speed); tailwind: more range. Wind has no effect on ROD.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Descent and glide (2-45)","h":"chapters/hb-07.html#n-descent-and-glide-2-45"},{"t":"Heat","d":"sum total of the kinetic energy of all molecules; temperature = average KE. A bathtub at 60°C holds more heat than a cup of boiling water. The thermosphere is very hot but holds little heat (few, far-apart particles) → no effect on spacecraft.","s":"Met 3","ch":"Temperature","sec":"Definitions (p.28)","h":"chapters/met-03.html#n-definitions-p-28"},{"t":"Heavy showers","d":"very low visibility, hydroplaning, engine power loss from water ingestion, noise; fractostratus below 1,000 ft.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"Helix angle","d":"between the plane of rotation and the path of effective pitch (each blade section follows a helix).","s":"Handbook 9","ch":"Propellers","sec":"Pitch and angles (2-58)","h":"chapters/hb-09.html#n-pitch-and-angles-2-58"},{"t":"High","d":"pressure higher than surroundings at the same level, ≥ 1 closed isobar.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"A. Synoptic systems","h":"chapters/met-30.html#n-a-synoptic-systems"},{"t":"High (H) / anticyclone","d":"highest at centre; fair weather but poor visibility (subsidence); N hemisphere winds clockwise, veer, diverge.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure patterns (p.21–22) (isobars at 2 hPa)","h":"chapters/met-02.html#n-pressure-patterns-p-21-22-isobars-at-2-hpa"},{"t":"High CLmax","d":"low landing speed.","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Requirements of an ideal aerofoil (2-27)","h":"chapters/hb-04.html#n-requirements-of-an-ideal-aerofoil-2-27"},{"t":"High to low (pressure or temperature): look out below","d":"the altimeter over-reads.","s":"Nav 18","ch":"Altimeter","sec":"Exam traps","h":"chapters/nav-18.html#n-exam-traps"},{"t":"High-lift devices","d":"more downwash and less dynamic pressure at the tail → less stability (neutral point may move forward) — stability is weakest on approach and landing.","s":"Handbook 5","ch":"Stability","sec":"Longitudinal static stability (2-32 to 2-33)","h":"chapters/hb-05.html#n-longitudinal-static-stability-2-32-to-2-33"},{"t":"Horn balance","d":"part of the surface ahead of the hinge at its tip (a horn); like an inset hinge; mainly on rudders; can also carry the mass balance.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Hinges, horns and mass balance (2-41)","h":"chapters/hb-06.html#n-hinges-horns-and-mass-balance-2-41"},{"t":"Hot spots","d":"locations on the movement area with collision/incursion risk, designated by the aerodrome operator and charted per Annex 4.","s":"Reg 8","ch":"Procedures for Aerodrome Control Service","sec":"Wind shear, hot spots, friction (p.216–217)","h":"chapters/reg-08.html#n-wind-shear-hot-spots-friction-p-216-217"},{"t":"Humidity mixing ratio (HMR)","d":"mass of WV per mass of dry air (g/kg). Constant when air is lifted adiabatically (no WV added or removed).","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Hydraulic fuse","d":"limits fluid loss if a line bursts (fitted upstream of non-essential services). Hydraulic lock: trapped fluid holds a piston stationary.","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Hydraulic components (3-7)","h":"chapters/hb-10.html#n-hydraulic-components-3-7"},{"t":"I — Instrument","d":"inherent/manufacturing error.","s":"Nav 18","ch":"Altimeter","sec":"Errors — \"BLIP PBT\"","h":"chapters/nav-18.html#n-errors-blip-pbt"},{"t":"IAS","d":"what the ASI shows (dynamic pressure). → CAS (= RAS): IAS corrected for position/instrument error. → EAS: CAS corrected for compressibility — the true measure of dynamic pressure, so handling depends on EAS. → TAS: EAS corrected for density: TAS = EAS ÷ √(ρ/ρ₀).","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Airspeeds (2-5)","h":"chapters/hb-01.html#n-airspeeds-2-5"},{"t":"Icing","d":"possible 0 to −30°C; clear ice worst in the first 10,000 ft above the freezing level (large supercooled drops); rime higher up; turbine flame-out, carburettor icing.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"Ideal fluid","d":"incompressible, good lubricant, right viscosity, high boiling point, non-flammable, chemically inert, low evaporation, no sludge/foam, non-corrosive, cheap. Synthetic fluid is blue; mineral fluid is red (book).","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Hydraulic components (3-7)","h":"chapters/hb-10.html#n-hydraulic-components-3-7"},{"t":"Identification plate","d":"at least the nationality (or common) mark and registration mark, made of fireproof metal or similar, secured in a prominent position near the main entrance. Unmanned free balloon: on the exterior of the payload. RPA: near the main entrance/compartment, or on the exterior.","s":"Reg 3","ch":"Aircraft Nationality and Registration Marks","sec":"Annex 7 basics (p.69)","h":"chapters/reg-03.html#n-annex-7-basics-p-69"},{"t":"IFR → VFR","d":"notify ATS specifically that the IFR flight is cancelled. Accepted only on a pilot message containing \"CANCELLING MY IFR FLIGHT\" plus any changes. ATS must never invite a change to VFR, directly or by inference.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Changing flight rules","h":"chapters/nav-16.html#n-changing-flight-rules"},{"t":"IFR to VFR","d":"tell ATS specifically \"IFR flight cancelled\"; do so only if the flight will continue for a reasonable time in uninterrupted VMC.","s":"Reg 4","ch":"Rules of the Air","sec":"Instrument flight rules (p.89–91)","h":"chapters/reg-04.html#n-instrument-flight-rules-p-89-91"},{"t":"IMD","d":"India's national met service (mausam.imd.gov.in); 6 Regional Met Offices: Delhi, Mumbai, Kolkata, Chennai, Guwahati, Nagpur.","s":"Met 21","ch":"Met Services for Aviation","sec":"Purpose and organisations (p.194–195)","h":"chapters/met-21.html#n-purpose-and-organisations-p-194-195"},{"t":"Impact icing","d":"supercooled drops hit the air intake → restricts airflow → power loss.","s":"Met 12","ch":"Ice Accretion","sec":"Engine icing (p.109)","h":"chapters/met-12.html#n-engine-icing-p-109"},{"t":"In flight","d":"to the ATS unit in charge of the FIR / control area / advisory area or route (or its aeronautical telecommunication station); otherwise via another unit for retransmission. The ATS authority may limit in-flight filing in busy airspace.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Submission","h":"chapters/nav-16.html#n-submission"},{"t":"In IMC / IFR","d":"non-radar airspace: keep last assigned speed and level (or minimum flight altitude if higher) for 20 minutes after failing to report over a compulsory reporting point, then follow the filed flight plan. Radar airspace: the same for 7 minutes after the later of reaching the last assigned level/MFA, setting 7600, or missing a compulsory report.","s":"Reg 4","ch":"Rules of the Air","sec":"Radio communication failure (p.86–87)","h":"chapters/reg-04.html#n-radio-communication-failure-p-86-87"},{"t":"In VMC","d":"continue in VMC, land at the nearest suitable aerodrome, report arrival to ATC by the quickest means (or complete IFR if advisable).","s":"Reg 4","ch":"Rules of the Air","sec":"Radio communication failure (p.86–87)","h":"chapters/reg-04.html#n-radio-communication-failure-p-86-87"},{"t":"INCERFA","d":"uncertainty phase (uncertainty about safety). ALERFA = alert phase (apprehension about safety). DETRESFA = distress phase (reasonable certainty of grave and imminent danger).","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Emergency and SAR words (p.8–31)","h":"chapters/reg-01.html#n-emergency-and-sar-words-p-8-31"},{"t":"INCERFA","d":"no communication 30 minutes after it was due (or from the first failed attempt, whichever earlier), or aircraft fails to arrive within 30 minutes of ETA (later of notified or estimated).","s":"Reg 5","ch":"Air Traffic Services","sec":"Alerting service and emergency phases (p.147–148)","h":"chapters/reg-05.html#n-alerting-service-and-emergency-phases-p-147-148"},{"t":"Increments","d":"with more lift the transition point moves forward and the adverse gradient grows; interference drag grows; changing AoA changes the frontal area.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Parasite drag (2-15)","h":"chapters/hb-02.html#n-parasite-drag-2-15"},{"t":"India","d":"a winter hazard, typically after a Western Disturbance (rain, then clear skies). Almost daily in winter in the Brahmaputra valley (moisture + katabatic flow). Most susceptible: NW India, UP, Bihar, Jharkhand, Chhattisgarh, Bengal, Assam (southern banks of the Brahmaputra).","s":"Met 7","ch":"Visibility and Fog","sec":"Radiation fog (p.70–71)","h":"chapters/met-07.html#n-radiation-fog-p-70-71"},{"t":"India","d":"highest frequency Oct–May over N, central and NE India (STJ); over S India in July–August (TEJ). Mostly weak–moderate; severe Dec–Feb (STJ peak). Patchy: ~120 km N–S × 250 km E–W, ~2,000 ft deep (can be deeper).","s":"Met 16","ch":"CAT and Mountain Waves","sec":"Clear Air Turbulence (p.147–148)","h":"chapters/met-16.html#n-clear-air-turbulence-p-147-148"},{"t":"India, monsoon (Jun–Sep)","d":"easterlies above 500 hPa, strengthening with height, stronger over S India; Tropical Easterly Jet ~13°N at ~15 km.","s":"Met 6","ch":"Winds","sec":"Contours and upper winds (p.59–60)","h":"chapters/met-06.html#n-contours-and-upper-winds-p-59-60"},{"t":"Indian Ocean Dipole (IOD)","d":"SST difference between the Arabian Sea and eastern Bay of Bengal; positive / neutral / negative. Positive IOD → better rain; negative → less rain, more breaks. EQUINOO (Equatorial Indian Ocean Oscillation) arises from it; positive IOD and EQUINOO increase rain.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"G. Other systems influencing the SW monsoon","h":"chapters/met-30.html#n-g-other-systems-influencing-the-sw-monsoon"},{"t":"Induced (lift-dependent) drag","d":"an unwanted by-product of lift, from the wingtip vortices and the induced downwash they cause. Lift itself reduces the lift finally obtained; restoring it needs more AoA, which adds more drag.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Induced drag and tip vortices (2-16)","h":"chapters/hb-02.html#n-induced-drag-and-tip-vortices-2-16"},{"t":"Induced low / induced cyclonic circulation","d":"develops south of a WD under its influence.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"A. Synoptic systems","h":"chapters/met-30.html#n-a-synoptic-systems"},{"t":"Inertia","d":"reluctance of a body to change its state of rest or motion. Depends on mass, not velocity; applies to bodies at rest and in motion; it is not the same as momentum.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Physical terms (2-3)","h":"chapters/hb-01.html#n-physical-terms-2-3"},{"t":"Inertia cross-coupling","d":"yaw divergence — good longitudinal but poor directional stability; pulling up during a fast roll, high pitch-plane inertia yaws the aircraft further. Pitch divergence — good directional but poor longitudinal stability; high yaw-plane inertia drives the nose down during combined roll and yaw. Avoid by minimum inclination of the inertia axis, more directional stability and roll-rate limits.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Transonic and supersonic stability (2-55)","h":"chapters/hb-08.html#n-transonic-and-supersonic-stability-2-55"},{"t":"Inertial wind","d":"no PGF; balance of centrifugal and Coriolis; Vi = fR; anticyclonic in both hemispheres.","s":"Met 6","ch":"Winds","sec":"Cyclostrophic, gradient, isallobaric, inertial winds (p.50–51)","h":"chapters/met-06.html#n-cyclostrophic-gradient-isallobaric-inertial-winds-p-50-51"},{"t":"Inferior (lower) mirage","d":"over intensely heated road, sand, beach, water → steep lapse rate.","s":"Met 10","ch":"Optical Phenomena","sec":"Mirage (p.97)","h":"chapters/met-10.html#n-mirage-p-97"},{"t":"INSAT-2E","d":"VIS 2 km; WV and TIR 8 km; CCD 1 km.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Met satellites (p.210–213)","h":"chapters/met-22.html#n-met-satellites-p-210-213"},{"t":"INSAT-3D","d":"launched 25 Jul 2013 from French Guiana; gives vertical temperature and humidity profiles; resolution 1 km VIS/SWIR, 4 km MIR/TIR, 8 km WV; at 82°E. INSAT-3DR: launched 8 Sep 2016, 74°E. Together 48 passes/day, new images every 15 min; Indian land scanned hourly, Indian Ocean every 90 min, swapping areas every 3 h.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Met satellites (p.210–213)","h":"chapters/met-22.html#n-met-satellites-p-210-213"},{"t":"Inset hinge","d":"hinge line moved back into the surface → shorter arm from the surface's CP → less hinge moment and stick force, no loss of effectiveness. Limited to 20–25% of the control chord so the CP never gets ahead of the hinge.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Hinges, horns and mass balance (2-41)","h":"chapters/hb-06.html#n-hinges-horns-and-mass-balance-2-41"},{"t":"Insolation","d":"total solar radiation received over an area; depends on the obliquity of the sun's rays: max when the sun is overhead, least at sunrise/sunset; max over the tropics, least at the poles.","s":"Met 3","ch":"Temperature","sec":"Insolation and radiation laws (p.30)","h":"chapters/met-03.html#n-insolation-and-radiation-laws-p-30"},{"t":"Instrument approach","d":"approach control specifies it; the crew may request another.","s":"Reg 7","ch":"Separation in the Vicinity of Aerodromes","sec":"Arriving aircraft (p.198–199)","h":"chapters/reg-07.html#n-arriving-aircraft-p-198-199"},{"t":"Instrument errors","d":"pressure falls under a growing/mature CB → altimeter over-reads; pitot blocked by water → wrong ASI.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"Integrated Aeronautical Information Package","d":"AIP, AIP AMDT, AIP SUP, NOTAM and PIB, AIC, checklists and summaries. NOTAMs and monthly checklists via AFS; PIBs at the ATS reporting office; the rest by mail.","s":"Reg 10","ch":"Aeronautical Information Services","sec":"India (p.240–245)","h":"chapters/reg-10.html#n-india-p-240-245"},{"t":"Inter-Tropical Convergence Zone","d":"narrow zone where Tm/Tc air from the north meets Tm/Em air from the south (converging trades). Usually along the equatorial trough (shallow trough in the doldrums). Also called the equatorial front.","s":"Met 18","ch":"Tropical Systems","sec":"ITCZ (p.154–155)","h":"chapters/met-18.html#n-itcz-p-154-155"},{"t":"Intercepted aircraft","d":"follow the interceptor's instructions; contact on 121.5 MHz (repeat on 243 MHz if practicable); squawk A 7700; select ADS-B/ADS-C emergency mode. If radio instructions from other sources conflict with the interceptor's visual signals, follow the visual signals and ask for clarification; if they conflict with the interceptor's radio instructions, follow the interceptor's radio instructions.","s":"Reg 4","ch":"Rules of the Air","sec":"Interception (p.92–96)","h":"chapters/reg-04.html#n-interception-p-92-96"},{"t":"Interference drag","d":"the whole aircraft has more parasite drag than the sum of its parts — boundary layers thicken and mix at wing–fuselage and wing–engine junctions; wake turbulence adds a further pressure difference.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Parasite drag (2-15)","h":"chapters/hb-02.html#n-parasite-drag-2-15"},{"t":"Intermediate stops","d":"initial clearance limit = first destination; new clearance for each stage. Later stages become active for ATS/SAR only when departure from the previous aerodrome is notified (scheduled flights through several control areas may be cleared through intermediate stops after ACC co-ordination).","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Submission","h":"chapters/nav-16.html#n-submission"},{"t":"Internal balance","d":"a balance panel/tongue inside the wing, sealed, ahead of the hinge; pressure difference on it helps move the surface.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Hinges, horns and mass balance (2-41)","h":"chapters/hb-06.html#n-hinges-horns-and-mass-balance-2-41"},{"t":"Inversion (warmer aloft)","d":"climbing at constant TAS → Mach ↓ (LSS ↑), CAS ↓; at constant Mach → TAS ↑, CAS ↓; at constant CAS → TAS ↑ (Mach changes little, since LSS also rises).","s":"Nav 11","ch":"DR Elements: Temperature and Airspeed","sec":"Climbs and descents (book's graphs)","h":"chapters/nav-11.html#n-climbs-and-descents-book-s-graphs"},{"t":"Inversion fog","d":"in an anticyclone, subsiding cold air contacts a warm water body.","s":"Met 7","ch":"Visibility and Fog","sec":"Other fogs (p.72)","h":"chapters/met-07.html#n-other-fogs-p-72"},{"t":"Inverted spin","d":"roll and yaw are in opposite senses; same flight path and moments otherwise. It responds better to anti-spin rudder because the rudder is not shielded by the tailplane. Recovery as for a normal spin.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Spin (2-24)","h":"chapters/hb-03.html#n-spin-2-24"},{"t":"Irisation","d":"colours/bands parallel to cloud margins (pink predominates), by diffraction.","s":"Met 10","ch":"Optical Phenomena","sec":"Other phenomena (p.97–98)","h":"chapters/met-10.html#n-other-phenomena-p-97-98"},{"t":"ISA","d":"MSL 15 °C, 1013.25 hPa (29.92 inHg, 760 mm, 14.7 lb/in²), density 1.225 kg/m³; lapse 1.98 °C/1000 ft to 36 090 ft, then −56.5 °C to ~65 600 ft. (Jet standard: 2 °C/1000 ft.)","s":"Nav 10","ch":"DR Elements: Pressure and Altimetry","sec":"ISA and density","h":"chapters/nav-10.html#n-isa-and-density"},{"t":"ISA layer (below the tropopause)","d":"climbing at constant CAS → TAS ↑ and Mach ↑; at constant Mach → TAS ↓ and CAS ↓; at constant TAS → CAS ↓, Mach ↑.","s":"Nav 11","ch":"DR Elements: Temperature and Airspeed","sec":"Climbs and descents (book's graphs)","h":"chapters/nav-11.html#n-climbs-and-descents-book-s-graphs"},{"t":"Isallobaric wind","d":"when pressure changes rapidly, an isallobaric force acts from higher to lower isallobar → deflects wind towards falling pressure.","s":"Met 6","ch":"Winds","sec":"Cyclostrophic, gradient, isallobaric, inertial winds (p.50–51)","h":"chapters/met-06.html#n-cyclostrophic-gradient-isallobaric-inertial-winds-p-50-51"},{"t":"Isallobars","d":"lines of equal pressure tendency. Greatest fall = isallobaric low; greatest rise = isallobaric high.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure gradient, tendency, isallobars (p.16–17)","h":"chapters/met-02.html#n-pressure-gradient-tendency-isallobars-p-16-17"},{"t":"Iso-lines","d":"isobar pressure · isohyet rainfall · isotach wind speed · isogon wind direction · isotherm temperature · isallobar pressure change · isopycnic density · isohel sunshine · isomer % of average annual rainfall in a month · isopleth any quantity (generic) · isohypse / contour height · streamline tangential to wind direction.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"D. Miscellaneous terms","h":"chapters/met-30.html#n-d-miscellaneous-terms"},{"t":"Isoclinals","d":"equal dip. Aclinic line: zero dip (magnetic equator). Isogonals: equal variation (converge at both the magnetic and geographic poles). Agonic line: zero variation. Variation at a place changes slowly over time (annual change shown on charts).","s":"Nav 8","ch":"Magnetism and Compasses","sec":"Earth's magnetism","h":"chapters/nav-08.html#n-earth-s-magnetism"},{"t":"Isogonals","d":"lines of equal variation. Agonic line: zero variation.","s":"Nav 6","ch":"Compass and Directions","sec":"Variation and deviation","h":"chapters/nav-06.html#n-variation-and-deviation"},{"t":"Isothermal layer","d":"LSS constant, so constant Mach = constant TAS; climbing at constant CAS → TAS ↑, Mach ↑ (CAS falls at constant TAS/Mach).","s":"Nav 11","ch":"DR Elements: Temperature and Airspeed","sec":"Climbs and descents (book's graphs)","h":"chapters/nav-11.html#n-climbs-and-descents-book-s-graphs"},{"t":"Isothermal process","d":"heat flows in/out so temperature stays constant.","s":"Met 9","ch":"Stability and Instability","sec":"Processes (p.87)","h":"chapters/met-09.html#n-processes-p-87"},{"t":"Jet stream","d":"strong, narrow current of wind along a quasi-horizontal axis in the upper troposphere; in both hemispheres all year; wavy, serpentine path.","s":"Met 15","ch":"Jet Streams","sec":"Definition (p.140)","h":"chapters/met-15.html#n-definition-p-140"},{"t":"Jet-stream cloud","d":"very long cirrus streaks.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Reading satellite images (p.212–213)","h":"chapters/met-22.html#n-reading-satellite-images-p-212-213"},{"t":"Kalpana-1","d":"launched 12 Sep 2002, 74°E; INSAT-3A: 10 Apr 2003, 93.5°E. Both have 3-channel VHRR: VIS (0.55–0.75 µm), IR (10.5–12.5 µm), WV (5.7–7.1 µm); resolution 2 km VIS, 8 km IR/WV; INSAT-3A also a 3-channel CCD (VIS, NIR, SWIR) at 1 km. ~48 images/day from Kalpana-1, 9 from INSAT-3A (CCD daytime, 5 times).","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Met satellites (p.210–213)","h":"chapters/met-22.html#n-met-satellites-p-210-213"},{"t":"Kata (stable) warm front","d":"CI, CS ~1000 km ahead → AS, NS 400–500 km ahead → steady, increasing, prolonged precipitation → just ahead: drizzle, low ST, frontal fog; freezing rain/fog (FZRA/FZFG) ahead in cold air. After passage: fog clears, partly clear, warmer and humid.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Warm front (p.133–134)","h":"chapters/met-14.html#n-warm-front-p-133-134"},{"t":"Kata cold front","d":"slope ~1:120, ~20 kt; warm air sinks aloft → limited vertical growth; ST, NS, AS + CU/CB; widespread rain; showers ahead and just behind; fast ones can produce a line squall 100–300 km ahead.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Cold front (p.132–133)","h":"chapters/met-14.html#n-cold-front-p-132-133"},{"t":"Katabatic","d":"night downslope cold wind (slope cools by radiation); few knots but pools cold air in hollows → frost, mist, fog. Common in NE India (morning fog/TS). Over snow-covered slopes can blow by day too. Bora (Adriatic, gusts > 100 kt), Greenland, Black Sea.","s":"Met 6","ch":"Winds","sec":"Local winds (p.55–58)","h":"chapters/met-06.html#n-local-winds-p-55-58"},{"t":"Kepler's laws","d":"(i) planets move in ellipses with the sun at a focus; (ii) the line joining planet and sun sweeps equal areas in equal times → orbital speed is fastest when closest (perihelion), slowest when farthest (aphelion).","s":"Nav 1","ch":"The Solar System","sec":"The earth's orbit","h":"chapters/nav-01.html#n-the-earth-s-orbit"},{"t":"Kilometre","d":"originally 1/10 000 of the meridian from equator to pole. 1 km = 3280 ft = 0.54 NM; 1 NM = 1.852 km; 1 m = 3.28 ft.","s":"Nav 7","ch":"Distances on the Earth","sec":"Units","h":"chapters/nav-07.html#n-units"},{"t":"Kinematic viscosity (ν = μ/ρ)","d":"1.46 × 10⁻⁵ m²/s at ISA MSL; density falls faster than μ, so ν rises with height, even in the stratosphere.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Viscosity and Reynolds number (2-8)","h":"chapters/hb-01.html#n-viscosity-and-reynolds-number-2-8"},{"t":"Krueger flap","d":"hinged out from the LE underside; increases camber, forms no slot.","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Lift augmentation (2-31)","h":"chapters/hb-04.html#n-lift-augmentation-2-31"},{"t":"L — Lag","d":"from hysteresis and mechanical friction; virtually removed in the servo altimeter by the electromechanical pick-off.","s":"Nav 18","ch":"Altimeter","sec":"Errors — \"BLIP PBT\"","h":"chapters/nav-18.html#n-errors-blip-pbt"},{"t":"L → H → L","d":"Low to High = under-read; cold to warm = under-read.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Over-reading and under-reading (p.19–20)","h":"chapters/met-02.html#n-over-reading-and-under-reading-p-19-20"},{"t":"Lambert","d":"chart convergence = d.long × sin (parallel of origin). Polar stereographic: = d.long.","s":"Nav 4","ch":"Convergency","sec":"On charts","h":"chapters/nav-04.html#n-on-charts"},{"t":"Laminar-flow aerofoils","d":"thinner, for higher speed; thickest at about 50% chord (conventional 25–30%); transition is delayed so drag falls considerably.","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Requirements of an ideal aerofoil (2-27)","h":"chapters/hb-04.html#n-requirements-of-an-ideal-aerofoil-2-27"},{"t":"Landing","d":"aircraft in flight or on the ground/water give way to aircraft landing or on final. Of two landing aircraft, the higher gives way to the lower, but the lower must not cut in front of one on final; power-driven heavier-than-air aircraft give way to gliders.","s":"Reg 4","ch":"Rules of the Air","sec":"Right of way (p.80–81)","h":"chapters/reg-04.html#n-right-of-way-p-80-81"},{"t":"Lapse rate","d":"decrease of temperature with height (positive when temperature falls). Troposphere average 6.5°C/km.","s":"Met 9","ch":"Stability and Instability","sec":"Processes (p.87)","h":"chapters/met-09.html#n-processes-p-87"},{"t":"Large-scale","d":"pressure systems, fronts, upper troughs/ridges, mountains → hundreds of km; mountain waves may reach the upper stratosphere.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Vertical motion (p.75–76)","h":"chapters/met-08.html#n-vertical-motion-p-75-76"},{"t":"Latent heat","d":"heat absorbed or released in a change of phase; absorbed solid→liquid→gas, released in the reverse. Turning boiling water into vapour needs > 5× the heat needed to bring ice-cold water to the boil. Released again on condensation.","s":"Met 3","ch":"Temperature","sec":"Definitions (p.28)","h":"chapters/met-03.html#n-definitions-p-28"},{"t":"Latent instability","d":"initially stable air becomes unstable after forced ascent. Real latent: energy needed to lift it ≪ energy released later. Pseudo latent: lifting energy > energy released.","s":"Met 9","ch":"Stability and Instability","sec":"Stability criteria (p.89)","h":"chapters/met-09.html#n-stability-criteria-p-89"},{"t":"Lateral: decreases","d":"at Mcrit one wing may drop (uneven shocks), gaining lift and a stronger shock, and drop further; dihedral and sweepback effects become unhelpful.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Transonic and supersonic stability (2-55)","h":"chapters/hb-08.html#n-transonic-and-supersonic-stability-2-55"},{"t":"Latitude","d":"angle along the meridian from the equator (datum) to the place, 0–90° N or S.","s":"Nav 2","ch":"The Earth","sec":"Latitude","h":"chapters/nav-02.html#n-latitude"},{"t":"LCC","d":"mathematically made conformal using two standard parallels. Scale correct on the standard parallels, contracts slightly between them (minimum at the parallel of origin, error < 1%), expands outside. The nominal scale is that at the standard parallels.","s":"Nav 3","ch":"Projections","sec":"Simple conic and Lambert's conformal conic (LCC)","h":"chapters/nav-03.html#n-simple-conic-and-lambert-s-conformal-conic-lcc"},{"t":"LE devices","d":"LE flaps, slats, Krueger flaps. TE devices: plain, split, slotted, Fowler, Zap, double-slotted flaps.","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Lift augmentation (2-31)","h":"chapters/hb-04.html#n-lift-augmentation-2-31"},{"t":"LE slots, boundary-layer blowing","d":"re-energise the BL.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Stall behaviour and how designers tame it (2-20)","h":"chapters/hb-03.html#n-stall-behaviour-and-how-designers-tame-it-2-20"},{"t":"Leading-edge radius","d":"small radius → abrupt stall; large radius → well-rounded CL curve, gentle stall.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Lift curves and factors affecting CL (2-13 to 2-14)","h":"chapters/hb-02.html#n-lift-curves-and-factors-affecting-cl-2-13-to-2-14"},{"t":"Leading-edge stagnation point","d":"where part of the flow is brought to complete rest. Velocity zero, positive pressure maximum; total pressure = static pressure, dynamic pressure zero. The flow divides here into top and bottom streams.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Subsonic airflow over an aerofoil (2-11)","h":"chapters/hb-02.html#n-subsonic-airflow-over-an-aerofoil-2-11"},{"t":"Leading-edge vortex (\"bubble\")","d":"on sharp-LE wings the laminar layer separates at the nose and a stationary vortex forms beneath it; good design (swept and delta wings) uses it to raise CL at the same AoA; the flow may re-attach downstream as a turbulent layer.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Lift curves and factors affecting CL (2-13 to 2-14)","h":"chapters/hb-02.html#n-lift-curves-and-factors-affecting-cl-2-13-to-2-14"},{"t":"Lease","d":"lessor furnishes an aircraft to a lessee for compensation or hire, for a period or number of flights. Lessor furnishes; lessee uses.","s":"Reg 3","ch":"Aircraft Nationality and Registration Marks","sec":"Leasing (p.73)","h":"chapters/reg-03.html#n-leasing-p-73"},{"t":"Level","d":"keep watching the temp deviation and FL.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Principles of fuel planning (p.278)","h":"chapters/nav-16.html#n-principles-of-fuel-planning-p-278"},{"t":"Lift","d":"aerodynamic force at 90° to the relative airflow (flight path). Total reaction (TR): resultant of all aerodynamic forces on the wing, acting through the centre of pressure; it resolves into lift and drag.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Lift","d":"Di and CDi ∝ CL². At the high AoA of take-off induced drag can be up to ¾ of total drag. Higher wing loading → more induced drag.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Factors affecting induced drag (2-17)","h":"chapters/hb-02.html#n-factors-affecting-induced-drag-2-17"},{"t":"Lift","d":"only the normal component V cos Λ makes lift (V sin Λ flows spanwise) → CL and CLmax lower (early upper-surface separation).","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Wing planforms (2-28)","h":"chapters/hb-04.html#n-wing-planforms-2-28"},{"t":"Lift","d":"CLmax and stalling AoA are reduced compared with incompressible flow.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Effects of shockwaves (2-52)","h":"chapters/hb-08.html#n-effects-of-shockwaves-2-52"},{"t":"Light","d":"faint thunder, lightning at long intervals.","s":"Met 13","ch":"Thunderstorms","sec":"Intensity (p.117)","h":"chapters/met-13.html#n-intensity-p-117"},{"t":"Light aircraft / gliders / helicopters","d":"warning when wind is expected ≥ 17 kt (prefix \"Warnings for Light Aircraft\"); not sent beyond the aerodrome.","s":"Met 21","ch":"Met Services for Aviation","sec":"Warnings (p.200)","h":"chapters/met-21.html#n-warnings-p-200"},{"t":"Lightning","d":"needs ~3×10⁶ V/m in clear air (~1×10⁶ V/m in cloud); usually not catastrophic (aircraft bonding) but burns/holes, compass errors, damaged electronics, radio noise, temporary blinding. Most likely between +10°C and −10°C. Thunder = shock wave from the heated air.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"Liquid swirl","d":"fluid dragged round in turns carries the magnets in the direction of turn; adds to or reduces turning error; at the equator it is the only turning error.","s":"Nav 8","ch":"Magnetism and Compasses","sec":"Errors due to dip (direct-reading compass)","h":"chapters/nav-08.html#n-errors-due-to-dip-direct-reading-compass"},{"t":"Little \"m\"","d":"cruising IAS ÷ VMD. Theoretically best range is at the highest altitude where m = 1 (IAS = VMD at Mcrit); in practice cruise lower so IAS and m rise to 1.19 (cruise climb) or 1.32 (constant altitude).","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Cruise, range and endurance (2-48)","h":"chapters/hb-07.html#n-cruise-range-and-endurance-2-48"},{"t":"LMT (Local Mean Time)","d":"time on the observer's meridian measured from the mean sun's transit of the observer's anti-meridian (midnight = 0000). Places east are ahead, west behind.","s":"Nav 5","ch":"Time","sec":"Basics","h":"chapters/nav-05.html#n-basics"},{"t":"Load factor","d":"Vs × √n — a 4 g pull doubles the stall speed.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Basic stalling speed and what changes it (2-21)","h":"chapters/hb-03.html#n-basic-stalling-speed-and-what-changes-it-2-21"},{"t":"Load factor n = 1 ÷ cos φ","d":"depends on bank angle only (60° → 2 g); rises ever faster with bank.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Steady turn (2-46)","h":"chapters/hb-07.html#n-steady-turn-2-46"},{"t":"Loading index (LI)","d":"scaled-down moment; DOI: index at the DOM. Ballast: removable or fixed mass to bring the CG into range.","s":"Nav 14","ch":"Mass and Balance","sec":"Definitions","h":"chapters/nav-14.html#n-definitions"},{"t":"Local / Area forecast","d":"3 times a day, valid 12 h: issued 0700 (valid 0730–1930), 1300 (1330–0130), 1800 (1830–0930) IST. Area = 100 NM or more; local = 50 NM. Contains surface wind, visibility, weather, cloud, upper winds/temps, sunrise/sunset, warnings.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"Location indicators","d":"4 letters. ICAO divides the world into 22 AFSRAs (non-overlapping). 1st letter = AFSRA (India: V), 2nd = State/FIR (India: A Mumbai, E Kolkata and Guwahati sub-FIR, I Delhi, O Chennai), 3rd–4th = place (e.g. VIDP Delhi, VABB Mumbai, VOMM Chennai). Assigned by States, supervised by ICAO.","s":"Reg 5","ch":"Air Traffic Services","sec":"ATS units and FIRs (p.139–140)","h":"chapters/reg-05.html#n-ats-units-and-firs-p-139-140"},{"t":"Long-period oscillation (phugoid)","d":"slow oscillation in pitch, height and speed at a nearly constant AoA — an exchange of potential and kinetic energy; easily controlled by the pilot.","s":"Handbook 5","ch":"Stability","sec":"Dynamic stability (2-34)","h":"chapters/hb-05.html#n-dynamic-stability-2-34"},{"t":"Longeron","d":"main fore–aft member. Stringer: lighter longitudinal member. Frames/formers: circumferential; they resist hoop stress. Bulkheads: transverse walls.","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Airframe construction (3-5)","h":"chapters/hb-10.html#n-airframe-construction-3-5"},{"t":"Longitude","d":"angle at the centre along the equator from the prime (Greenwich) meridian (datum) to the meridian of the place, 0–180° E or W.","s":"Nav 2","ch":"The Earth","sec":"Longitude and meridians","h":"chapters/nav-02.html#n-longitude-and-meridians"},{"t":"Longitudinal dihedral","d":"the tailplane is set at a smaller incidence than the wing — needed for positive stability.","s":"Handbook 5","ch":"Stability","sec":"Longitudinal static stability (2-32 to 2-33)","h":"chapters/hb-05.html#n-longitudinal-static-stability-2-32-to-2-33"},{"t":"Lost on the manoeuvring area","d":"pilot stops and simultaneously tells ATS (last known position). If the pilot knows the aircraft is on a runway: tell ATS, vacate via a nearby taxiway if possible, then stop. A vehicle driver: tell ATS, vacate to a safe distance, then stop.","s":"Reg 8","ch":"Procedures for Aerodrome Control Service","sec":"Information from the tower (p.208–211)","h":"chapters/reg-08.html#n-information-from-the-tower-p-208-211"},{"t":"Lost procedure","d":"climb (range of radios/radar), use VOR/ADF/GPS, contact ATC (DF, radar), emergency 121.5 MHz, squawk 7700.","s":"Nav 9","ch":"Dead Reckoning","sec":"Time and DR position","h":"chapters/nav-09.html#n-time-and-dr-position"},{"t":"Low (L)","d":"closed isobar(s), lowest at centre. 2+ closed isobars = depression; stronger = cyclone / severe cyclone. N hemisphere winds anticlockwise and converging → upward motion → bad weather, but visibility better than in a high. Winds back. Surface wind < 17 kt (for a \"low\").","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure patterns (p.21–22) (isobars at 2 hPa)","h":"chapters/met-02.html#n-pressure-patterns-p-21-22-isobars-at-2-hpa"},{"t":"Low-level / VFR flights","d":"up to FL100 (FL150 or above in mountains); poor visibility (≤ 5000 m), phenomena likely to lower widespread visibility below 5000 m, cloud affecting flight, SIGMET.","s":"Met 28","ch":"Met Documentation and Briefing","sec":"Briefing (p.260–261)","h":"chapters/met-28.html#n-briefing-p-260-261"},{"t":"Low-level jet (LLJ)","d":"strong winds at 1–3 km in the SW monsoon over the Peninsula; continuation of the Somali jet off East Africa; enhances monsoon rain.","s":"Met 15","ch":"Jet Streams","sec":"Tropical Easterly Jet (p.143)","h":"chapters/met-15.html#n-tropical-easterly-jet-p-143"},{"t":"Low-level WS","d":"along final approach, runway, take-off and initial climb. Vertical WS: change of horizontal wind with height. Horizontal WS: with distance. Up/downdraughts: change of the vertical component with distance.","s":"Met 6","ch":"Winds","sec":"Wind shear (p.54–55)","h":"chapters/met-06.html#n-wind-shear-p-54-55"},{"t":"LRC (long-range cruise)","d":"about 4% faster than the still-air best-range speed for 99% of the range.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Cruise, range and endurance (2-48)","h":"chapters/hb-07.html#n-cruise-range-and-endurance-2-48"},{"t":"MAC (mean aerodynamic chord)","d":"chord of an equivalent rectangular wing; CG often given as % MAC (LeMAC/TeMAC give its position). For longitudinal stability the CG must be ahead of the centre of lift.","s":"Nav 14","ch":"Mass and Balance","sec":"Definitions","h":"chapters/nav-14.html#n-definitions"},{"t":"Mach trim","d":"automatically adds nose-up trim at high Mach to cancel Mach tuck and keep the stick-force gradient; operates only at high Mach.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Designs for high-speed flight (2-53 to 2-54)","h":"chapters/hb-08.html#n-designs-for-high-speed-flight-2-53-to-2-54"},{"t":"Mach tuck","d":"CP back → nose-down → Mach trimmer. Area rule = waisted fuselage against interference/wave drag.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Exam traps","h":"chapters/hb-08.html#n-exam-traps"},{"t":"Madden–Julian Oscillation (MJO)","d":"eastward-moving (W → E) equatorial wave of cloud, rain, wind and pressure, 30–60-day cycle (Madden & Julian, 1971); over the Indian Ocean in the monsoon → good rain; shorter (~30-day) cycle → better monsoon (2–3 good spells); ≥ 40 days reduces rain.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"G. Other systems influencing the SW monsoon","h":"chapters/met-30.html#n-g-other-systems-influencing-the-sw-monsoon"},{"t":"Magnetic direction (°M)","d":"measured from magnetic north — where a freely suspended magnet points (the magnetic and geographic axes are not aligned).","s":"Nav 6","ch":"Compass and Directions","sec":"Three norths","h":"chapters/nav-06.html#n-three-norths"},{"t":"Mandatory read-back","d":"ATC route clearances; clearances to enter, land on, take off from, hold short of, cross and backtrack on a runway; runway in use, altimeter settings, SSR codes, level, heading and speed instructions, transition levels (even from ATIS). Controller checks the read-back. CPDLC messages need no voice read-back.","s":"Reg 5","ch":"Air Traffic Services","sec":"ATC service (p.142–144)","h":"chapters/reg-05.html#n-atc-service-p-142-144"},{"t":"Manoeuvre point","d":"CG position at which wing and tail moments balance in a manoeuvre; because of the extra tail effectiveness it lies behind the neutral point.","s":"Handbook 5","ch":"Stability","sec":"Manoeuvre stability (2-34)","h":"chapters/hb-05.html#n-manoeuvre-stability-2-34"},{"t":"Manoeuvring area","d":"take-off, landing and taxiing, excluding aprons. Movement area = manoeuvring area + aprons.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aerodrome areas (p.4–36)","h":"chapters/reg-01.html#n-aerodrome-areas-p-4-36"},{"t":"Manual","d":"cables and pulleys. Primary stops set the range; secondary stops back them up; fairleads guide cables clear of structure; tension gives positive action both ways, removes backlash, and is temperature-compensated. Inspect tension, locking, range, temperature compensation — always a duplicate inspection by another person. Cables are light, strong, damage-tolerant, compact.","s":"Handbook 11","ch":"Landing Gear, Brakes, Tyres and Powered Controls","sec":"Flight-control systems (3-14)","h":"chapters/hb-11.html#n-flight-control-systems-3-14"},{"t":"Map","d":"graticule plus lots of ground detail. Chart: graticule with little detail, made for a purpose (navigation).","s":"Nav 3","ch":"Projections","sec":"Why projections distort","h":"chapters/nav-03.html#n-why-projections-distort"},{"t":"MAPt","d":"point at or before which the missed approach must start to protect obstacle clearance.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Approaches and runways (p.16–19)","h":"chapters/reg-01.html#n-approaches-and-runways-p-16-19"},{"t":"Mascarene High","d":"semi-permanent high in the S Indian Ocean (~4000 km from India), develops from mid-April; drives cross-equatorial flow; stronger high → stronger surge, heavier W-coast rain.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"G. Other systems influencing the SW monsoon","h":"chapters/met-30.html#n-g-other-systems-influencing-the-sw-monsoon"},{"t":"Mass","d":"quantity of matter in a body. Weight (newtons) = mass × g: the force pulling it towards the earth's centre. M = W / g.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Physical terms (2-3)","h":"chapters/hb-01.html#n-physical-terms-2-3"},{"t":"Mass balance","d":"a weight ahead of the hinge line brings the control surface's CG to (or ahead of) the hinge → prevents control-surface flutter.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Hinges, horns and mass balance (2-41)","h":"chapters/hb-06.html#n-hinges-horns-and-mass-balance-2-41"},{"t":"Maximum EAS (VD/VNE line)","d":"exceed it and risk panel loss, aileron reversal, divergence, flutter; usually a 5–10% caution margin.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Manoeuvre envelope (2-56)","h":"chapters/hb-08.html#n-manoeuvre-envelope-2-56"},{"t":"Maxtra level","d":"in the stratosphere; above it no contrails form.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Condensation trails (p.83–84)","h":"chapters/met-08.html#n-condensation-trails-p-83-84"},{"t":"Mcrit","d":"first local M 1.0; more AoA/weight → lower Mcrit. Transonic Mcrit–1.2; hypersonic > 5.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Exam traps","h":"chapters/hb-08.html#n-exam-traps"},{"t":"Mcrit (critical Mach number)","d":"the free-stream Mach number at which the local flow first reaches M 1.0 somewhere on the aircraft. Beyond it shockwaves form: CL falls, drag and temperature rise. Higher AoA → lower Mcrit; so more weight → lower Mcrit (more AoA).","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Mach number and speed regimes (2-49)","h":"chapters/hb-08.html#n-mach-number-and-speed-regimes-2-49"},{"t":"MDA/H","d":"in a 2D approach or circling, do not descend below without the required visual reference. MDH is referenced to aerodrome elevation, or threshold elevation if that is more than 2 m (7 ft) below aerodrome elevation; circling MDH to aerodrome elevation.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Minimum altitudes (p.18–21)","h":"chapters/reg-01.html#n-minimum-altitudes-p-18-21"},{"t":"Mdet (detachment Mach number)","d":"above it the bow shock moves very little with speed — the upper limit of the transonic region.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Mach number and speed regimes (2-49)","h":"chapters/hb-08.html#n-mach-number-and-speed-regimes-2-49"},{"t":"MEA","d":"en-route altitude giving nav-aid reception, ATS communications, airspace compliance and obstacle clearance.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Minimum altitudes (p.18–21)","h":"chapters/reg-01.html#n-minimum-altitudes-p-18-21"},{"t":"Mean aerodynamic chord (MAC)","d":"the chord through the centroid of the wing area; a rectangular wing of that chord would have the same pitching-moment characteristics.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Mean camber line","d":"line from LE to TE midway between the upper and lower surfaces; max camber: greatest distance between it and the chord line.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Mean solar day","d":"based on the mean sun, a fictitious sun moving at constant speed along the celestial equator = 24 h.","s":"Nav 1","ch":"The Solar System","sec":"Year and day","h":"chapters/nav-01.html#n-year-and-day"},{"t":"Mercator","d":"meridians parallel → chart convergence 0; correct only at the equator. All RLs straight; GCs curve concave to the equator (on the polar side of the RL).","s":"Nav 4","ch":"Convergency","sec":"On charts","h":"chapters/nav-04.html#n-on-charts"},{"t":"Mercury barometer","d":"most accurate; pressure balanced by a mercury column.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Measurement (p.15)","h":"chapters/met-02.html#n-measurement-p-15"},{"t":"Meridian","d":"semi-great circle pole to pole joining places of equal longitude; defines true north–south; crosses the equator at 90°. Anti-meridian = longitude 180° away, opposite name (030°W ↔ 150°E); meridian + anti-meridian = a full great circle.","s":"Nav 2","ch":"The Earth","sec":"Longitude and meridians","h":"chapters/nav-02.html#n-longitude-and-meridians"},{"t":"Meridians","d":"parallel, equally spaced, vertical straight lines. Parallels: straight, spacing increases away from the equator.","s":"Nav 3","ch":"Projections","sec":"Mercator (direct)","h":"chapters/nav-03.html#n-mercator-direct"},{"t":"Mesoscale Convective Complex (MCC)","d":"near-circular cluster of interacting TS over a huge area (~1000× an air-mass TS); new cells keep forming → life 6–24 h; severe weather, tornadoes, flash floods; near fronts and in the ITCZ.","s":"Met 13","ch":"Thunderstorms","sec":"Types (p.112–113)","h":"chapters/met-13.html#n-types-p-112-113"},{"t":"Mesoscale weather","d":"local phenomena such as TS, DS, land/sea breeze, katabatic wind.","s":"Met 13","ch":"Thunderstorms","sec":"Types (p.112–113)","h":"chapters/met-13.html#n-types-p-112-113"},{"t":"Met sub-divisions","d":"NW India J&K, HP, Punjab, Haryana, Delhi, E & W UP, Rajasthan, Uttarakhand · East Jharkhand, Bihar, Odisha, WB, Sikkim · NE Arunachal, Nagaland, Mizoram, Manipur, Tripura, Assam, Meghalaya · South TN, AP, Kerala, Karnataka, Lakshadweep, A&N · West Konkan & Goa, Madhya Maharashtra, Marathwada, Gujarat, Saurashtra & Kutch · Central MP, Chhattisgarh, Vidarbha.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"D. Miscellaneous terms","h":"chapters/met-30.html#n-d-miscellaneous-terms"},{"t":"METAR","d":"routine aerodrome report, every half hour, with a TREND appended.","s":"Met 21","ch":"Met Services for Aviation","sec":"Observations and reports","h":"chapters/met-21.html#n-observations-and-reports"},{"t":"Microburst","d":"concentrated downdraught ~4 km across, lasts 1–5 min; most hazardous; surface wind difference up to 90 kt, even opposite directions. Wet (heavy rain, evaporative cooling) or dry (high-based TS, virga evaporating under the anvil/AC).","s":"Met 6","ch":"Winds","sec":"Wind shear (p.54–55)","h":"chapters/met-06.html#n-wind-shear-p-54-55"},{"t":"Microlight","d":"single-seater MAUW ≤ 330 kg, two-seater ≤ 450 kg, wing area ≥ 10 m² in both; excludes hang gliders and para-planes. Flown on a Permit to Fly.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aircraft and their kinds (p.3–38)","h":"chapters/reg-01.html#n-aircraft-and-their-kinds-p-3-38"},{"t":"Mid-tropospheric (subtropical) cyclone","d":"circulation at 500–700 hPa around 18–28°N, 60–80°E with a surface trough; heavy rain over W India / Gujarat / NE Arabian Sea (W/SW of centre); e.g. Mumbai floods 2005.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Miner's rule","d":"cumulative damage from loads of different sizes: n₁/N₁ + n₂/N₂ + … = 1 at failure (n = cycles applied, N = cycles to failure at that stress, from the S–N curve). E.g. 80% of ultimate fails after ~100 cycles; 20% needs ~10 million.","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Metal fatigue (3-4)","h":"chapters/hb-10.html#n-metal-fatigue-3-4"},{"t":"Minimum Sector Altitude","d":"lowest altitude giving 300 m (1000 ft) clearance over all objects within a sector of a 46 km (25 NM) circle centred on a radio aid.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Mintra level","d":"below it no contrails form; for jets ≈ the level where temperature is about −45°C (at 100% RH).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Condensation trails (p.83–84)","h":"chapters/met-08.html#n-condensation-trails-p-83-84"},{"t":"MMEL","d":"by the type-design organisation, approved by the State of Design. MEL: by the operator, same as or more restrictive than the MMEL.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Operations and people (p.4–34)","h":"chapters/reg-01.html#n-operations-and-people-p-4-34"},{"t":"MMO","d":"maximum operating Mach number; Mcrit lies above it.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Mach number and speed regimes (2-49)","h":"chapters/hb-08.html#n-mach-number-and-speed-regimes-2-49"},{"t":"MOCA","d":"gives only the required obstacle clearance for a segment.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Minimum altitudes (p.18–21)","h":"chapters/reg-01.html#n-minimum-altitudes-p-18-21"},{"t":"Moderate","d":"loud thunder, frequent lightning, moderate/heavy showers, light hail; max wind 15–40 kt.","s":"Met 13","ch":"Thunderstorms","sec":"Intensity (p.117)","h":"chapters/met-13.html#n-intensity-p-117"},{"t":"Moist air","d":"normal air; also called \"unsaturated\" or \"dry\" air at its temperature and pressure.","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Momentum","d":"mass × velocity (kg m/s): the tendency to keep moving once moving.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Physical terms (2-3)","h":"chapters/hb-01.html#n-physical-terms-2-3"},{"t":"Momentum (deflection) theory","d":"the wing deflects a stream of air; force = rate of change of momentum = mass flow × Δv (book's worked form F ≈ 1.4 ρ A V² for its vector example). The force grows with angle of attack and camber — how a windmill works.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Streamline flow and lift theories (2-6 to 2-7)","h":"chapters/hb-01.html#n-streamline-flow-and-lift-theories-2-6-to-2-7"},{"t":"Monsoon","d":"any markedly seasonal wind (E and SE Asia).","s":"Met 6","ch":"Winds","sec":"Named winds (p.61–62)","h":"chapters/met-06.html#n-named-winds-p-61-62"},{"t":"Monsoon depressions","d":"2–3 a month from the north Bay, moving N/W, spreading rain over central and north India.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Monsoon trough","d":"normal position Ganganagar–Allahabad–Kolkata–head Bay ≈ ITCZ; Bay branch north of it, Arabian Sea branch south; slopes south with height (700 hPa ≈ 22°N Gujarat–Odisha; 500 hPa ≈ 10–15°N); its N–S swings govern rainfall.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Montreal 1971","d":"unlawful acts against the safety of civil aviation: violence on board, destroying/damaging aircraft, placing devices, damaging navigation facilities, false information.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Unlawful acts conventions (p.50–53)","h":"chapters/reg-02.html#n-unlawful-acts-conventions-p-50-53"},{"t":"Montreal 1991","d":"marking of plastic explosives for detection.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Unlawful acts conventions (p.50–53)","h":"chapters/reg-02.html#n-unlawful-acts-conventions-p-50-53"},{"t":"Montreal Protocol 1988","d":"extends to violence at airports serving international civil aviation.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Unlawful acts conventions (p.50–53)","h":"chapters/reg-02.html#n-unlawful-acts-conventions-p-50-53"},{"t":"Mountain (lee) wave","d":"oscillations on the lee side of high ground due to disturbance of horizontal flow; reach great heights and far downwind.","s":"Met 16","ch":"CAT and Mountain Waves","sec":"Mountain waves — definition and conditions (p.149)","h":"chapters/met-16.html#n-mountain-waves-definition-and-conditions-p-149"},{"t":"Movement area condition","d":"works, rough surfaces, water/snow/slush/ice/frost, de-icing fluids, snow banks, temporary hazards incl. parked aircraft, visual aid failures, power supply failure.","s":"Reg 8","ch":"Procedures for Aerodrome Control Service","sec":"Information from the tower (p.208–211)","h":"chapters/reg-08.html#n-information-from-the-tower-p-208-211"},{"t":"MSA","d":"lowest altitude giving 300 m (1,000 ft) clearance above all objects within a sector of a 46 km (25 NM) circle centred on a radio aid.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Minimum altitudes (p.18–21)","h":"chapters/reg-01.html#n-minimum-altitudes-p-18-21"},{"t":"MSL","d":"average of high and low tides.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Altimetry definitions (p.17)","h":"chapters/met-02.html#n-altimetry-definitions-p-17"},{"t":"Multi-cell cluster","d":"cells last ~20 min each, the cluster for hours; near mountains, cold fronts, troughs.","s":"Met 13","ch":"Thunderstorms","sec":"Classification by structure (p.113)","h":"chapters/met-13.html#n-classification-by-structure-p-113"},{"t":"Multi-cell line = squall line","d":"along/ahead of cold fronts; hundreds of km; heavy rain, hail, lightning, very strong winds, isolated tornadoes. A very powerful one = derecho. Also in outer rain bands of tropical cyclones.","s":"Met 13","ch":"Thunderstorms","sec":"Classification by structure (p.113)","h":"chapters/met-13.html#n-classification-by-structure-p-113"},{"t":"Nacreous (mother-of-pearl)","d":"upper stratosphere; like CI or AC lenticularis with strong irisation; ice or supercooled drops; seen mainly in Scotland and Scandinavia.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"The ten genera (p.79–80)","h":"chapters/met-08.html#n-the-ten-genera-p-79-80"},{"t":"Nautical mile","d":"arc subtending 1′ at the earth's centre (along a great circle/meridian). Varies slightly: ~6046 ft at the equator, ~6080 ft (standard, at 45°), ~6108–6170 ft at the poles (book quotes 6170) — longer at the poles. 1° = 60 NM; 1′ = 1 NM. Defined value 1852 m = 6076 ft.","s":"Nav 7","ch":"Distances on the Earth","sec":"Units","h":"chapters/nav-07.html#n-units"},{"t":"Navigation lights","d":"red on the left, 110° (from dead ahead to 110° left); green on the right, 110°; white tail light, 140° (70° each side of dead astern).","s":"Reg 4","ch":"Rules of the Air","sec":"Lights to be displayed (p.81–82, 113–115)","h":"chapters/reg-04.html#n-lights-to-be-displayed-p-81-82-113-115"},{"t":"NDB","d":"tracks to/from the NDB diverging at least 30°, at least one aircraft 15 NM or more from it.","s":"Reg 6","ch":"Separation Methods and Minima","sec":"Lateral separation (p.170–172)","h":"chapters/reg-06.html#n-lateral-separation-p-170-172"},{"t":"Near-parallel runways","d":"extended centre lines converge/diverge by 15° or less.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aerodrome areas (p.4–36)","h":"chapters/reg-01.html#n-aerodrome-areas-p-4-36"},{"t":"Neutral point","d":"the CG position at which the aircraft is neutrally stable — the reference for longitudinal static stability. CG behind it → unstable; the CG is never allowed to reach it.","s":"Handbook 5","ch":"Stability","sec":"Longitudinal static stability (2-32 to 2-33)","h":"chapters/hb-05.html#n-longitudinal-static-stability-2-32-to-2-33"},{"t":"Neutrally stable","d":"CG at or near the aerodynamic centre (neutral point); no restoring tendency.","s":"Nav 14","ch":"Mass and Balance","sec":"CG position effects","h":"chapters/nav-14.html#n-cg-position-effects"},{"t":"Newton's laws","d":"(1) a body stays at rest or in uniform straight-line motion unless a force acts; (2) rate of change of momentum ∝ applied force, in the force's direction; (3) action and reaction are equal and opposite.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Laws (2-4)","h":"chapters/hb-01.html#n-laws-2-4"},{"t":"Night","d":"friction layer shrinks; upper wind cannot reach down → surface wind weak and backed (crosses isobars more); marked wind shear near 500 m (strong above, weak below) — a hazard.","s":"Met 6","ch":"Winds","sec":"Diurnal variation of surface wind (p.53–54)","h":"chapters/met-06.html#n-diurnal-variation-of-surface-wind-p-53-54"},{"t":"Night","d":"end of evening civil twilight to start of morning civil twilight (sun's centre 6° below the horizon).","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Flight plans and times (p.13–35)","h":"chapters/reg-01.html#n-flight-plans-and-times-p-13-35"},{"t":"Noctilucent","d":"upper mesosphere (80–85 km); bluish/silvery; visible just after sunset/before sunrise, 45°–72°N (mostly ~55°N), late May to mid-August; ice particles.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"The ten genera (p.79–80)","h":"chapters/met-08.html#n-the-ten-genera-p-79-80"},{"t":"Nocturnal radiation","d":"radiation from the earth at night (no incoming short wave). Warmer earth → more intense nocturnal radiation.","s":"Met 3","ch":"Temperature","sec":"Solar, terrestrial and nocturnal radiation (p.31)","h":"chapters/met-03.html#n-solar-terrestrial-and-nocturnal-radiation-p-31"},{"t":"Non-precision approach runway","d":"visibility not less than 1,000 m.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Approaches and runways (p.16–19)","h":"chapters/reg-01.html#n-approaches-and-runways-p-16-19"},{"t":"Non-scheduled flights","d":"signed and submitted by the PIC, or by an approved flight dispatcher of the operator/authorised handling agency. Those persons may take ATS, COMM and MET briefing.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"India: filing flight plans","h":"chapters/nav-16.html#n-india-filing-flight-plans"},{"t":"Non-scheduled flights into/across Indian airspace","d":"state the DGCA authority (YA No.) or AHQ authority (AOR No.) in Item 18.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"India: filing flight plans","h":"chapters/nav-16.html#n-india-filing-flight-plans"},{"t":"Normal shock","d":"at right angles to the flow; no change of direction; flow behind is always subsonic; greatest compression and loss of total pressure (kinetic energy turned to heat).","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Shockwaves (2-51)","h":"chapters/hb-08.html#n-shockwaves-2-51"},{"t":"Normand's theorem","d":"draw DALR up from the dry bulb, SALR from the wet bulb and the isohygric from the dew point — the three meet at the Normand point. The first one from surface values = LCL (likely cloud base).","s":"Met 9","ch":"Stability and Instability","sec":"Tephigram (p.90–91)","h":"chapters/met-09.html#n-tephigram-p-90-91"},{"t":"Nose raised (higher AoA)","d":"vertical rate of descent less (more CD), spin radius less (less CL), spin rate faster.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Spin (2-24)","h":"chapters/hb-03.html#n-spin-2-24"},{"t":"Nowcasting","d":"< 24 h (TREND, TAF, SIGMET, local forecasts, aerodrome warnings).","s":"Met 21","ch":"Met Services for Aviation","sec":"Types of forecast by range","h":"chapters/met-21.html#n-types-of-forecast-by-range"},{"t":"NPA","d":"2D approach Type A. APV: PBN 3D approach Type A. PA: ILS, MLS, GLS, SBAS Cat I; 3D Type A or B.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Approaches and runways (p.16–19)","h":"chapters/reg-01.html#n-approaches-and-runways-p-16-19"},{"t":"Oblique","d":"cylinder tangent along a chosen great circle (route). Conformal; scale correct along that GC; within ~500 NM treat as constant scale.","s":"Nav 3","ch":"Projections","sec":"Transverse and oblique Mercator","h":"chapters/nav-03.html#n-transverse-and-oblique-mercator"},{"t":"Oblique shock","d":"inclined; the flow changes direction; behind it the flow may be subsonic or supersonic; less energy loss.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Shockwaves (2-51)","h":"chapters/hb-08.html#n-shockwaves-2-51"},{"t":"OCA/H","d":"lowest altitude/height used to meet obstacle clearance criteria (OCA from MSL; OCH from threshold, or aerodrome elevation for NPA/circling).","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Minimum altitudes (p.18–21)","h":"chapters/reg-01.html#n-minimum-altitudes-p-18-21"},{"t":"Off ATS routes","d":"points normally ≤ 30 minutes or 370 km (200 NM) apart, plus every change point. Where required: east–west flights between 70°N and 70°S by half/whole degrees of latitude at 10° longitude intervals (20° outside those latitudes), points ideally ≤ 1 hour apart; north–south flights by whole degrees of longitude at parallels 5° apart.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Item 15 — Route","h":"chapters/nav-16.html#n-item-15-route"},{"t":"Off track","d":"adjust heading to regain track forthwith. Deviation from assigned Mach/IAS: inform ATS immediately.","s":"Reg 4","ch":"Rules of the Air","sec":"ATC clearances and deviations (p.85–86)","h":"chapters/reg-04.html#n-atc-clearances-and-deviations-p-85-86"},{"t":"Oil-in-compression","d":"oil forced through damping orifices; above a set pressure a valve opens to a reserve chamber — soft for small loads, firm for hard landings.","s":"Handbook 11","ch":"Landing Gear, Brakes, Tyres and Powered Controls","sec":"Shock absorbers (3-10)","h":"chapters/hb-11.html#n-shock-absorbers-3-10"},{"t":"Oleo-pneumatic","d":"gas (air/nitrogen) absorbs the shock; oil through a restricting orifice/clack valve damps the rebound (controls extension). In the static condition the weight is held by gas and oil pressure.","s":"Handbook 11","ch":"Landing Gear, Brakes, Tyres and Powered Controls","sec":"Shock absorbers (3-10)","h":"chapters/hb-11.html#n-shock-absorbers-3-10"},{"t":"On ATS routes","d":"first ATS route designator (or DCT + joining point + route), then every point where speed/level, route or flight rules change, each followed by the next route designator (even if the same) or DCT. Point of transition between lower and upper routes in the same direction need not be inserted.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Item 15 — Route","h":"chapters/nav-16.html#n-item-15-route"},{"t":"Onward clearance time","d":"when held en route or at a fix other than the IAF, the time the aircraft can expect to leave that fix; also advise if more holding is expected later.","s":"Reg 7","ch":"Separation in the Vicinity of Aerodromes","sec":"Expected approach time (p.200)","h":"chapters/reg-07.html#n-expected-approach-time-p-200"},{"t":"Open system","d":"simple, small aircraft; the engine-driven pump circulates fluid continuously; one service at a time.","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Hydraulics — principles (3-6)","h":"chapters/hb-10.html#n-hydraulics-principles-3-6"},{"t":"Operating mass (OM)","d":"DOM + take-off fuel. Zero fuel mass (ZFM) = DOM + traffic load. Take-off mass (TOM) at the start of the take-off run. Ramp/taxi mass = TOM + taxi fuel.","s":"Nav 14","ch":"Mass and Balance","sec":"Mass terms","h":"chapters/nav-14.html#n-mass-terms"},{"t":"Operational control","d":"authority over initiation, continuation, diversion or termination of a flight.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Operations and people (p.4–34)","h":"chapters/reg-01.html#n-operations-and-people-p-4-34"},{"t":"Orthomorphic / conformal","d":"bearings shown correctly. Needs (a) meridians and parallels crossing at 90° and (b) scale the same in all directions at a point.","s":"Nav 3","ch":"Projections","sec":"Orthomorphism (conformality)","h":"chapters/nav-03.html#n-orthomorphism-conformality"},{"t":"Other factors","d":"alternate, diversion and hold, circuit and landing, reserve. A diversion is assumed after an unsuccessful landing attempt, so diversion tables already include overshoot, climb to a suitable level and reserve fuel.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Principles of fuel planning (p.278)","h":"chapters/nav-16.html#n-principles-of-fuel-planning-p-278"},{"t":"Outputs","d":"pressure altitude (static pressure corrected to the ICAO Standard Atmosphere); airspeed (IAS, or TAS for DR/inertial navigation); air density (gas laws, for engine controls); Mach number (from pitot and static pressures); air temperature (corrected for frictional heating and compression at the probe); angle of attack (measured AoA corrected for airspeed = true AoA); rates of change of altitude and speed.","s":"Nav 17","ch":"Air Data Systems","sec":"Air data system","h":"chapters/nav-17.html#n-air-data-system"},{"t":"Overbalance","d":"CP ahead of the hinge → controls get lighter as deflection increases (dangerous).","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Hinges, horns and mass balance (2-41)","h":"chapters/hb-06.html#n-hinges-horns-and-mass-balance-2-41"},{"t":"Overtaking","d":"approaching from the rear within 70° of the other's plane of symmetry (at night you could see neither navigation light, only the white tail light). The overtaken aircraft has right of way; the overtaker keeps clear by altering heading to the right, whether climbing, descending or level, until entirely past and clear.","s":"Reg 4","ch":"Rules of the Air","sec":"Right of way (p.80–81)","h":"chapters/reg-04.html#n-right-of-way-p-80-81"},{"t":"Ozone (O₃)","d":"forms in the upper atmosphere, absorbs UV and raises temperature; protects from skin cancer, sunburn, cataracts.","s":"Met 1","ch":"Atmosphere","sec":"CO₂, ozone and particles (p.3)","h":"chapters/met-01.html#n-co-ozone-and-particles-p-3"},{"t":"Ozone hole","d":"thinning, mainly over polar regions, caused by pollution and halocarbons/CFCs (refrigerants, solvents) that release halogens in the stratosphere by photodissociation.","s":"Met 1","ch":"Atmosphere","sec":"CO₂, ozone and particles (p.3)","h":"chapters/met-01.html#n-co-ozone-and-particles-p-3"},{"t":"P — Position","d":"dynamic-pressure interference at the static source, from (a) incorrect static source position, (b) induced causes (slip/skid, low speed, high or low angle of attack, standby/alternate source), (c) ground effect (wing-tip vortices and airflow around the aircraft). Position error makes the altimeter always under-read.","s":"Nav 18","ch":"Altimeter","sec":"Errors — \"BLIP PBT\"","h":"chapters/nav-18.html#n-errors-blip-pbt"},{"t":"P — Pressure","d":"high → low pressure: reads higher than actual; low → high: reads lower than actual.","s":"Nav 18","ch":"Altimeter","sec":"Errors — \"BLIP PBT\"","h":"chapters/nav-18.html#n-errors-blip-pbt"},{"t":"P/R/D areas","d":"nationality letters + P/R/D + number not repeated in the State, e.g. VA(P)-2 (Mumbai FIR prohibited area 2), VO(R)-81, VE(D)-72. Prohibited = not at any time; danger area times notified by NOTAM.","s":"Reg 5","ch":"Air Traffic Services","sec":"ATS units and FIRs (p.139–140)","h":"chapters/reg-05.html#n-ats-units-and-firs-p-139-140"},{"t":"PANS","d":"approved by the Council for worldwide use; procedures not mature enough for SARPs or too detailed / often amended. SUPPS (Doc 7030): like PANS but for regions only.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"ICAO publications (p.47–49)","h":"chapters/reg-02.html#n-icao-publications-p-47-49"},{"t":"Parallels of latitude","d":"small circles parallel to the equator (the equator is the only parallel that is a great circle); they cut every meridian at 90° → rhumb lines.","s":"Nav 2","ch":"The Earth","sec":"Latitude","h":"chapters/nav-02.html#n-latitude"},{"t":"Parasite (zero-lift) drag","d":"Dp = ½ρV² CDp S. At the zero-lift AoA only parasite drag exists.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Parasite drag (2-15)","h":"chapters/hb-02.html#n-parasite-drag-2-15"},{"t":"Parts of the day (IST)","d":"early hours 0000–0400 · morning 0400–0800 · forenoon 0800–1200 · afternoon 1200–1600 · evening 1600–2000 · night 2000–2400.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"D. Miscellaneous terms","h":"chapters/met-30.html#n-d-miscellaneous-terms"},{"t":"Pause","d":"the rudder is initially shielded by the descending tailplane's wake.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Spin recovery (2-26)","h":"chapters/hb-03.html#n-spin-recovery-2-26"},{"t":"Petroleum in bulk","d":"receptacle over 900 litres.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Operations and people (p.4–34)","h":"chapters/reg-01.html#n-operations-and-people-p-4-34"},{"t":"Phugoid","d":"speed and height change at ~constant AoA, easy to control. Short period: AoA and g change, hard to control, PIO.","s":"Handbook 5","ch":"Stability","sec":"Exam traps","h":"chapters/hb-05.html#n-exam-traps"},{"t":"PIC","d":"pilot designated by the operator (or owner, in GA) as in command and charged with safe conduct. Co-pilot: licensed pilot in any piloting capacity other than PIC, excluding someone aboard only for instruction. Student PIC: trainee acting as PIC under an instructor's observation; if the instructor touches the controls it becomes dual.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Operations and people (p.4–34)","h":"chapters/reg-01.html#n-operations-and-people-p-4-34"},{"t":"Pitot tube","d":"senses impact (ram) air pressure; mounted where there is minimum disturbance, usually near the wing leading edge, piped to the back of the ASI case. Susceptible to dirt, water and ice — aircraft for instrument flight must have a heated pitot tube; inspect the tube and test the heater before flight. Its opening is nearly perpendicular to the relative wind.","s":"Nav 17","ch":"Air Data Systems","sec":"The pitot-static system","h":"chapters/nav-17.html#n-the-pitot-static-system"},{"t":"Planck's law","d":"distribution of radiated energy with wavelength (right-skewed curve).","s":"Met 3","ch":"Temperature","sec":"Insolation and radiation laws (p.30)","h":"chapters/met-03.html#n-insolation-and-radiation-laws-p-30"},{"t":"Planform","d":"maximum where the vortices are (tips); elliptical wing = minimum; more sweep → more Di; taper plus washout reduces it.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Factors affecting induced drag (2-17)","h":"chapters/hb-02.html#n-factors-affecting-induced-drag-2-17"},{"t":"Planform","d":"a rectangular wing stalls at the root first — good.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Stall behaviour and how designers tame it (2-20)","h":"chapters/hb-03.html#n-stall-behaviour-and-how-designers-tame-it-2-20"},{"t":"Polar cell (60–90°)","d":"air sinks and warms at the poles → polar high; surface outflow turned west → polar easterlies; meets warm subtropical air at the polar front (with the polar front jet).","s":"Met 20","ch":"General Circulation","sec":"Three-cell model (p.188–190)","h":"chapters/met-20.html#n-three-cell-model-p-188-190"},{"t":"Polar front","d":"between polar easterlies and mid-latitude westerlies (~60°), active in segments. Arctic front: between arctic and polar air. Mediterranean front: Pc Europe vs Tc N Africa (winter).","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Occlusions and others (p.134–135)","h":"chapters/met-14.html#n-occlusions-and-others-p-134-135"},{"t":"Polar orbiting","d":"650–1500 km; whole earth twice in 24 h, same place every 12 h (e.g. NOAA).","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Met satellites (p.210–213)","h":"chapters/met-22.html#n-met-satellites-p-210-213"},{"t":"Position error","d":"varies with aircraft type and external configuration; flight tests plot it against airspeed, altitude and configuration, and the manufacturer builds a correcting circuit for the static signal → calibrated airspeed, actual TAS, calibrated altitude, true Mach. So a CADC is tailored to one aircraft type and not usable in others.","s":"Nav 17","ch":"Air Data Systems","sec":"CADC errors (common to all instruments)","h":"chapters/nav-17.html#n-cadc-errors-common-to-all-instruments"},{"t":"Position reports","d":"time and level over each compulsory reporting point, and others on request.","s":"Reg 4","ch":"Rules of the Air","sec":"ATC clearances and deviations (p.85–86)","h":"chapters/reg-04.html#n-atc-clearances-and-deviations-p-85-86"},{"t":"Positive","d":"returns towards equilibrium. Neutral: stays where it was put. Negative (unstable): keeps diverging.","s":"Handbook 5","ch":"Stability","sec":"Stability and static stability (2-32)","h":"chapters/hb-05.html#n-stability-and-static-stability-2-32"},{"t":"Post-flight information","d":"report malfunctioning visual/non-visual aids or other facilities, and bird/wildlife hazards, without delay.","s":"Reg 10","ch":"Aeronautical Information Services","sec":"India (p.240–245)","h":"chapters/reg-10.html#n-india-p-240-245"},{"t":"Potential (convective) instability","d":"a whole layer lifted bodily becomes unstable because latent heat released at its moist bottom steepens its lapse rate; needs high RH low down, low RH higher up.","s":"Met 9","ch":"Stability and Instability","sec":"Stability criteria (p.89)","h":"chapters/met-09.html#n-stability-criteria-p-89"},{"t":"Power","d":"thrust line below the CG (nose-up moment) and propwash/jet downwash on the tail reduce stability — most at high power, low speed; propeller aircraft lose more with thrust changes.","s":"Handbook 5","ch":"Stability","sec":"Longitudinal static stability (2-32 to 2-33)","h":"chapters/hb-05.html#n-longitudinal-static-stability-2-32-to-2-33"},{"t":"Power available vs required","d":"the biggest vertical gap = best climb speed. Jets have a wide band of speeds with excess power; the curve crossings mark the minimum and maximum level-flight speeds at that power. Power required (drag × TAS) rises with altitude at constant EAS (TAS rises), and best ROC speed falls with altitude.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Steady climb (2-43)","h":"chapters/hb-07.html#n-steady-climb-2-43"},{"t":"Power-assisted","d":"hydraulics supply part of the force; the pilot keeps natural feel (∝ IAS²); the controls remain reversible.","s":"Handbook 11","ch":"Landing Gear, Brakes, Tyres and Powered Controls","sec":"Flight-control systems (3-14)","h":"chapters/hb-11.html#n-flight-control-systems-3-14"},{"t":"Pre-flight action","d":"become familiar with all available information; for flights away from the vicinity of an aerodrome and all IFR flights, study current weather reports and forecasts, fuel requirements and an alternative course of action.","s":"Reg 4","ch":"Rules of the Air","sec":"Applicability and responsibility (p.77–78)","h":"chapters/reg-04.html#n-applicability-and-responsibility-p-77-78"},{"t":"Pressure","d":"Sahara–Siberia high belt centred 45°N 105°E; India on its southern edge: high over N India, low over the Indian Ocean; ~4 isobars 1012–1018 hPa; shallow trough Kerala–Gujarat along the west coast; shallow ridge over the Gangetic plains.","s":"Met 19","ch":"Climatology of India","sec":"Winter (Jan–Feb) (p.171–173)","h":"chapters/met-19.html#n-winter-jan-feb-p-171-173"},{"t":"Pressure","d":"transition; temperature rising, pressure falling; weak gradient — only two isobars (1006, 1008 hPa) parallel to the coast; peninsular trough along 78°E (79°E near Chennai by May); weak low over Pakistan (upper Sindh), weak trough E UP/Bihar; low over Myanmar; closed high over the east-central Bay west of the Bay Islands.","s":"Met 19","ch":"Climatology of India","sec":"Summer / pre-monsoon (Mar–May) (p.173–175)","h":"chapters/met-19.html#n-summer-pre-monsoon-mar-may-p-173-175"},{"t":"Pressure","d":"low over Baluchistan (994 hPa); monsoon trough Sriganganagar – Allahabad – Kolkata – head Bay; high over the S hemisphere at 30°S 60°E; seven isobars (994–1008 hPa); steep gradient along the west coast; shallow lows over Arunachal and Myanmar.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Pressure","d":"flat; one isobar (1010 hPa) encloses India; monsoon trough moves to the Bay along 13°N; weak lows off Chennai and over Baluchistan.","s":"Met 19","ch":"Climatology of India","sec":"Post-monsoon / NE monsoon (Oct–Dec) (p.180–182)","h":"chapters/met-19.html#n-post-monsoon-ne-monsoon-oct-dec-p-180-182"},{"t":"Pressure","d":"QNH rounded down to whole hPa (996.6 → Q0996; 999.9 → Q0999); inches reported exactly (A3005). World range 850–1100 hPa.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Pressure altitude","d":"altimeter reading with 1013.2 hPa set (written 3500, 19000; as FL35, FL190).","s":"Met 2","ch":"Atmospheric Pressure","sec":"Altimetry definitions (p.17)","h":"chapters/met-02.html#n-altimetry-definitions-p-17"},{"t":"Pressure altitude","d":"altitude in the standard atmosphere corresponding to the pressure at that point. Constant flight level = constant outside pressure.","s":"Nav 18","ch":"Altimeter","sec":"From the questions","h":"chapters/nav-18.html#n-from-the-questions"},{"t":"Pressure altitude","d":"a pressure expressed as the altitude it corresponds to in the Standard Atmosphere.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Vertical references (p.8–36)","h":"chapters/reg-01.html#n-vertical-references-p-8-36"},{"t":"Pressure gradient","d":"horizontal rate of change of pressure perpendicular to isobars, from high to low. Close isobars = steep gradient (strong wind); far apart = weak/flat.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure gradient, tendency, isallobars (p.16–17)","h":"chapters/met-02.html#n-pressure-gradient-tendency-isallobars-p-16-17"},{"t":"Pressure gradient force (PGF)","d":"from high to low, = pressure difference ÷ distance between isobars.","s":"Met 6","ch":"Winds","sec":"Coriolis (geostrophic) force (p.48)","h":"chapters/met-06.html#n-coriolis-geostrophic-force-p-48"},{"t":"Pressure systems","d":"lows/cyclones (ascent), anticyclones (descent).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Vertical motion (p.75–76)","h":"chapters/met-08.html#n-vertical-motion-p-75-76"},{"t":"Pressure tendency","d":"change of pressure with time: 24 h in India, 3 h in higher latitudes.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure gradient, tendency, isallobars (p.16–17)","h":"chapters/met-02.html#n-pressure-gradient-tendency-isallobars-p-16-17"},{"t":"Primary bow","d":"radius 42°; red outside, violet inside.","s":"Met 10","ch":"Optical Phenomena","sec":"Rainbow (p.95–96)","h":"chapters/met-10.html#n-rainbow-p-95-96"},{"t":"Priority order","d":"(a) aircraft in an emergency compelling it to land (engine failure, acute fuel shortage, total communication failure); (b) military fighters (fuel-limited; avoid altering their profile, depart without delay); (c) aircraft on a live scramble; (d) medical flights (sick/injured, medevac); (e) VVIP flights; (f) SAR missions; (g) large military exercise formations; (h) urgent coordinated military/RPA operations; (i) ai…","s":"Reg 8","ch":"Procedures for Aerodrome Control Service","sec":"Other traffic and priorities (p.211–213)","h":"chapters/reg-08.html#n-other-traffic-and-priorities-p-211-213"},{"t":"PROB30 / PROB40","d":"30% or 40% probability. Change period 1809/1812 = 18th between 0900 and 1200 UTC.","s":"Met 26","ch":"TAF, ARFOR and ROFOR","sec":"TAF — Aerodrome Forecast (p.242–244)","h":"chapters/met-26.html#n-taf-aerodrome-forecast-p-242-244"},{"t":"Prohibited area","d":"flight prohibited. Restricted area: flight restricted by conditions. Danger area: dangerous activities may exist at specified times. Prohibited and restricted areas lie over a State's land or territorial waters; danger areas can be anywhere, including high seas.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Airspace and ATS (p.5–35)","h":"chapters/reg-01.html#n-airspace-and-ats-p-5-35"},{"t":"PSR","d":"position report method (blip matches a reported position and track); departing aircraft method (identified within 1 NM of the runway end; beware holding, overflying or missed-approach traffic); turn method (one or more heading changes of 30° or more, only one blip responding, without leaving coverage).","s":"Reg 9","ch":"Use of ATS Surveillance Systems","sec":"Identification (p.224–226)","h":"chapters/reg-09.html#n-identification-p-224-226"},{"t":"Psychoactive substances","d":"alcohol, opioids, cannabinoids, sedatives, hypnotics, cocaine, other stimulants, hallucinogens, volatile solvents; coffee and tobacco excluded.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Operations and people (p.4–34)","h":"chapters/reg-01.html#n-operations-and-people-p-4-34"},{"t":"QFE","d":"pressure at the aerodrome datum → altimeter reads height above the aerodrome/threshold.","s":"Nav 10","ch":"DR Elements: Pressure and Altimetry","sec":"Altimeter settings and altitudes","h":"chapters/nav-10.html#n-altimeter-settings-and-altitudes"},{"t":"QFF","d":"QFE reduced to MSL using the actual temperature (met charts).","s":"Nav 10","ch":"DR Elements: Pressure and Altimetry","sec":"Altimeter settings and altitudes","h":"chapters/nav-10.html#n-altimeter-settings-and-altitudes"},{"t":"QNH","d":"QFE reduced to MSL using ISA → reads altitude (AMSL); shows elevation on the ground.","s":"Nav 10","ch":"DR Elements: Pressure and Altimetry","sec":"Altimeter settings and altitudes","h":"chapters/nav-10.html#n-altimeter-settings-and-altitudes"},{"t":"Quantitative radar (10 cm)","d":"rate, total and intensity of precipitation, snowfall.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Wavelength bands (Table 22.1)","h":"chapters/met-22.html#n-wavelength-bands-table-22-1"},{"t":"Radiation","d":"needs no medium and does not heat the medium; solar radiation heats the earth directly. Radiation plays the most significant role in atmospheric heat transfer.","s":"Met 3","ch":"Temperature","sec":"Heat transfer (p.29–30)","h":"chapters/met-03.html#n-heat-transfer-p-29-30"},{"t":"Rain intensity (per day)","d":"trace 0.01–0.04 mm · light 2.5–7.5 mm · heavy 64.5–124.4 mm · very heavy 124.5–244.4 mm · rainy day ≥ 2.5 mm · mainly dry = very light rain · dry day = no rain.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"D. Miscellaneous terms","h":"chapters/met-30.html#n-d-miscellaneous-terms"},{"t":"Rain shadow","d":"lee side of a range, e.g. areas east of the Western Ghats.","s":"Met 11","ch":"Precipitation","sec":"Diurnal and seasonal variation (p.104)","h":"chapters/met-11.html#n-diurnal-and-seasonal-variation-p-104"},{"t":"Rainy day","d":"≥ 2.5 mm in a day.","s":"Met 11","ch":"Precipitation","sec":"Snow, sleet and terms (p.104)","h":"chapters/met-11.html#n-snow-sleet-and-terms-p-104"},{"t":"Range","d":"limited by attenuation by rain and earth curvature. Detect up to 500 km; resolution better up to 250 km. Normally echoes within 25 NM displayed; long-range echoes up to 75 NM also used.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Weather radar (p.206)","h":"chapters/met-22.html#n-weather-radar-p-206"},{"t":"Rate of descent","d":"height to lose ÷ time (e.g. FL290 → FL80 over 50 NM at 243 kt: 21 000 ft in 12.3 min ≈ 1700 ft/min).","s":"Nav 9","ch":"Dead Reckoning","sec":"Time and DR position","h":"chapters/nav-09.html#n-time-and-dr-position"},{"t":"Ravine winds","d":"pressure difference across hills drives strong flow through narrow valleys, continuing beyond the mouth.","s":"Met 6","ch":"Winds","sec":"Local winds (p.55–58)","h":"chapters/met-06.html#n-local-winds-p-55-58"},{"t":"RCC","d":"organises SAR in a search and rescue region (SRR); RSC: rescue sub-centre under it. Alerting post: intermediary between someone reporting an emergency and the RCC.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Emergency and SAR words (p.8–31)","h":"chapters/reg-01.html#n-emergency-and-sar-words-p-8-31"},{"t":"RCP n","d":"seconds for an instruction to go up and the acknowledgement to come back (RCP 10, 60, 120, 240, 400). RSP n = seconds for surveillance data to reach ATS (RSP 180, 240, 400).","s":"Reg 6","ch":"Separation Methods and Minima","sec":"Performance-based separation (p.181–182)","h":"chapters/reg-06.html#n-performance-based-separation-p-181-182"},{"t":"Reciprocal","d":"more than 135° but less than 225°.","s":"Reg 6","ch":"Separation Methods and Minima","sec":"Track definitions (p.172)","h":"chapters/reg-06.html#n-track-definitions-p-172"},{"t":"Reciprocal tracks","d":"may climb/descend through each other's levels once positively passed and at least 10 NM apart.","s":"Reg 6","ch":"Separation Methods and Minima","sec":"Longitudinal separation by DME/GNSS distance (p.176–179)","h":"chapters/reg-06.html#n-longitudinal-separation-by-dme-gnss-distance-p-176-179"},{"t":"Recovery factor","d":"fraction of the full ram rise a probe senses (0.75 sensing 5 °C → full rise 6.7 °C).","s":"Nav 11","ch":"DR Elements: Temperature and Airspeed","sec":"SAT and TAT","h":"chapters/nav-11.html#n-sat-and-tat"},{"t":"Rectangular","d":"low CL at the tip, high at the root → strong root-stall tendency, ailerons stay effective; but poor aerodynamic and structural efficiency.","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Wing planforms (2-28)","h":"chapters/hb-04.html#n-wing-planforms-2-28"},{"t":"Red square with one yellow diagonal","d":"special precautions in approach/landing (bad manoeuvring area).","s":"Reg 4","ch":"Rules of the Air","sec":"Visual ground signals (p.97–98)","h":"chapters/reg-04.html#n-visual-ground-signals-p-97-98"},{"t":"Red square with two yellow diagonals","d":"landing prohibited, likely to be prolonged.","s":"Reg 4","ch":"Rules of the Air","sec":"Visual ground signals (p.97–98)","h":"chapters/reg-04.html#n-visual-ground-signals-p-97-98"},{"t":"Red/Magenta","d":"heavy precipitation, TS, hail, strong winds, tornadoes, severe turbulence — always avoid.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Airborne weather radar (p.209)","h":"chapters/met-22.html#n-airborne-weather-radar-p-209"},{"t":"Registration mark","d":"letters, numbers or both, 1 to 5 characters, assigned by the State of Registry or common mark registering authority.","s":"Reg 3","ch":"Aircraft Nationality and Registration Marks","sec":"Annex 7 basics (p.69)","h":"chapters/reg-03.html#n-annex-7-basics-p-69"},{"t":"Relative humidity (RH)","d":"actual WV ÷ maximum possible at the same temperature and pressure × 100 = HMR/HMRsat × 100 = e/SVP × 100.","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Relief","d":"contours (lines of equal elevation; approximate = form lines), spot heights, layer tinting, hachuring, hill shading.","s":"Nav 3","ch":"Projections","sec":"Scale","h":"chapters/nav-03.html#n-scale"},{"t":"Repetitive flight plan (RPL)","d":"for a series of frequently recurring, regularly operated IFR flights with identical basic features, submitted by an operator for retention and repetitive use by ATS.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"RESA","d":"area at the end of the strip to reduce damage from undershoot/overrun. Runway strip: runway + stopway area protecting aircraft running off or flying over.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aerodrome areas (p.4–36)","h":"chapters/reg-01.html#n-aerodrome-areas-p-4-36"},{"t":"Reservoir","d":"pressurised to prevent cavitation (and foaming); allows for leaks and thermal expansion. A stack pipe keeps a reserve: normal services draw from the stack pipe, the emergency service from the bottom of the reservoir.","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Hydraulic components (3-7)","h":"chapters/hb-10.html#n-hydraulic-components-3-7"},{"t":"Reversal above 8 km","d":"because the equatorial troposphere is deeper, above ~8 km the poles are warmer than the equator (reversal of temperature and density).","s":"Met 1","ch":"Atmosphere","sec":"Tropopause details (p.5–6)","h":"chapters/met-01.html#n-tropopause-details-p-5-6"},{"t":"Reynolds number","d":"higher RN → earlier transition → more energetic turbulent layer → delayed separation → more lift, higher stalling AoA.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Lift curves and factors affecting CL (2-13 to 2-14)","h":"chapters/hb-02.html#n-lift-curves-and-factors-affecting-cl-2-13-to-2-14"},{"t":"Reynolds number RN = ρ V l / μ","d":"ratio of inertial to viscous forces (dimensionless). A model and a full-size aircraft at the same RN behave the same aerodynamically.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Viscosity and Reynolds number (2-8)","h":"chapters/hb-01.html#n-viscosity-and-reynolds-number-2-8"},{"t":"Rhumb line (loxodrome)","d":"cuts all meridians at the same angle → constant track; not the shortest distance; spirals towards the nearer pole. Equator is the only line that is both GC and rhumb line (meridians are GCs and also rhumb lines of 000/180 — the book counts the equator).","s":"Nav 2","ch":"The Earth","sec":"Great circle, small circle, rhumb line","h":"chapters/nav-02.html#n-great-circle-small-circle-rhumb-line"},{"t":"Ridge","d":"wedge from a high; rounded (not V) isobars; fair weather; winds veer.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure patterns (p.21–22) (isobars at 2 hPa)","h":"chapters/met-02.html#n-pressure-patterns-p-21-22-isobars-at-2-hpa"},{"t":"RMI","d":"compass card slaved to the gyro-magnetic compass; the needle head reads the QDM directly.","s":"Nav 13","ch":"In-flight Navigation","sec":"Fixes and position lines","h":"chapters/nav-13.html#n-fixes-and-position-lines"},{"t":"RN up","d":"more of the BL turbulent, separation moves aft (less form drag) but more friction; for the whole aircraft total drag falls as RN rises.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Factors affecting CD (2-17)","h":"chapters/hb-02.html#n-factors-affecting-cd-2-17"},{"t":"RNAV specification","d":"no on-board performance monitoring and alerting (e.g. RNAV 5, RNAV 1). RNP specification: with monitoring and alerting (e.g. RNP 4, RNP APCH).","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Navigation words (p.12–38)","h":"chapters/reg-01.html#n-navigation-words-p-12-38"},{"t":"Roaring Forties / Furious Fifties / Crying Sixties","d":"westerlies 35°–60° (stormy beyond 40°S).","s":"Met 6","ch":"Winds","sec":"Named winds (p.61–62)","h":"chapters/met-06.html#n-named-winds-p-61-62"},{"t":"ROBEX","d":"METAR/SPECI of international aerodromes and alternates exchanged outside India; AIREPs too.","s":"Met 21","ch":"Met Services for Aviation","sec":"Exchange of met messages (p.201)","h":"chapters/met-21.html#n-exchange-of-met-messages-p-201"},{"t":"ROC = V sin θ = (T − D) V ÷ W = excess power ÷ weight","d":"rate of climb depends on excess power. Best rate at Vy.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Steady climb (2-43)","h":"chapters/hb-07.html#n-steady-climb-2-43"},{"t":"ROFOR","d":"route forecast (coded): upper winds/temps, sig weather, cloud, freezing level, turbulence, icing, jet, tropopause, max wind.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"Roll cloud","d":"cylindrical, appears to roll; behind the first gust, detached from the CB; seldom severe.","s":"Met 13","ch":"Thunderstorms","sec":"Life cycle (p.114–116)","h":"chapters/met-13.html#n-life-cycle-p-114-116"},{"t":"Roll due to yaw","d":"right rudder → yaw right → left (outer) wing faster → more lift → roll right, the same way as the yaw. Greatest at low speed, high AoA.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Secondary effects (2-39)","h":"chapters/hb-06.html#n-secondary-effects-2-39"},{"t":"Roll spoilers","d":"raised on the down-going wing (adds drag on the same side as the turn).","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Secondary effects (2-39)","h":"chapters/hb-06.html#n-secondary-effects-2-39"},{"t":"Rome 1952","d":"damage by foreign aircraft to third parties on the ground; operator liable, limit proportionate to aircraft weight, compulsory insurance. India has not ratified. Montreal Protocol 1978 amended it.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Liability conventions (p.54–56)","h":"chapters/reg-02.html#n-liability-conventions-p-54-56"},{"t":"Rossby (planetary) waves","d":"giant meanders (troughs and ridges) of upper westerlies in a rotating atmosphere/ocean (discovered by Carl Rossby, 1930s); the meandering jet streams are Rossby waves; strongly influence weather.","s":"Met 20","ch":"General Circulation","sec":"Standing and Rossby waves (p.191–192)","h":"chapters/met-20.html#n-standing-and-rossby-waves-p-191-192"},{"t":"Rotation","d":"seen from above the North Pole anticlockwise (west → east); from above the South Pole clockwise. The earth spins about its polar diameter (axis).","s":"Nav 2","ch":"The Earth","sec":"Shape and size","h":"chapters/nav-02.html#n-shape-and-size"},{"t":"Rotor streaming","d":"strong low-level wind that weakens/reverses aloft → violent rotors on the lee slope.","s":"Met 16","ch":"CAT and Mountain Waves","sec":"Vertical currents and clouds (p.150–151)","h":"chapters/met-16.html#n-vertical-currents-and-clouds-p-150-151"},{"t":"RPA","d":"unmanned aircraft piloted from a remote pilot station; RPAS = RPA + station(s) + command-and-control links.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aircraft and their kinds (p.3–38)","h":"chapters/reg-01.html#n-aircraft-and-their-kinds-p-3-38"},{"t":"RRR","d":"1 = trace, 2 = 0.1–0.9 (book table), … the book's question uses 2 → 1.6–2.4 mm.","s":"Met 24","ch":"Station Models","sec":"Codes","h":"chapters/met-24.html#n-codes"},{"t":"Runway turn pad","d":"area for a 180° turn. Rapid exit taxiway: joins the runway at an acute angle to let landing aircraft turn off at higher speed.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aerodrome areas (p.4–36)","h":"chapters/reg-01.html#n-aerodrome-areas-p-4-36"},{"t":"Runway Visual Range","d":"range over which a pilot on the runway centre line can see the runway markings or the lights delineating the runway / its centre line.","s":"Met 7","ch":"Visibility and Fog","sec":"RVR (p.67–68)","h":"chapters/met-07.html#n-rvr-p-67-68"},{"t":"RVR","d":"range over which a pilot on the runway centre line can see runway markings or lights.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Flight plans and times (p.13–35)","h":"chapters/reg-01.html#n-flight-plans-and-times-p-13-35"},{"t":"S-band (10 cm)","d":"cyclone detection radar; X-band (3 cm) = airborne and storm detection.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Exam traps","h":"chapters/met-22.html#n-exam-traps"},{"t":"Safe-life","d":"designed to last a fixed number of hours/cycles, then replaced; a crack means retirement. Inefficient (deterioration is hard to predict).","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Load limits and design philosophies (3-3)","h":"chapters/hb-10.html#n-load-limits-and-design-philosophies-3-3"},{"t":"Saffir–Simpson","d":"Cat 1 minimal > 980 hPa, 64–83 kt, surge 4–5 ft · Cat 2 moderate 965–979, 84–96 kt, 6–8 ft · Cat 3 extensive 945–964, 97–113 kt, 9–12 ft · Cat 4 extreme 920–944, 114–135 kt, 13–18 ft · Cat 5 catastrophic < 920 hPa, > 135 kt, > 18 ft.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"B. Meteorological scales","h":"chapters/met-30.html#n-b-meteorological-scales"},{"t":"Same cruising level, same track","d":"15 min; 10 min if nav-aids allow frequent position/speed checks; 5 min if the preceding aircraft is ≥ 20 kt (37 km/h) TAS faster and both departed the same aerodrome, or both reported over the same exact significant point, or a departing aircraft can be spaced 5 min where it joins the route behind an en-route one; 3 min in those cases if the leader is ≥ 40 kt (74 km/h) faster.","s":"Reg 6","ch":"Separation Methods and Minima","sec":"Longitudinal separation by time (p.172–176)","h":"chapters/reg-06.html#n-longitudinal-separation-by-time-p-172-176"},{"t":"Same level, crossing tracks","d":"15 min; 10 min with frequent position fixing.","s":"Reg 6","ch":"Separation Methods and Minima","sec":"Longitudinal separation by time (p.172–176)","h":"chapters/reg-06.html#n-longitudinal-separation-by-time-p-172-176"},{"t":"Same level, same track","d":"20 NM (same on-track DME / collocated waypoint / same waypoint, checked with simultaneous readings); 10 NM if the leader is ≥ 20 kt faster.","s":"Reg 6","ch":"Separation Methods and Minima","sec":"Longitudinal separation by DME/GNSS distance (p.176–179)","h":"chapters/reg-06.html#n-longitudinal-separation-by-dme-gnss-distance-p-176-179"},{"t":"Same track","d":"angular difference less than 45° or more than 315° (protection areas overlap).","s":"Reg 6","ch":"Separation Methods and Minima","sec":"Track definitions (p.172)","h":"chapters/reg-06.html#n-track-definitions-p-172"},{"t":"SAR (specific air range)","d":"air distance per unit of fuel = TAS ÷ fuel flow. Best SAR at the altitude where ~90% RPM gives 1.32 VMD without accelerating. SAR = (1 ÷ SFC) × (TAS ÷ D) — larger with more TAS/drag, less with more weight and more SFC.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Cruise, range and endurance (2-48)","h":"chapters/hb-07.html#n-cruise-range-and-endurance-2-48"},{"t":"SAR (still air range)","d":"fuel available × TAS ÷ FC.","s":"Nav 12","ch":"PNR, PET and Range","sec":"Point of no return (PNR / PSR / radius of action)","h":"chapters/nav-12.html#n-point-of-no-return-pnr-psr-radius-of-action"},{"t":"SAT / OAT / true air temperature / ambient","d":"the temperature of the undisturbed air.","s":"Nav 11","ch":"DR Elements: Temperature and Airspeed","sec":"SAT and TAT","h":"chapters/nav-11.html#n-sat-and-tat"},{"t":"Saturated air","d":"holds the maximum WV (like a full sponge).","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Saturation HMR","d":"maximum HMR at that temperature and pressure; rises with temperature.","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Saturation vapour pressure (SVP)","d":"vapour pressure when saturated.","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Scale (instrument) error","d":"tied to a particular set of altitude aneroids, varies with altitude; plotted for each CADC and reduced with a corrective camshaft on the altitude output.","s":"Nav 17","ch":"Air Data Systems","sec":"CADC errors (common to all instruments)","h":"chapters/nav-17.html#n-cadc-errors-common-to-all-instruments"},{"t":"Scale effect","d":"change of aerodynamic characteristics with RN. A 1/10 model has 1/10 the length, 1/100 the area and 1/1000 the mass; to match RN the \"VL law\" would need 10× the speed (a 400 km/h aircraft → 4000 km/h in the tunnel). Raising the tunnel air density 25× keeps RN the same at only 160 km/h.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Viscosity and Reynolds number (2-8)","h":"chapters/hb-01.html#n-viscosity-and-reynolds-number-2-8"},{"t":"Scheduled flights","d":"printed/electronic plans accepted; the operator obtains ATS, COMM and MET briefing and keeps the documents as records for 6 months. ATC may still require the PIC/crew to report in person for special briefing.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"India: filing flight plans","h":"chapters/nav-16.html#n-india-filing-flight-plans"},{"t":"Scopes","d":"PPI (Plan Position Indicator) = plan view, gives bearing and range; RHI (Range Height Indicator) = direct reading of heights of CB cells.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Weather radar (p.206)","h":"chapters/met-22.html#n-weather-radar-p-206"},{"t":"Screen height","d":"imaginary screen at the end of TODR and start of LDR (35 ft). PMC = power management computer; QRH = quick reference handbook.","s":"Nav 15","ch":"Performance","sec":"Terms","h":"chapters/nav-15.html#n-terms"},{"t":"Sea breeze (day)","d":"land heats → air rises → pressure aloft over land rises → upper air drifts seaward → surface pressure rises over sea, falls over land → sea-to-land wind.","s":"Met 6","ch":"Winds","sec":"Sea and land breeze (p.57–58)","h":"chapters/met-06.html#n-sea-and-land-breeze-p-57-58"},{"t":"Seaplane","d":"takes off and alights solely on water. Amphibian: on land or water.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aircraft and their kinds (p.3–38)","h":"chapters/reg-01.html#n-aircraft-and-their-kinds-p-3-38"},{"t":"Secondary bow","d":"radius about 52° (red inside at 50°, violet outside at 54°); fainter, about twice as broad.","s":"Met 10","ch":"Optical Phenomena","sec":"Rainbow (p.95–96)","h":"chapters/met-10.html#n-rainbow-p-95-96"},{"t":"Section 1","d":"area AAAAA, visibility VVVV, weather W1W1W1, cloud groups NsCChshshs (e.g. 2AC100 = 2/8 AC at 10 000 ft; layer rules 1/8, 3/8, 5/8, plus CB), 7hfhfhf freezing level, 6IchihihitL icing, 5BhBhBhBtL turbulence, 4hxhxhxTT dddff wind & temperature, 2h'ph'pTpTp tropopause.","s":"Met 26","ch":"TAF, ARFOR and ROFOR","sec":"ARFOR — Area Forecast (p.247–249)","h":"chapters/met-26.html#n-arfor-area-forecast-p-247-249"},{"t":"Segment 1","d":"from 35 ft at V2 to gear fully retracted. Segment 2: gear up to at least 400 ft at V2 — the performance-limiting segment. Segment 3 (transition): level acceleration for flap/slat retraction. Final segment: to at least 1500 ft, clean, maximum continuous power, final climb speed.","s":"Nav 15","ch":"Performance","sec":"Take-off flight path and segments","h":"chapters/nav-15.html#n-take-off-flight-path-and-segments"},{"t":"Sensible horizon","d":"horizon through the observer without refraction (what a spirit level senses); lies above the visible horizon. Visible horizon: lowered by refraction.","s":"Nav 1","ch":"The Solar System","sec":"Horizon and twilight","h":"chapters/nav-01.html#n-horizon-and-twilight"},{"t":"Sensors","d":"measure the surrounding atmosphere: all systems use a pitot tube, static ports and a temperature probe; complex ones add an angle-of-attack sensor.","s":"Nav 17","ch":"Air Data Systems","sec":"Air data system","h":"chapters/nav-17.html#n-air-data-system"},{"t":"Series 1","d":"interceptor rocks wings and flashes nav lights from slightly above, ahead and normally to the left (right for a helicopter), then a slow level turn = \"You have been intercepted, follow me\". Reply: rock wings, flash lights, follow.","s":"Reg 4","ch":"Rules of the Air","sec":"Interception (p.92–96)","h":"chapters/reg-04.html#n-interception-p-92-96"},{"t":"Series 2","d":"abrupt break-away, climbing turn of 90° or more without crossing the intercepted aircraft's path = \"You may proceed\". Reply: rock wings.","s":"Reg 4","ch":"Rules of the Air","sec":"Interception (p.92–96)","h":"chapters/reg-04.html#n-interception-p-92-96"},{"t":"Series 3","d":"gear down, steady landing lights, overfly the runway = \"Land at this aerodrome\". Reply: same and land if safe.","s":"Reg 4","ch":"Rules of the Air","sec":"Interception (p.92–96)","h":"chapters/reg-04.html#n-interception-p-92-96"},{"t":"Series 5","d":"regular switching on and off of all lights = \"Cannot comply\". Series 6: irregular flashing of all lights = \"In distress\".","s":"Reg 4","ch":"Rules of the Air","sec":"Interception (p.92–96)","h":"chapters/reg-04.html#n-interception-p-92-96"},{"t":"Servo tab","d":"the pilot moves only the tab; its aerodynamic force moves the surface (opposite direction). Sometimes also a trim tab; can act as emergency control if hydraulics fail or the elevator jams (works in the opposite sense). Poor at low IAS (deflections above ~20° ineffective).","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Aerodynamic balance (2-40)","h":"chapters/hb-06.html#n-aerodynamic-balance-2-40"},{"t":"Severe","d":"almost continuous thunder and lightning, heavy rain/showers, maybe hail; wind > 40 kt.","s":"Met 13","ch":"Thunderstorms","sec":"Intensity (p.117)","h":"chapters/met-13.html#n-intensity-p-117"},{"t":"Severe TS","d":"locally damaging winds, frequent lightning, or large hail.","s":"Met 13","ch":"Thunderstorms","sec":"What it is (p.112)","h":"chapters/met-13.html#n-what-it-is-p-112"},{"t":"Severe-storm signatures","d":"intense, sharp echoes (strong updraughts; anvil = fuzzy top); hooks, appendages, protuberances → hail; \"figure 6\" echo → tornado; rapidly moving echoes → strong winds; slanting rain columns → vertical wind shear; dry holes (echo-free areas inside extensive bright echo) → strong winds and heavy rain; rapidly developing, large horizontal, converging echoes → severe storm; bright band (a few hundred m thick, just bel…","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Cloud echoes (p.208–209)","h":"chapters/met-22.html#n-cloud-echoes-p-208-209"},{"t":"Shear line","d":"in the same air mass wind speed falls sharply S → N (or vice versa); friction → small-scale ascent; if deep → thick ST, AS, NS up to ~500 km across; with a fresh surge, CU/CB embedded at its leading edge.","s":"Met 18","ch":"Tropical Systems","sec":"Surge and shear line (p.157–158)","h":"chapters/met-18.html#n-surge-and-shear-line-p-157-158"},{"t":"Shear line","d":"line/zone of abrupt change in horizontal wind component (maximum horizontal shear). Wind discontinuity: line of abrupt change in wind direction.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"A. Synoptic systems","h":"chapters/met-30.html#n-a-synoptic-systems"},{"t":"Shelf cloud","d":"wedge-shaped with flat base, at the gust front, attached to the CB; associated with severe weather.","s":"Met 13","ch":"Thunderstorms","sec":"Life cycle (p.114–116)","h":"chapters/met-13.html#n-life-cycle-p-114-116"},{"t":"Shimmy","d":"rapid side-to-side oscillation of the nose wheel from sidewall flexibility; also a sign of a broken torque link. Reduced by twin nose wheels or Marstrand (twin-contact) tyres; shimmy dampers.","s":"Handbook 11","ch":"Landing Gear, Brakes, Tyres and Powered Controls","sec":"Nose-wheel control and shimmy (3-13)","h":"chapters/hb-11.html#n-nose-wheel-control-and-shimmy-3-13"},{"t":"Shock stall","d":"sudden drop in CL at about M 0.82 from boundary-layer separation behind the upper-surface shockwave; can occur at low AoA/high speed or high AoA/lower Mach; severe buffet that can damage the tail.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Types of stall (2-22)","h":"chapters/hb-03.html#n-types-of-stall-2-22"},{"t":"Short-period oscillation","d":"rapid, with large changes of AoA and load factor while speed and height stay almost constant; restored by static stability; hard for the pilot to control — control inputs may reinforce it (PIO); cured by pitch dampers.","s":"Handbook 5","ch":"Stability","sec":"Dynamic stability (2-34)","h":"chapters/hb-05.html#n-dynamic-stability-2-34"},{"t":"Sidereal day","d":"between two transits of a fixed star / the First Point of Aries = 23 h 56 min.","s":"Nav 1","ch":"The Solar System","sec":"Year and day","h":"chapters/nav-01.html#n-year-and-day"},{"t":"Sideslip angle β","d":"between the centreline and the relative airflow; positive with the airflow from the right. Airflow from the left pushes the fin (behind the CG) so the nose yaws into the airflow. Yawing with rudder sets up an opposing sideslip → damping in yaw.","s":"Handbook 5","ch":"Stability","sec":"Directional stability (2-35)","h":"chapters/hb-05.html#n-directional-stability-2-35"},{"t":"Significant point","d":"nav-aid, intersection or waypoint.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Navigation words (p.12–38)","h":"chapters/reg-01.html#n-navigation-words-p-12-38"},{"t":"sin θ = (T − D) ÷ W","d":"angle of climb depends on excess thrust. Best angle at Vx.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Steady climb (2-43)","h":"chapters/hb-07.html#n-steady-climb-2-43"},{"t":"Single cell","d":"one updraught; rarely severe; summer heating (or winter cold fronts).","s":"Met 13","ch":"Thunderstorms","sec":"Classification by structure (p.113)","h":"chapters/met-13.html#n-classification-by-structure-p-113"},{"t":"Skin-friction drag","d":"viscosity in the boundary layer; more surface area → more friction drag.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Parasite drag (2-15)","h":"chapters/hb-02.html#n-parasite-drag-2-15"},{"t":"Slats","d":"raise CLmax by up to 70% and increase the stalling AoA. Fitted along the LE (often full span); unlike flaps they do not increase camber; the slot acts as a venturi and energises the BL, flattening the suction peak at high AoA. Extended manually or automatically at a set AoA; useful only at high AoA (high drag otherwise). On landing they give a nose-high attitude (poorer view).","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Lift augmentation (2-31)","h":"chapters/hb-04.html#n-lift-augmentation-2-31"},{"t":"Slowing down","d":"reduce power and raise AoA to hold lift; as AoA rises the CP moves forward, reducing the nose-down moment, so a little forward stick is needed again to settle.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Level flight (2-42)","h":"chapters/hb-07.html#n-level-flight-2-42"},{"t":"Small aeroplane","d":"MCTOM 5,700 kg or less. Large aeroplane: over 5,700 kg.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aircraft and their kinds (p.3–38)","h":"chapters/reg-01.html#n-aircraft-and-their-kinds-p-3-38"},{"t":"Small circle","d":"any circle on the surface that is not a GC.","s":"Nav 2","ch":"The Earth","sec":"Great circle, small circle, rhumb line","h":"chapters/nav-02.html#n-great-circle-small-circle-rhumb-line"},{"t":"Small, stable CP movement","d":"the largest wing loads lie along the line of CP travel, so small travel saves structural weight.","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Requirements of an ideal aerofoil (2-27)","h":"chapters/hb-04.html#n-requirements-of-an-ideal-aerofoil-2-27"},{"t":"SNOWTAM","d":"special-series NOTAM on snow, ice, slush, frost, standing water on the movement area. RWYCC (runway condition code) assessed by the aerodrome operator for each third of the runway, for performance calculations. ASHTAM: volcanic activity/ash in its set format.","s":"Reg 10","ch":"Aeronautical Information Services","sec":"NOTAM (p.235–237)","h":"chapters/reg-10.html#n-notam-p-235-237"},{"t":"Somali jet","d":"low-level (1–1.5 km) cross-equatorial flow reaching jet speed along the E coast of Africa; from near Mauritius/N Madagascar; reaches India's W coast in June, strongest in July; stronger jet → stronger monsoon.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"G. Other systems influencing the SW monsoon","h":"chapters/met-30.html#n-g-other-systems-influencing-the-sw-monsoon"},{"t":"Source regions","d":"where air stagnates over a uniform surface — high-pressure areas with slack gradients and light winds: the poles and the subtropical highs.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Air masses (p.129–130)","h":"chapters/met-14.html#n-air-masses-p-129-130"},{"t":"Spar","d":"main spanwise member — bending and torsion loads. Stringers: spanwise stiffeners of the skin (stop buckling). Ribs: chordwise members holding the shape and supporting the skin. Torsion box: front spar + rear spar + skins + ribs + stringers — resists bending and twisting (often the fuel tank).","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Airframe construction (3-5)","h":"chapters/hb-10.html#n-airframe-construction-3-5"},{"t":"SPECI","d":"special report — immediately for deterioration; for improvement after 10 min once conditions stabilise; TREND appended.","s":"Met 21","ch":"Met Services for Aviation","sec":"Observations and reports","h":"chapters/met-21.html#n-observations-and-reports"},{"t":"Special features","d":"e.g. \"A WD lies over W Rajasthan with upper-air cyclonic circulation up to 20 000 ft\".","s":"Met 29","ch":"Flight Forecast: Tabular and Cross-Section","sec":"Met T-3 — tabular flight forecast (sample, Table 29.1)","h":"chapters/met-29.html#n-met-t-3-tabular-flight-forecast-sample-table-29-1"},{"t":"Specific heat","d":"heat needed to raise unit mass by 1°C. Water 1 (highest), ice 0.5, soil 0.2 → land heats and cools much faster than water. Temperature rise is inversely proportional to specific heat.","s":"Met 3","ch":"Temperature","sec":"Definitions (p.28)","h":"chapters/met-03.html#n-definitions-p-28"},{"t":"Speed","d":"Di ∝ 1/EAS² — 2× EAS → ¼ Di; CDi ∝ 1/EAS⁴ — 2× EAS → 1/16 CDi (q 4×, so CL to ¼, CL² to 1/16).","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Factors affecting induced drag (2-17)","h":"chapters/hb-02.html#n-factors-affecting-induced-drag-2-17"},{"t":"Speed control (India)","d":"below 10,000 ft, IAS not more than 250 kt; arrivals below 10,000 ft within 15 NM of the aerodrome VOR/DME not more than 220 kt. ATC may add restrictions or cancel them with \"No speed restriction\".","s":"Reg 9","ch":"Use of ATS Surveillance Systems","sec":"Separation and speed control (p.226–227)","h":"chapters/reg-09.html#n-separation-and-speed-control-p-226-227"},{"t":"Speed of sound depends only on temperature","d":"LSS = 39 √T(K) kt. Higher altitude → colder → lower LSS. Climbing at constant TAS → Mach rises; at constant IAS → Mach rises faster (TAS also rises).","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Mach number and speed regimes (2-49)","h":"chapters/hb-08.html#n-mach-number-and-speed-regimes-2-49"},{"t":"Spiral divergence","d":"directional stability > lateral stability. In a sideslip the strong fin yaws the nose into it, weak lateral stability lags; the faster outer wing adds bank — a slowly tightening spiral dive; usually controllable by the pilot.","s":"Handbook 5","ch":"Stability","sec":"Coupled directional and lateral stability (2-37)","h":"chapters/hb-05.html#n-coupled-directional-and-lateral-stability-2-37"},{"t":"Spiral slipstream","d":"the corkscrewing slipstream strikes the fin from the left → yaw left (and a roll right). Reduced by contra-rotation, a fixed rudder tab, a thrust line angled slightly right, or an offset fin.","s":"Handbook 9","ch":"Propellers","sec":"Propeller effects on the aircraft (2-60) — clockwise propeller seen from behind","h":"chapters/hb-09.html#n-propeller-effects-on-the-aircraft-2-60-clockwise-propeller-seen-from-behind"},{"t":"Spoilers","d":"flat plates on the upper wing surface that increase drag and reduce lift. Used differentially for roll (and to avoid adverse yaw); together on both wings as airbrakes (and lift dumpers).","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Primary controls (2-38)","h":"chapters/hb-06.html#n-primary-controls-2-38"},{"t":"Spot wind/temperature chart","d":"forecast wind and temperature at grid points for several altitudes (e.g. 30 280100 −32 = 30 000 ft, 280°/100 kt, −32 °C) plus the freezing level.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"F. Met charts","h":"chapters/met-30.html#n-f-met-charts"},{"t":"Spring tab","d":"a servo tab with a spring — at low speed the spring is not compressed and the pilot moves the surface directly; at high speed dynamic pressure holds the surface, the spring compresses and the tab helps. Tab movement ∝ stick force.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Aerodynamic balance (2-40)","h":"chapters/hb-06.html#n-aerodynamic-balance-2-40"},{"t":"Squall","d":"sudden increase of ≥ 16 kt (32 km/h, 8 m/s), reaching ≥ 22 kt (44 km/h, 11 m/s), lasting ≥ 1 minute. With CB / violent convection; spreads several km and thousands of feet; direction and speed differ widely from the prevailing wind; often a sharp temperature drop and precipitation.","s":"Met 6","ch":"Winds","sec":"Gust, lull, squall, gale (p.46–47)","h":"chapters/met-06.html#n-gust-lull-squall-gale-p-46-47"},{"t":"Squall","d":"usually up to 40 kt, can be 100 kt; strongest ahead of the storm.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"SSR/MLAT","d":"aircraft identification in the label; a verified discrete code; Mode S aircraft identification; transfer; compliance with an instruction to set a code; compliance with \"SQUAWK IDENT\".","s":"Reg 9","ch":"Use of ATS Surveillance Systems","sec":"Identification (p.224–226)","h":"chapters/reg-09.html#n-identification-p-224-226"},{"t":"St Elmo's fire","d":"bluish/greenish glow with crackling on an aircraft in CU/CB from a strong electric field; weak to moderate.","s":"Met 10","ch":"Optical Phenomena","sec":"Atmospheric electricity and lightning (p.99–100)","h":"chapters/met-10.html#n-atmospheric-electricity-and-lightning-p-99-100"},{"t":"Stability","d":"the tendency of an aircraft to return to steady flight after a disturbance, without pilot input. Equilibrium (trim): all forces and moments sum to zero. The CG is placed for the best balance of stability and control: more stability = less manoeuvrability.","s":"Handbook 5","ch":"Stability","sec":"Stability and static stability (2-32)","h":"chapters/hb-05.html#n-stability-and-static-stability-2-32"},{"t":"Stable","d":"a displaced parcel returns (ball in a bowl). Unstable: keeps going (ball on an upturned bowl). Neutral: stays where put.","s":"Met 9","ch":"Stability and Instability","sec":"Stability ideas (p.88–89)","h":"chapters/met-09.html#n-stability-ideas-p-88-89"},{"t":"Stages","d":"crack initiation (joints, holes, corners) → moderation (corrosion worsens it) → growth (beyond about 1 mm it depends mainly on stress level) → final fracture at the critical crack length.","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Metal fatigue (3-4)","h":"chapters/hb-10.html#n-metal-fatigue-3-4"},{"t":"Stall recovery","d":"lower the nose (reduce AoA), full thrust, then stabilise altitude and control once out of the stall.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Types of stall (2-22)","h":"chapters/hb-03.html#n-types-of-stall-2-22"},{"t":"Stalling","d":"the BL flows spanwise, pools and thickens at the tips → tip stall; a ram's-horn vortex forms at the tip (LE separation + spanwise flow + tip flow).","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Wing planforms (2-28)","h":"chapters/hb-04.html#n-wing-planforms-2-28"},{"t":"Standard masses","d":"crew 85 kg (75 + 10), adult 75 kg, child (2–12) 35 kg, infant (< 2) 10 kg (training flights may use actual crew masses). Scales calibrated as required.","s":"Nav 14","ch":"Mass and Balance","sec":"Weighing and records (India)","h":"chapters/nav-14.html#n-weighing-and-records-india"},{"t":"Standard time","d":"time set by the legal authorities for a country or part of it, kept on a chosen meridian. IST = UTC + 5 h 30 min (82°30′E); IST and LMT agree only at 82°30′E.","s":"Nav 5","ch":"Time","sec":"Basics","h":"chapters/nav-05.html#n-basics"},{"t":"Standards","d":"uniform application necessary; non-compliance must be notified (Art 38). Recommended Practices: desirable; Council invites (but does not oblige) notification.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"ICAO publications (p.47–49)","h":"chapters/reg-02.html#n-icao-publications-p-47-49"},{"t":"Standing (stationary) wave","d":"two waves of equal amplitude and frequency moving in opposite directions; in the atmosphere = month/season-averaged deviations of the circulation caused by mountains, continents, oceans, SST contrasts; N/S flows carry heat and moisture, alter storm tracks.","s":"Met 20","ch":"General Circulation","sec":"Standing and Rossby waves (p.191–192)","h":"chapters/met-20.html#n-standing-and-rossby-waves-p-191-192"},{"t":"State aircraft","d":"military aircraft and aircraft used exclusively in government service (posts, customs, police).","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aircraft and their kinds (p.3–38)","h":"chapters/reg-01.html#n-aircraft-and-their-kinds-p-3-38"},{"t":"State of Registry","d":"on whose register the aircraft is. State of the Operator: operator's principal place of business. State of Design: type-design organisation. State of Manufacture: final assembly. State of Occurrence: where the accident happens.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Operations and people (p.4–34)","h":"chapters/reg-01.html#n-operations-and-people-p-4-34"},{"t":"Static (barometric) pressure","d":"air at rest; molecules in random motion push equally in all directions.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Static and dynamic pressure (p.12)","h":"chapters/met-02.html#n-static-and-dynamic-pressure-p-12"},{"t":"Static margin","d":"the distance between the aft CG limit and the neutral point.","s":"Handbook 5","ch":"Stability","sec":"Longitudinal static stability (2-32 to 2-33)","h":"chapters/hb-05.html#n-longitudinal-static-stability-2-32-to-2-33"},{"t":"Static port","d":"usually flush on the side of the fuselage, sensing the pressure of the still air; vents on both sides compensate for erratic static changes with attitude. Its opening is always parallel to the relative airflow.","s":"Nav 17","ch":"Air Data Systems","sec":"The pitot-static system","h":"chapters/nav-17.html#n-the-pitot-static-system"},{"t":"Static pressure (S)","d":"the weight of the air acting on every surface; higher at lower altitude.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Density and pressures (2-5)","h":"chapters/hb-01.html#n-density-and-pressures-2-5"},{"t":"Static stability","d":"only the initial tendency after a disturbance (e.g. a gust).","s":"Handbook 5","ch":"Stability","sec":"Stability and static stability (2-32)","h":"chapters/hb-05.html#n-stability-and-static-stability-2-32"},{"t":"Stationary front","d":"barely moves; winds parallel to it in opposite directions on either side (e.g. polar front).","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Occlusions and others (p.134–135)","h":"chapters/met-14.html#n-occlusions-and-others-p-134-135"},{"t":"Statute mile","d":"5280 ft = 0.87 NM (1 NM = 1.15 SM). NM > SM > km.","s":"Nav 7","ch":"Distances on the Earth","sec":"Units","h":"chapters/nav-07.html#n-units"},{"t":"Steady descent","d":"lift < weight (W cos θ); thrust < drag (W sin θ helps). Vertical descent: weight does all the work.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Descent and glide (2-45)","h":"chapters/hb-07.html#n-descent-and-glide-2-45"},{"t":"Steady erect spin","d":"oscillatory at first; after about 2 turns inertial and aerodynamic moments balance and it settles with a steady rate of descent.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Spin (2-24)","h":"chapters/hb-03.html#n-spin-2-24"},{"t":"Steady streamline flow","d":"properties may differ from point to point but stay constant in time at any point; streamlines follow the surface and never cross. Unsteady flow cannot be drawn as streamlines.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Streamline flow and lift theories (2-6 to 2-7)","h":"chapters/hb-01.html#n-streamline-flow-and-lift-theories-2-6-to-2-7"},{"t":"Steady-state TS","d":"fronts, converging winds, troughs aloft force ascent; precipitation falls outside the updraught; lasts several hours.","s":"Met 13","ch":"Thunderstorms","sec":"Types (p.112–113)","h":"chapters/met-13.html#n-types-p-112-113"},{"t":"Steaming fog (sea smoke)","d":"cold air over a warm sea; vapour from the warm water condenses in the cold air. High latitudes, frozen land, Iceland, Norway.","s":"Met 7","ch":"Visibility and Fog","sec":"Other fogs (p.72)","h":"chapters/met-07.html#n-other-fogs-p-72"},{"t":"Stefan–Boltzmann law","d":"total energy radiated ∝ T⁴ (absolute temperature) → hot bodies (sun) emit intense radiation.","s":"Met 3","ch":"Temperature","sec":"Insolation and radiation laws (p.30)","h":"chapters/met-03.html#n-insolation-and-radiation-laws-p-30"},{"t":"Step climb","d":"fly 2000 ft above the optimum altitude, hold it until the optimum is 2000 ft above you, then climb 4000 ft; repeat, staying within 2000 ft of optimum — about 99% of cruise-climb efficiency.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Cruise climb and step climb (2-44)","h":"chapters/hb-07.html#n-cruise-climb-and-step-climb-2-44"},{"t":"Stopway","d":"prepared area beyond TORA for stopping after a rejected take-off; at least as wide as the runway, able to bear the aircraft. Counts only in ASDA.","s":"Nav 15","ch":"Performance","sec":"Declared distances","h":"chapters/nav-15.html#n-declared-distances"},{"t":"Stratiform cloud / steady rain","d":"diffuse, ill-defined, uniform-intensity echoes; on RHI a bright band at the freezing level (strong reflection from melting snowflakes) — seen only with weak, uniform updraughts; vanishes as convection increases.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Cloud echoes (p.208–209)","h":"chapters/met-22.html#n-cloud-echoes-p-208-209"},{"t":"Strayed aircraft","d":"deviated significantly or reports lost. (One unit's strayed aircraft may be another's unidentified aircraft.)","s":"Reg 5","ch":"Air Traffic Services","sec":"ATS route designators (p.148–150)","h":"chapters/reg-05.html#n-ats-route-designators-p-148-150"},{"t":"Stress","d":"force ÷ area. Strain = change in size ÷ original size (no units). Stiffness (rigidity) = stress ÷ strain (Young's modulus).","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Terms and loads (3-3)","h":"chapters/hb-10.html#n-terms-and-loads-3-3"},{"t":"Super stall (low-AR deltas)","d":"stalling AoA up to 40°; by then the drag is so high that the flight path tilts down with the nose high — high rate of descent, loss of stability and control.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Types of stall (2-22)","h":"chapters/hb-03.html#n-types-of-stall-2-22"},{"t":"Supercell","d":"separate up/downdraughts (vertical wind shear) and a rotating updraught (mesocyclone); can reach the lower stratosphere; hail up to 10 cm, winds > 130 km/h, flash floods; most tornadoes; up to 24 km wide.","s":"Met 13","ch":"Thunderstorms","sec":"Classification by structure (p.113)","h":"chapters/met-13.html#n-classification-by-structure-p-113"},{"t":"Supercritical aerofoil","d":"blunt nose, thick, flat upper surface, S-shaped camber line (cambered aft). Flow does not accelerate as much on the flat top → shock delayed to a higher Mach and weaker → more even loading; thickness gives strength, payload and fuel. But lower CLmax at low speed → needs more high-lift devices.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Designs for high-speed flight (2-53 to 2-54)","h":"chapters/hb-08.html#n-designs-for-high-speed-flight-2-53-to-2-54"},{"t":"Superior (upper) mirage","d":"over snow fields, cold sea → inversion.","s":"Met 10","ch":"Optical Phenomena","sec":"Mirage (p.97)","h":"chapters/met-10.html#n-mirage-p-97"},{"t":"Supplementary","d":"RE recent weather (RERA, RETS); WS RWY09 / WS ALL RWY wind shear; sea temperature and state W19/S4; runway state; RMK remarks.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Surface condition","d":"LE roughness has a considerable effect on CL; roughness aft of about 20% chord has no effect on CL.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Lift curves and factors affecting CL (2-13 to 2-14)","h":"chapters/hb-02.html#n-lift-curves-and-factors-affecting-cl-2-13-to-2-14"},{"t":"Surface movement","d":"head-on → stop or turn right; converging → the one with the other on its right gives way; overtaken has right of way. Stop at all runway-holding positions unless cleared, and at all lighted stop bars (proceed when they are switched off).","s":"Reg 4","ch":"Rules of the Air","sec":"Right of way (p.80–81)","h":"chapters/reg-04.html#n-right-of-way-p-80-81"},{"t":"Surface temperature","d":"measured 1.25 m (4 ft) above the ground in shade, inside a Stevenson screen (door opens away from the sun).","s":"Met 3","ch":"Temperature","sec":"Definitions (p.28)","h":"chapters/met-03.html#n-definitions-p-28"},{"t":"Surface winds","d":"March — W north of 17°N, E south; April — N–NW to E UP and east to NE India; May — SW over Rajasthan, E from E UP to NE India, S over Odisha/WB/Bihar/Jharkhand/Chhattisgarh. Dust-raising winds over the Gangetic plains 0900–1700 h.","s":"Met 19","ch":"Climatology of India","sec":"Summer / pre-monsoon (Mar–May) (p.173–175)","h":"chapters/met-19.html#n-summer-pre-monsoon-mar-may-p-173-175"},{"t":"Surface winds","d":"E–SE north of the trough, SW–W elsewhere (more southerly over WB; NW on the Malabar coast); 5–10 kt over land, ~15 kt at sea; monsoon strength depends on these.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Surge (pulse)","d":"sudden strengthening of the wind within the same air mass; air arrives faster than it leaves → velocity convergence → ascent, CU, showers, squalls. Common over the Arabian Sea in the monsoon: ~40 kt behind (west of) the surge line vs 10–15 kt ahead. Moves with the wind to the head Bay; activates the ITCZ, favours depressions.","s":"Met 18","ch":"Tropical Systems","sec":"Surge and shear line (p.157–158)","h":"chapters/met-18.html#n-surge-and-shear-line-p-157-158"},{"t":"Sweepback","d":"same area but lower effective aspect ratio, so it behaves like a low-AR wing: stalling AoA higher, CLmax lower, stall speed higher. Above about 45° sweep this is mainly from early upper-surface separation.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Lift curves and factors affecting CL (2-13 to 2-14)","h":"chapters/hb-02.html#n-lift-curves-and-factors-affecting-cl-2-13-to-2-14"},{"t":"Sweepback","d":"the leading wing presents a smaller effective sweep (more V cos Λ) → more lift → more lateral stability; 10° sweepback ≈ 1° dihedral. A swept high wing may be over-stable, so anhedral is used. Forward sweep reduces dihedral effect.","s":"Handbook 5","ch":"Stability","sec":"Lateral stability (2-36)","h":"chapters/hb-05.html#n-lateral-stability-2-36"},{"t":"Sweepback","d":"raises Mcrit (only V cos Λ acts across the LE). Drawbacks: tip stall, pitch-up, super stall, Mach tuck, higher take-off/landing speeds, less TE space.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Designs for high-speed flight (2-53 to 2-54)","h":"chapters/hb-08.html#n-designs-for-high-speed-flight-2-53-to-2-54"},{"t":"Swept back","d":"like reducing aspect ratio; improves high-speed characteristics; good in turbulence (gentle lift-curve slope, so gusts change wing loading less).","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Wing planforms (2-28)","h":"chapters/hb-04.html#n-wing-planforms-2-28"},{"t":"Symmetric aerofoil","d":"CP stays at about 25% chord whatever the AoA.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Centre of pressure and aerodynamic centre (2-10)","h":"chapters/hb-01.html#n-centre-of-pressure-and-aerodynamic-centre-2-10"},{"t":"Systems","d":"STJ, 5–7 WDs/month in the north; a few cyclones and easterly waves in the south.","s":"Met 19","ch":"Climatology of India","sec":"Winter (Jan–Feb) (p.171–173)","h":"chapters/met-19.html#n-winter-jan-feb-p-171-173"},{"t":"T — Temperature","d":"high → low temperature: altimeter over-reads (H-L-H). Calibrated to ISA temperature and pressure lapse rate; no altimeter setting compensates for temperature deviation. At constant indicated altitude from warm to cold air the aircraft descends and is truly lower than indicated. \"Hot to cold, don't be bold\" / \"cold kills\". The opposite from cold to hot.","s":"Nav 18","ch":"Altimeter","sec":"Errors — \"BLIP PBT\"","h":"chapters/nav-18.html#n-errors-blip-pbt"},{"t":"T (Dvorak CI) numbers","d":"Low T1.5, D T2.0, DD T2.5, CS T3.0, SCS T3.5, VSCS T4.0–6.0, SuCS T6.5–8.0.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"B. Meteorological scales","h":"chapters/met-30.html#n-b-meteorological-scales"},{"t":"TAF","d":"by AMOs for own and associated AMSs; valid min 9 h, max 30 h. 9-h TAFs every 3 h; 12–30 h TAFs every 6 h, from 0000 UTC.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"Tail-less delta","d":"counters sweepback's drawbacks; large area and chord → strength, less wave drag, lower wing loading, less tip stall. But more skin-friction and form drag (large chord); tips must lie within the Mach cone; needs long intakes and jet pipes.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Designs for high-speed flight (2-53 to 2-54)","h":"chapters/hb-08.html#n-designs-for-high-speed-flight-2-53-to-2-54"},{"t":"Tailplane","d":"the greatest stabilising influence; depends on tail area, planform and moment arm. Elevator position does not change the tail's contribution. Reduced by wing downwash on the tail and lower dynamic pressure at the tail.","s":"Handbook 5","ch":"Stability","sec":"Longitudinal static stability (2-32 to 2-33)","h":"chapters/hb-05.html#n-longitudinal-static-stability-2-32-to-2-33"},{"t":"Take-off","d":"aircraft taxiing on the manoeuvring area give way to aircraft taking off or about to take off.","s":"Reg 4","ch":"Rules of the Air","sec":"Right of way (p.80–81)","h":"chapters/reg-04.html#n-right-of-way-p-80-81"},{"t":"Take-off alternate","d":"to land shortly after take-off if the departure aerodrome cannot be used.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Take-off forecast","d":"within 3 h before ETD: surface wind (2-min mean), temperature, QNH, others.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"Take-off run","d":"flaps lower the lift-off speed (shorter) but cut acceleration (longer); up to the optimum setting the speed effect wins and TORR falls; beyond it TORR rises.","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Lift augmentation (2-31)","h":"chapters/hb-04.html#n-lift-augmentation-2-31"},{"t":"Taper ratio","d":"Ct / Cr. Aspect ratio = span / mean chord = b² / S.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Tapered","d":"taper sets spanwise lift distribution. Moderate taper (0.5) ≈ elliptical behaviour. High taper (0.25): highest CL near the tip → tip-stall tendency. Pointed tip (taper 0): tip always stalled — no practical subsonic use.","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Wing planforms (2-28)","h":"chapters/hb-04.html#n-wing-planforms-2-28"},{"t":"Taxi clearance","d":"concise, to follow the right route, avoid collisions and avoid entering an active runway by mistake. If the taxi limit is beyond a runway, it must contain an explicit clearance to cross or an instruction to hold short.","s":"Reg 8","ch":"Procedures for Aerodrome Control Service","sec":"Traffic and taxi circuit (p.207–208)","h":"chapters/reg-08.html#n-traffic-and-taxi-circuit-p-207-208"},{"t":"Tc","d":"most common over India, especially winter; from the Siberian high; cold, dry, fair weather, poor visibility. Over NW India in summer.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Air masses over India (p.130–131)","h":"chapters/met-14.html#n-air-masses-over-india-p-130-131"},{"t":"TCU","d":"light to severe up to at least the −20°C level.","s":"Met 12","ch":"Ice Accretion","sec":"Icing by cloud (p.108)","h":"chapters/met-12.html#n-icing-by-cloud-p-108"},{"t":"TE flaps","d":"extending them:","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Lift augmentation (2-31)","h":"chapters/hb-04.html#n-lift-augmentation-2-31"},{"t":"TEET (total estimated elapsed time)","d":"IFR — from take-off to that approach point (or over the destination aerodrome if no navaid); VFR — from take-off to over the destination aerodrome.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Temperate latitudes","d":"depressions and fronts → maximum in winter. NW India / J&K / western Himalaya follow this because of Western Disturbances (occluded fronts, frequent in winter).","s":"Met 11","ch":"Precipitation","sec":"Diurnal and seasonal variation (p.104)","h":"chapters/met-11.html#n-diurnal-and-seasonal-variation-p-104"},{"t":"Temperature","d":"Dec–Jan coldest; mean minimum 22°C far south → 10°C northern plains → 6°C Punjab; diurnal range ~13°C (10°C coasts, 5°C Tamil Nadu).","s":"Met 19","ch":"Climatology of India","sec":"Winter (Jan–Feb) (p.171–173)","h":"chapters/met-19.html#n-winter-jan-feb-p-171-173"},{"t":"Temperature","d":"central peninsula 30–35°C in April; mean max 40–42°C; hottest in May (Andamans April, Saurashtra June, Rajasthan & Kashmir July). Max diurnal range 18°C (Gujarat, Saurashtra, MP); ~6°C on coasts. Heat wave: ≥ 4–5°C above normal maximum.","s":"Met 19","ch":"Climatology of India","sec":"Summer / pre-monsoon (Mar–May) (p.173–175)","h":"chapters/met-19.html#n-summer-pre-monsoon-mar-may-p-173-175"},{"t":"Temperature","d":"south ~26°C, Rajasthan ~31°C; spatial range ~9°C, diurnal 4–9°C; rises in breaks.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Temperature","d":"nearly uniform ~18°C; diurnal range 6–7°C; NW India mean falls from ~38°C (Oct) to 28°C (Nov).","s":"Met 19","ch":"Climatology of India","sec":"Post-monsoon / NE monsoon (Oct–Dec) (p.180–182)","h":"chapters/met-19.html#n-post-monsoon-ne-monsoon-oct-dec-p-180-182"},{"t":"Temperature","d":"x.5 rounded up: +2.5 → 03, −2.5 → M02; e.g. 24/M02.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Temperature increasing with height","d":"negative lapse rate → stability, no turbulence.","s":"Met 9","ch":"Stability and Instability","sec":"Inversion (p.88)","h":"chapters/met-09.html#n-inversion-p-88"},{"t":"Temporary aerodrome","d":"used for not more than 6 months.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aerodrome areas (p.4–36)","h":"chapters/reg-01.html#n-aerodrome-areas-p-4-36"},{"t":"Terrain","d":"rises on the windward side, sinks on the lee; strong winds → mountain (lee) waves; can carry WV into the stratosphere → nacreous clouds.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Vertical motion (p.75–76)","h":"chapters/met-08.html#n-vertical-motion-p-75-76"},{"t":"Terrestrial radiation","d":"long-wave, invisible, mostly IR. Earth gains heat as short wave and loses it as long wave.","s":"Met 3","ch":"Temperature","sec":"Solar, terrestrial and nocturnal radiation (p.31)","h":"chapters/met-03.html#n-solar-terrestrial-and-nocturnal-radiation-p-31"},{"t":"Thermal","d":"heat the air above its dew point (WW2 FIDO burners; costly, discontinued).","s":"Met 7","ch":"Visibility and Fog","sec":"Fog dispersal (p.72)","h":"chapters/met-07.html#n-fog-dispersal-p-72"},{"t":"Thermal wind","d":"the vector that must be added to the lower-level geostrophic wind to give the upper-level geostrophic wind = upper − lower (vertical wind shear).","s":"Met 6","ch":"Winds","sec":"Thermal wind (p.58–59)","h":"chapters/met-06.html#n-thermal-wind-p-58-59"},{"t":"Thickness","d":"height difference between two pressure levels: low where the layer is cold, high where warm; thickness lines = isotherms of mean layer temperature.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Contours and thickness (p.16)","h":"chapters/met-02.html#n-contours-and-thickness-p-16"},{"t":"Thin wings","d":"higher Mcrit (less flow acceleration), less wave drag. But less lift, higher take-off/landing speeds and distances, aeroelastic problems, little fuel space, LE separation and abrupt stall.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Designs for high-speed flight (2-53 to 2-54)","h":"chapters/hb-08.html#n-designs-for-high-speed-flight-2-53-to-2-54"},{"t":"Threshold","d":"beginning of the runway usable for landing. Displaced threshold: not at the extremity of the runway. Touchdown zone: where landing aeroplanes first contact the runway.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aerodrome areas (p.4–36)","h":"chapters/reg-01.html#n-aerodrome-areas-p-4-36"},{"t":"Thrust","d":"the blade's total reaction is roughly at right angles to the chord; its forward component is thrust, its component in the plane of rotation is rotational drag (torque) — so a propeller is never 100% efficient.","s":"Handbook 9","ch":"Propellers","sec":"Forces on a blade (2-59)","h":"chapters/hb-09.html#n-forces-on-a-blade-2-59"},{"t":"Tibetan High","d":"warm anticyclone at 300 hPa over the Tibetan plateau (~28°N 98°E), 70–110°E; its easterly outflow feeds the TEJ (13–15°N near Chennai, 150 hPa, July), running from Vietnam to W Africa; accelerates S China Sea → S India, decelerates beyond. Shifts E/W vary monsoon activity; a far-west shift can push the monsoon into Pakistan/N Iran.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"G. Other systems influencing the SW monsoon","h":"chapters/met-30.html#n-g-other-systems-influencing-the-sw-monsoon"},{"t":"Tm","d":"from the N Pacific subtropical high via SE Asia in the monsoon; hot, humid, high dew point; excellent visibility; fair diurnal range; CU with showers/TS. Over NE India and along the Himalaya in summer.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Air masses over India (p.130–131)","h":"chapters/met-14.html#n-air-masses-over-india-p-130-131"},{"t":"TODA","d":"TORA + clearway. ASDA = TORA + stopway. LDA: runway length for the ground run of a landing.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Declared distances (p.14)","h":"chapters/reg-01.html#n-declared-distances-p-14"},{"t":"TORA","d":"runway available for the ground run. TODA = TORA + clearway. ASDA = TORA + stopway. LDA: runway for landing, reduced by a displaced threshold (affects only landings towards that threshold).","s":"Nav 15","ch":"Performance","sec":"Declared distances","h":"chapters/nav-15.html#n-declared-distances"},{"t":"TORA","d":"runway length available for the ground run of a take-off.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Declared distances (p.14)","h":"chapters/reg-01.html#n-declared-distances-p-14"},{"t":"Tornado","d":"rotating funnel sucked up into a CB base; winds > 150 kt; core pressure drop of hundreds of hPa (condensation makes it visible); diameter metres to ~200 m; life minutes to over an hour; narrow path of devastation; hook-shaped radar echo; rare in India (New Delhi, April 1978). Fujita scale (Appendix B).","s":"Met 13","ch":"Thunderstorms","sec":"Tornado, waterspout, dust devil (p.124–125)","h":"chapters/met-13.html#n-tornado-waterspout-dust-devil-p-124-125"},{"t":"Torque","d":"the equal and opposite reaction to turning the propeller — a rolling moment about the longitudinal axis.","s":"Handbook 9","ch":"Propellers","sec":"Pitch and angles (2-58)","h":"chapters/hb-09.html#n-pitch-and-angles-2-58"},{"t":"Torque reaction","d":"the airframe is pushed anticlockwise → on take-off more load on the left wheel; in flight a tendency to roll left. Worst at low speed, high power. Cured by contra-rotating propellers.","s":"Handbook 9","ch":"Propellers","sec":"Propeller effects on the aircraft (2-60) — clockwise propeller seen from behind","h":"chapters/hb-09.html#n-propeller-effects-on-the-aircraft-2-60-clockwise-propeller-seen-from-behind"},{"t":"Torsional aileron flutter","d":"aileron down → wing twists, TE rises, lags, reverses… Cures: mass-balance the ailerons; irreversible (powered) controls.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Aeroelastic problems (2-57)","h":"chapters/hb-08.html#n-aeroelastic-problems-2-57"},{"t":"Towing","d":"no aircraft shall tow an aircraft; towing of aircraft is not permitted in India; objects only as prescribed by the DG.","s":"Reg 4","ch":"Rules of the Air","sec":"General rules (p.78–81)","h":"chapters/reg-04.html#n-general-rules-p-78-81"},{"t":"Track (TR)","d":"path over the ground, normally °T. Required track (RT): wanted; Track made good (TMG): actually flown (join the start and a fix).","s":"Nav 9","ch":"Dead Reckoning","sec":"Terms","h":"chapters/nav-09.html#n-terms"},{"t":"Track error (TE)","d":"angle from required track to TMG; starboard/port likewise; TMG = RT ± TE.","s":"Nav 9","ch":"Dead Reckoning","sec":"Triangle of velocities","h":"chapters/nav-09.html#n-triangle-of-velocities"},{"t":"Trades","d":"steady winds 10°–30°, NE in NH, SE in SH.","s":"Met 6","ch":"Winds","sec":"Named winds (p.61–62)","h":"chapters/met-06.html#n-named-winds-p-61-62"},{"t":"Traffic load (payload)","d":"passengers, baggage, cargo (incl. non-revenue). Useful load = traffic load + usable fuel = TOM − DOM.","s":"Nav 14","ch":"Mass and Balance","sec":"Mass terms","h":"chapters/nav-14.html#n-mass-terms"},{"t":"Trailing-edge stagnation point","d":"skin friction and the adverse gradient take energy out of the BL; if it runs out of kinetic energy it stops near the TE. Separation point: where the upper BL leaves the surface — whenever it lacks the energy to face the adverse gradient.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Transition, separation and the creation of lift (2-12)","h":"chapters/hb-02.html#n-transition-separation-and-the-creation-of-lift-2-12"},{"t":"Transducers","d":"convert pressure, temperature and angles to voltages, synchro outputs or digital pulses; their accuracy governs the whole system.","s":"Nav 17","ch":"Air Data Systems","sec":"Air data system","h":"chapters/nav-17.html#n-air-data-system"},{"t":"Transition altitude","d":"at or below it, vertical position is controlled by altitudes. Transition level: lowest flight level available above the TA. Transition layer: airspace between TA and TL.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Vertical references (p.8–36)","h":"chapters/reg-01.html#n-vertical-references-p-8-36"},{"t":"Transition altitude (TA)","d":"altitude at or below which you fly on QNH (vertical position as altitude).","s":"Met 2","ch":"Atmospheric Pressure","sec":"Altimetry definitions (p.17)","h":"chapters/met-02.html#n-altimetry-definitions-p-17"},{"t":"Transition layer","d":"airspace between TA and TL.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Altimetry definitions (p.17)","h":"chapters/met-02.html#n-altimetry-definitions-p-17"},{"t":"Transition level (TL)","d":"lowest flight level available above TA; above it you fly on 1013.2 hPa. Expressed in hundreds of feet.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Altimetry definitions (p.17)","h":"chapters/met-02.html#n-altimetry-definitions-p-17"},{"t":"Transition point","d":"where the laminar layer becomes turbulent; on a curved aerofoil usually at the point of minimum pressure (maximum camber). It moves forward with a rougher surface and higher speed; forward movement increases skin friction.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Transition, separation and the creation of lift (2-12)","h":"chapters/hb-02.html#n-transition-separation-and-the-creation-of-lift-2-12"},{"t":"Transverse","d":"cylinder tangent along a chosen meridian and its anti-meridian. Conformal; scale correct along the datum meridian, expanding as sec (GC distance from it). Convergence correct at the equator and poles. Straight lines at 90° to the datum meridian are GCs; meridians and parallels are complex curves (parallels ellipses).","s":"Nav 3","ch":"Projections","sec":"Transverse and oblique Mercator","h":"chapters/nav-03.html#n-transverse-and-oblique-mercator"},{"t":"TREND (landing forecast)","d":"appended to METAR/SPECI by AMOs (except Jaipur and Safdarjung); valid 2 h; PROB not used; NOSIG = no significant change.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"Tricycle","d":"the modern standard; the main gear carries about 90% of the weight.","s":"Handbook 11","ch":"Landing Gear, Brakes, Tyres and Powered Controls","sec":"Landing gear design and layout (3-9)","h":"chapters/hb-11.html#n-landing-gear-design-and-layout-3-9"},{"t":"Trigger NOTAM","d":"when an AIP Supplement is published under AIRAC, a NOTAM giving a brief description, effective date/time and the supplement number, in force on the same date, so it appears in the PIB as a reminder.","s":"Reg 10","ch":"Aeronautical Information Services","sec":"NOTAM (p.235–237)","h":"chapters/reg-10.html#n-notam-p-235-237"},{"t":"Trim drag","d":"beyond M 1 the CP moves back → nose-down moment = Mach tuck (tuck-under), worsened by less downwash at the tail; the dive increases speed further. Insignificant subsonic, critical supersonic. Reduced by a Mach trimmer, less CP travel, aft CG, canards.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Effects of shockwaves (2-52)","h":"chapters/hb-08.html#n-effects-of-shockwaves-2-52"},{"t":"Trim tab","d":"adjustable from the cockpit (trim wheel/switch); moved opposite to the surface until its moment balances the hinge moment → zero stick force. Aircraft is trimmed when it holds attitude and speed hands-off; re-trim after any change of speed, power or CG.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Aerodynamic balance (2-40)","h":"chapters/hb-06.html#n-aerodynamic-balance-2-40"},{"t":"Tropics","d":"convective → rain mostly in the afternoon; summer > winter.","s":"Met 11","ch":"Precipitation","sec":"Diurnal and seasonal variation (p.104)","h":"chapters/met-11.html#n-diurnal-and-seasonal-variation-p-104"},{"t":"Tropopause and max-wind chart","d":"tropopause FL in boxes (e.g. FL400); jet path as bold arrows with FL; 0 °C isotherm as short dashes.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"F. Met charts","h":"chapters/met-30.html#n-f-met-charts"},{"t":"Trough","d":"tongue/V-shaped extension of a low; pressure lower than either side; wind changes abruptly and backs; bad weather. Example: monsoon trough over the Indo-Gangetic plains.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure patterns (p.21–22) (isobars at 2 hPa)","h":"chapters/met-02.html#n-pressure-patterns-p-21-22-isobars-at-2-hpa"},{"t":"Trough in the easterlies / easterly wave","d":"shallow trough in the tropical easterlies moving E → W, clearer in upper winds than in surface pressure; cloud and showers; affects S peninsular India.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"A. Synoptic systems","h":"chapters/met-30.html#n-a-synoptic-systems"},{"t":"Trough in the westerlies","d":"mid-latitude wave moving W → E; affects northern India.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"A. Synoptic systems","h":"chapters/met-30.html#n-a-synoptic-systems"},{"t":"Troughs in westerlies","d":"upper-air waves moving W → E with divergence ahead; when behind a surface system, they enhance weather: severe TS/DS, Nor'westers, heavy rain.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Fronts in India and Western Disturbances (p.136–137)","h":"chapters/met-14.html#n-fronts-in-india-and-western-disturbances-p-136-137"},{"t":"True direction (°T)","d":"measured from true north (towards the geographic pole, the earth's spin axis). A line drawn on a map shows a true direction.","s":"Nav 6","ch":"Compass and Directions","sec":"Three norths","h":"chapters/nav-06.html#n-three-norths"},{"t":"TS gust front","d":"cold outflow meets warm air; reaches ~30 km ahead and ~6,000 ft up.","s":"Met 6","ch":"Winds","sec":"Wind shear (p.54–55)","h":"chapters/met-06.html#n-wind-shear-p-54-55"},{"t":"Tubeless tyres","d":"hold pressure longer, no rapid loss on puncture, more impact-resistant, ~7.5% lighter, no creep damage.","s":"Handbook 11","ch":"Landing Gear, Brakes, Tyres and Powered Controls","sec":"Tyres (3-12)","h":"chapters/hb-11.html#n-tyres-3-12"},{"t":"Turning errors","d":"max turning onto/through N/S, nil on E/W. Turning through the nearer pole the compass is sluggish (undershoot) → roll out early; through the equator it is lively (overshoot) → roll out late. (\"APPS\")","s":"Nav 8","ch":"Magnetism and Compasses","sec":"Errors due to dip (direct-reading compass)","h":"chapters/nav-08.html#n-errors-due-to-dip-direct-reading-compass"},{"t":"Twilight colours","d":"refraction, scattering, selective absorption at sunrise/sunset.","s":"Met 10","ch":"Optical Phenomena","sec":"Other phenomena (p.97–98)","h":"chapters/met-10.html#n-other-phenomena-p-97-98"},{"t":"Type A","d":"minimum 250 ft or above; Type B = below 250 ft.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Approaches and runways (p.16–19)","h":"chapters/reg-01.html#n-approaches-and-runways-p-16-19"},{"t":"Ultra-sensitive radar","d":"convection before/after cloud forms; CAT, gravity waves, lee waves.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Wavelength bands (Table 22.1)","h":"chapters/met-22.html#n-wavelength-bands-table-22-1"},{"t":"Upper winds","d":"to ~10,000 ft NW (north/central) and NE (south); westerlies above, strengthening with height, reaching the tip of the peninsula; STJ ~12 km, 27°N, 80–100 kt (max 200).","s":"Met 19","ch":"Climatology of India","sec":"Winter (Jan–Feb) (p.171–173)","h":"chapters/met-19.html#n-winter-jan-feb-p-171-173"},{"t":"Upper winds","d":"westerlies strengthen with height (April 40 kt at 300 hPa, 60 kt at 200 hPa north of 22°N); in May the westerly belt moves to 30°N and 15–20 kt easterlies set in over the peninsula; June: westerlies to 700 hPa, easterlies above south of 25°N (50 kt at 100 hPa).","s":"Met 19","ch":"Climatology of India","sec":"Summer / pre-monsoon (Mar–May) (p.173–175)","h":"chapters/met-19.html#n-summer-pre-monsoon-mar-may-p-173-175"},{"t":"Upper winds","d":"to ~10,000 ft W–SW south of the trough, SE north of it; easterlies from 500 hPa up over almost all India; anticyclones over Tibet and Baluchistan at 200 hPa; TEJ at 15–16 km, 70–80 kt (max 150) along ~13°N.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Upper winds","d":"westerlies re-establish; STJ reappears over J&K; easterlies above 500 hPa only in the far south (~20 kt).","s":"Met 19","ch":"Climatology of India","sec":"Post-monsoon / NE monsoon (Oct–Dec) (p.180–182)","h":"chapters/met-19.html#n-post-monsoon-ne-monsoon-oct-dec-p-180-182"},{"t":"Upslope fog","d":"moist air lifted up a slope, cooling adiabatically.","s":"Met 7","ch":"Visibility and Fog","sec":"Other fogs (p.72)","h":"chapters/met-07.html#n-other-fogs-p-72"},{"t":"Upwash","d":"air approaching the wing rises towards the low pressure above it. Downwash: behind the wing the flow is turned down and then returns to its original direction.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Subsonic airflow over an aerofoil (2-11)","h":"chapters/hb-02.html#n-subsonic-airflow-over-an-aerofoil-2-11"},{"t":"Vapour pressure (e)","d":"partial pressure of WV; pressure of dry air = p − e.","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Variable gases","d":"water vapour, CO, SO₂, NO₂, methane — more over industrial areas, cities, water bodies; tiny in amount but very significant for weather and life.","s":"Met 1","ch":"Atmosphere","sec":"Variable gases and greenhouse gases (p.2)","h":"chapters/met-01.html#n-variable-gases-and-greenhouse-gases-p-2"},{"t":"Variable pitch","d":"a fixed fine blade at high speed (or a coarse one at low speed) works at a poor AoA and L/D, so pitch is varied: fine pitch for take-off and initial acceleration, coarse pitch for high speed (blade angle increases with airspeed), reverse pitch for reverse thrust on the landing roll. In a glide, coarsening reduces RPM and drag → more glide range.","s":"Handbook 9","ch":"Propellers","sec":"Fixed, variable and constant-speed propellers (2-59)","h":"chapters/hb-09.html#n-fixed-variable-and-constant-speed-propellers-2-59"},{"t":"Variable-incidence tailplane","d":"the whole tailplane moves to trim; less trim drag (streamlined), full elevator range kept, elevator stays neutral; good over a wide speed and CG range.","s":"Handbook 6","ch":"Flight Controls, Tabs and Balancing","sec":"Hinges, horns and mass balance (2-41)","h":"chapters/hb-06.html#n-hinges-horns-and-mass-balance-2-41"},{"t":"Variation (magnetic declination)","d":"angle between true and magnetic north. Magnetic north east of true = easterly (+); west = westerly (−). Changes from place to place (and with mineral deposits); given on maps and charts.","s":"Nav 6","ch":"Compass and Directions","sec":"Variation and deviation","h":"chapters/nav-06.html#n-variation-and-deviation"},{"t":"Vector","d":"magnitude and direction. Scalar: magnitude only.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Physical terms (2-3)","h":"chapters/hb-01.html#n-physical-terms-2-3"},{"t":"VFR → IFR","d":"if a flight plan was filed, pass the changes to the current plan; or, when required, submit a flight plan and get a clearance before proceeding IFR in controlled airspace.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Changing flight rules","h":"chapters/nav-16.html#n-changing-flight-rules"},{"t":"VFR controlled flight losing VMC","d":"request an amended clearance to stay VMC (to destination/alternate or to leave controlled airspace); or if none, continue VMC and tell ATC you are leaving or landing at the nearest suitable aerodrome; or in a CTR request special VFR; or request IFR.","s":"Reg 4","ch":"Rules of the Air","sec":"ATC clearances and deviations (p.85–86)","h":"chapters/reg-04.html#n-atc-clearances-and-deviations-p-85-86"},{"t":"Virga","d":"precipitation falling from a cloud that evaporates before reaching the ground.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"The ten genera (p.79–80)","h":"chapters/met-08.html#n-the-ten-genera-p-79-80"},{"t":"Virtual temperature","d":"the temperature at which dry air would have the same pressure and density as the moist air parcel (lets the dry-air equation of state be used for moist air).","s":"Met 3","ch":"Temperature","sec":"Definitions (p.28)","h":"chapters/met-03.html#n-definitions-p-28"},{"t":"Viscosity (μ)","d":"resistance to relative motion between adjacent fluid layers; for air 1.79 × 10⁻⁵ kg/m/s at ISA MSL. In a gas it rises with temperature (more molecular collisions), so it falls with height to the tropopause and stays steady above. In a liquid it falls with temperature.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Viscosity and Reynolds number (2-8)","h":"chapters/hb-01.html#n-viscosity-and-reynolds-number-2-8"},{"t":"Visibility","d":"the greater of (a) distance a black object can be seen against a bright background (= MOR) and (b) distance lights of about 1,000 candelas can be seen against an unlit background.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Flight plans and times (p.13–35)","h":"chapters/reg-01.html#n-flight-plans-and-times-p-13-35"},{"t":"Visibility steps","d":"50 m for 0–800 m; 100 m for 800–5000 m; 1 km for 5000–9000 m; 9999 = 10 km or more. Directional: 6000S; if minimum < 1500 m and another direction > 5000 m report both, e.g. 1400SW 6000E.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Visual approach","d":"an IFR flight completes all or part of the approach by visual reference to terrain. May be requested by the pilot or initiated by the controller (not if the crew may be unfamiliar with the aerodrome). Separation is still provided from other arriving and departing traffic. Once cleared, the pilot is responsible for terrain clearance. May be cleared direct to base or final.","s":"Reg 7","ch":"Separation in the Vicinity of Aerodromes","sec":"Arriving aircraft (p.198–199)","h":"chapters/reg-07.html#n-arriving-aircraft-p-198-199"},{"t":"Visual checkpoint","d":"big enough to see, small enough to pinpoint, unique. Coastlines (inlets, piers better than straight beaches), rivers/lakes (change with seasons, floods, drought, snow), hills (look flatter from higher; may be in cloud), villages (cross-check), towns (shape + roads/railways), cities (too large to fix accurately), railways and roads (line features: along track for tracking, across track for timing; junctions and bri…","s":"Nav 13","ch":"In-flight Navigation","sec":"Visual navigation (map reading)","h":"chapters/nav-13.html#n-visual-navigation-map-reading"},{"t":"VOLMET","d":"met information for aircraft in flight, broadcast on a published schedule, 5-min slots per station on one HF/VHF frequency. D-VOLMET (data link): METAR, SPECI, 9-h TAF, SIGMET, special AIREPs, AIRMET. Voice VOLMET in India on HF from Mumbai and Kolkata in turn every half hour — Mumbai: METARs of Mumbai, Ahmedabad, Chennai, Colombo, Karachi, Male; TAFs of Mumbai, Male, Colombo. Kolkata: METARs of Kolkata, Delhi, Dh…","s":"Met 21","ch":"Met Services for Aviation","sec":"Exchange of met messages (p.201)","h":"chapters/met-21.html#n-exchange-of-met-messages-p-201"},{"t":"VOR","d":"on an RMI or an OBI (TO flag = QDM, FROM flag = QDR); convert with variation at the station (constant for that VOR); plot as QTE from the station's true meridian.","s":"Nav 13","ch":"In-flight Navigation","sec":"Fixes and position lines","h":"chapters/nav-13.html#n-fixes-and-position-lines"},{"t":"VOR","d":"radials diverging at least 15° and at least one aircraft 15 NM or more from the VOR.","s":"Reg 6","ch":"Separation Methods and Minima","sec":"Lateral separation (p.170–172)","h":"chapters/reg-06.html#n-lateral-separation-p-170-172"},{"t":"Vortex generators","d":"small vortices mix fast outer air into the slow BL.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Stall behaviour and how designers tame it (2-20)","h":"chapters/hb-03.html#n-stall-behaviour-and-how-designers-tame-it-2-20"},{"t":"Vortex lift","d":"on a delta at subsonic speed a root-originating LE vortex is held over the wing; its low-pressure core adds lift and delays separation.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Designs for high-speed flight (2-53 to 2-54)","h":"chapters/hb-08.html#n-designs-for-high-speed-flight-2-53-to-2-54"},{"t":"VSI transonic jump","d":"near Mach 1 a shock wave makes the static pressure drop as it passes the static source → a brief false jump on the VSI (a positive sign the aircraft is close to the speed of sound).","s":"Nav 17","ch":"Air Data Systems","sec":"Errors specific to the ASI and VSI","h":"chapters/nav-17.html#n-errors-specific-to-the-asi-and-vsi"},{"t":"VV","d":"90 < 50 m, 91 50–<200, 92 200–<500, 93 500–<1000, 94 1–<2 km, 95 2–<4 km, 96 4–<10 km, 97 10–<20 km, 98 20–<50 km, 99 ≥ 50 km.","s":"Met 24","ch":"Station Models","sec":"Codes","h":"chapters/met-24.html#n-codes"},{"t":"W/V","d":"direction the wind blows from / speed, e.g. 330/25.","s":"Nav 9","ch":"Dead Reckoning","sec":"Terms","h":"chapters/nav-09.html#n-terms"},{"t":"W1W2","d":"0 cloud < 4/8, 1 > 4/8 part period, 2 > 4/8 throughout, 3 DS, 4 FG, 5 DZ, 6 RA, 7 SN, 8 SH, 9 TS.","s":"Met 24","ch":"Station Models","sec":"Codes","h":"chapters/met-24.html#n-codes"},{"t":"WAFS (World Area Forecast System)","d":"gives Met Offices global en-route forecasts (upper winds and temperatures). Two WAFCs: Washington and London. 19 RAFCs (Regional Area Forecast Centres), one at New Delhi.","s":"Met 21","ch":"Met Services for Aviation","sec":"Purpose and organisations (p.194–195)","h":"chapters/met-21.html#n-purpose-and-organisations-p-194-195"},{"t":"Wake","d":"SUPER (book prints S; the ICAO code is J, e.g. A380); /H HEAVY ≥ 136 000 kg MTOM; /M MEDIUM < 136 000 kg but > 7 000 kg; /L LIGHT ≤ 7 000 kg.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Item 9 — Number, type, wake category","h":"chapters/nav-16.html#n-item-9-number-type-wake-category"},{"t":"Wake turbulence","d":"apply the minima; where avoidance is the pilot's responsibility, warn of expected wake hazards.","s":"Reg 8","ch":"Procedures for Aerodrome Control Service","sec":"Information from the tower (p.208–211)","h":"chapters/reg-08.html#n-information-from-the-tower-p-208-211"},{"t":"Warm occlusion","d":"air behind less cold than the air ahead → rides over the warm front; warm-front-type weather; winter, less common.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Occlusions and others (p.134–135)","h":"chapters/met-14.html#n-occlusions-and-others-p-134-135"},{"t":"Warsaw 1929","d":"international carriage of persons, baggage and goods for reward (and free carriage by an air transport undertaking); not postal. Unifies documents (ticket, baggage check), carrier liability and jurisdiction. Loss of ticket does not void the contract, but carrying a passenger without a ticket loses the liability limits. Gross negligence removes the limit.","s":"Reg 2","ch":"International Organisations and Conventions","sec":"Liability conventions (p.54–56)","h":"chapters/reg-02.html#n-liability-conventions-p-54-56"},{"t":"Wash-in","d":"twist that increases incidence towards the tip. Wash-out: twist that decreases incidence towards the tip.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Wash-out from flexure","d":"swept tips twist nose-down under load, losing tip lift.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Tip stall and pitch-up (2-23)","h":"chapters/hb-03.html#n-tip-stall-and-pitch-up-2-23"},{"t":"Waterspout","d":"tornado over the sea (can cause \"rain of fish\").","s":"Met 13","ch":"Thunderstorms","sec":"Tornado, waterspout, dust devil (p.124–125)","h":"chapters/met-13.html#n-tornado-waterspout-dust-devil-p-124-125"},{"t":"Wave (energy) drag","d":"temperature rise behind the shock = energy lost; the more oblique the shock, the less loss. Reduced by vortex generators, area rule, thin wings, sharp leading edges.","s":"Handbook 8","ch":"High-Speed Flight, Envelope and Aeroelasticity","sec":"Effects of shockwaves (2-52)","h":"chapters/hb-08.html#n-effects-of-shockwaves-2-52"},{"t":"WD","d":"low or trough moving W → E, north of 20°N, causing weather. Two or more closed isobars (2 hPa) = Western Depression. Upper troughs above 500 hPa = troughs in westerlies.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Fronts in India and Western Disturbances (p.136–137)","h":"chapters/met-14.html#n-fronts-in-india-and-western-disturbances-p-136-137"},{"t":"Weather","d":"north — clear, dry, poor visibility, low humidity and temperature, broken by WDs: winds back NW → SW/SE, temperature rises, pressure falls, CI → AS, NS, ST, drizzle/rain (warm-front type), then CU/CB, pressure rise, TS (cold-front type); then clear, cold dry N–NW winds, widespread radiation fog and cold waves (temperature ≥ 4°C below normal minimum, lasting 2–3 days). Cold day: maximum ≤ 16°C in the plains. Cold w…","s":"Met 19","ch":"Climatology of India","sec":"Winter (Jan–Feb) (p.171–173)","h":"chapters/met-19.html#n-winter-jan-feb-p-171-173"},{"t":"Weather","d":"widespread dust haze and very high temperatures; dust storms over N/NW India, Nor'westers (Kalbaishakhi) over E and NE India, triggered by WDs; a few cyclones hit Bengal; STJ weakens and moves north.","s":"Met 19","ch":"Climatology of India","sec":"Summer / pre-monsoon (Mar–May) (p.173–175)","h":"chapters/met-19.html#n-summer-pre-monsoon-mar-may-p-173-175"},{"t":"Weather","d":"1–2 WDs/month in the north; best flying season (except S India): clear skies, good visibility. Maximum cyclones: October in the Bay, November in the Arabian Sea; SCS more in November; usually from the Andaman Sea towards TN/AP/Odisha; some recurve to WB/Bangladesh; some cross into the Arabian Sea and hit Maharashtra/Gujarat.","s":"Met 19","ch":"Climatology of India","sec":"Post-monsoon / NE monsoon (Oct–Dec) (p.180–182)","h":"chapters/met-19.html#n-post-monsoon-ne-monsoon-oct-dec-p-180-182"},{"t":"Weather","d":"onset/cessation/intensity change of FZ precipitation, FZFG, moderate/heavy precipitation, drifting/blowing snow, sand, dust, DS, SS, TS, squall, funnel cloud.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"SPECI criteria (p.230–231) — deterioration at once, improvement after 10 min","h":"chapters/met-25.html#n-speci-criteria-p-230-231-deterioration-at-once-improvement-after-10-min"},{"t":"Weather abbreviations","d":"DZ, RA, SN, SG, PL/PE ice pellets, IC ice crystals, GR hail ≥ 5 mm, GS small hail < 5 mm, FG, BR, SA, DU, HZ, FU, VA, PO dust devil, SQ, FC funnel cloud, DS, SS, SH, TS.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Weight","d":"for a given EAS induced drag ∝ W² (CL ∝ W); a heavier aircraft has more.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Factors affecting induced drag (2-17)","h":"chapters/hb-02.html#n-factors-affecting-induced-drag-2-17"},{"t":"Weight","d":"Vs ∝ √W — 20% more weight → about 10% higher Vs. Weight does not change the stalling AoA.","s":"Handbook 3","ch":"Stalls, Spins and Upsets","sec":"Basic stalling speed and what changes it (2-21)","h":"chapters/hb-03.html#n-basic-stalling-speed-and-what-changes-it-2-21"},{"t":"Weight","d":"L/D is independent of weight — a heavier glider at its (higher) VMD has the same glide angle and range, but higher speed and ROD.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Descent and glide (2-45)","h":"chapters/hb-07.html#n-descent-and-glide-2-45"},{"t":"Weight up","d":"more CL and drag; VMD and VMP increase. Flaps, gear, airbrakes, damage: more drag and VMD decreases. Same IAS at any altitude → same drag. AoA: drag grows faster above about 8°; a sudden rise at the stall.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Total drag and the speeds it defines (2-18)","h":"chapters/hb-02.html#n-total-drag-and-the-speeds-it-defines-2-18"},{"t":"Western disturbance (WD)","d":"surface low or mid/lower-tropospheric cyclonic circulation/trough from the Mediterranean, Caspian and Black Seas, moving across N India; with ≥ 2 closed isobars = western depression.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"A. Synoptic systems","h":"chapters/met-30.html#n-a-synoptic-systems"},{"t":"Wet runway","d":"any visible dampness or water up to and including 3 mm deep. Dry: no visible moisture, not contaminated.","s":"Reg 1","ch":"Definitions and Abbreviations","sec":"Aerodrome areas (p.4–36)","h":"chapters/reg-01.html#n-aerodrome-areas-p-4-36"},{"t":"Wet-bulb temperature","d":"lowest temperature air can reach by evaporating water into it until saturated (desert-cooler principle; drier air cools more).","s":"Met 5","ch":"Humidity","sec":"Wet bulb, dew point, frost point (p.42)","h":"chapters/met-05.html#n-wet-bulb-dew-point-frost-point-p-42"},{"t":"White dumbbell","d":"land, take off and taxi on runways and taxiways only. Dumbbell with black bars across each disc: land and take off on runways only; other manoeuvres need not be confined.","s":"Reg 4","ch":"Rules of the Air","sec":"Visual ground signals (p.97–98)","h":"chapters/reg-04.html#n-visual-ground-signals-p-97-98"},{"t":"White or orange landing T","d":"land and take off parallel to the shaft towards the cross-arm (lit or outlined in white at night).","s":"Reg 4","ch":"Rules of the Air","sec":"Visual ground signals (p.97–98)","h":"chapters/reg-04.html#n-visual-ground-signals-p-97-98"},{"t":"Wien's law","d":"wavelength of maximum radiation ∝ 1/T → hot sun emits short waves, cool earth emits long waves.","s":"Met 3","ch":"Temperature","sec":"Insolation and radiation laws (p.30)","h":"chapters/met-03.html#n-insolation-and-radiation-laws-p-30"},{"t":"Wind","d":"horizontal movement of air; a succession of gusts (strong) and lulls (weak). Two components: direction and speed.","s":"Met 6","ch":"Winds","sec":"Basics (p.45)","h":"chapters/met-06.html#n-basics-p-45"},{"t":"Wind","d":"27010KT. VRB when speed < 3 kt (VRB02KT), or at higher speed when direction varies ≥ 180° (VRB10KT). Calm (< 1 kt) 00000KT. Gust 30020G40KT. Extreme directions 270V050 only when variation 60°–180° and wind ≥ 3 kt. ≥ 100 kt: P99KT (240100KT → 240P99KT).","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Wind","d":"direction change ≥ 60° with speed ≥ 10 kt before/after; mean speed change ≥ 10 kt; gust variation ≥ 10 kt with speed ≥ 15 kt. (Any one triggers.)","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"SPECI criteria (p.230–231) — deterioration at once, improvement after 10 min","h":"chapters/met-25.html#n-speci-criteria-p-230-231-deterioration-at-once-improvement-after-10-min"},{"t":"Wind","d":"headwind → steeper climb gradient over the ground (less ground distance); no effect on rate of climb.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Steady climb (2-43)","h":"chapters/hb-07.html#n-steady-climb-2-43"},{"t":"Wind never changes ROC or ROD","d":"only gradients and ground distances.","s":"Handbook 7","ch":"Flight Mechanics: Climb, Glide, Turn, Range","sec":"Exam traps","h":"chapters/hb-07.html#n-exam-traps"},{"t":"Wind shear","d":"variation of wind vector along the aircraft's path that can displace it.","s":"Met 6","ch":"Winds","sec":"Wind shear (p.54–55)","h":"chapters/met-06.html#n-wind-shear-p-54-55"},{"t":"Wind shear","d":"vertical shear → eddies, turbulence; CAT near jet streams; amplified over mountains.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Vertical motion (p.75–76)","h":"chapters/met-08.html#n-vertical-motion-p-75-76"},{"t":"Wind shear","d":"outflow up to ~2,000 ft; landing aircraft gets a headwind then a tailwind; wind can change 90° or more in a few hundred feet. Strong vertical wind shear is needed for a severe TS.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"Wind shear","d":"sustained change in wind along the flight path faster than the aircraft can accelerate/decelerate; low-level wind shear from the surface to about 1,500 ft. A pilot's report is passed to following aircraft until it no longer exists or is in the ATIS and acknowledged; also passed to the met office.","s":"Reg 8","ch":"Procedures for Aerodrome Control Service","sec":"Wind shear, hot spots, friction (p.216–217)","h":"chapters/reg-08.html#n-wind-shear-hot-spots-friction-p-216-217"},{"t":"Wind shear warning","d":"observed/expected wind shear up to 500 m (1600 ft) above the runway on approach, take-off, circling or the runway; topographic shear above 500 m also included; appended to METAR/SPECI in abbreviated plain language, e.g. WS WRNG MBST APCH RWY 30; pilot reports include aircraft type (WS WRNG B747 REPORTED MOD WS IN APCH RWY 28 AT 1000).","s":"Met 21","ch":"Met Services for Aviation","sec":"Warnings (p.200)","h":"chapters/met-21.html#n-warnings-p-200"},{"t":"Winds","d":"SW → NE by mid-October; NE winds pick up moisture over the Bay → rain on TN and parts of Kerala; light variable winds inland; sea breeze felt up to 160 km inland.","s":"Met 19","ch":"Climatology of India","sec":"Post-monsoon / NE monsoon (Oct–Dec) (p.180–182)","h":"chapters/met-19.html#n-post-monsoon-ne-monsoon-oct-dec-p-180-182"},{"t":"Wing loading","d":"weight / wing area. Load factor = lift / weight.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Wing position","d":"high wing — crossflow round the fuselage blows up onto the leading wing (more AoA) → stabilising. Low wing — blows down (less AoA) → destabilising.","s":"Handbook 5","ch":"Stability","sec":"Lateral stability (2-36)","h":"chapters/hb-05.html#n-lateral-stability-2-36"},{"t":"Wing-tip trails","d":"short-lived; pressure drop at wing tips/propellers → adiabatic cooling.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Condensation trails (p.83–84)","h":"chapters/met-08.html#n-condensation-trails-p-83-84"},{"t":"Wings","d":"negligible. Fuselage: side force acts through its AC ahead of the CG → destabilising. CG position: negligible effect (its range is set by longitudinal stability).","s":"Handbook 5","ch":"Stability","sec":"Directional stability (2-35)","h":"chapters/hb-05.html#n-directional-stability-2-35"},{"t":"Wings","d":"biplane (old, < 200 kt), braced (external struts, e.g. Cessna), cantilever (internal spars carry all loads — all modern aircraft; mono-spar or multi-spar).","s":"Handbook 10","ch":"Structures, Hydraulics and Pneumatics","sec":"Airframe construction (3-5)","h":"chapters/hb-10.html#n-airframe-construction-3-5"},{"t":"Wingtip vortex","d":"the pressure difference equalises round the finite tip — air flows outward underneath, round the tip, inward on top; where the streams meet at the trailing edge vortices form, small at the root and largest at the tip. Energy for the vortex comes out of the main flow.","s":"Handbook 2","ch":"Airflow, Lift and Drag","sec":"Induced drag and tip vortices (2-16)","h":"chapters/hb-02.html#n-induced-drag-and-tip-vortices-2-16"},{"t":"WINTEM","d":"forecast upper wind and temperature.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"Withdrawal","d":"from Rajasthan ~1 Sep, NW India 15 Sep, almost all India by 15 Oct, replaced by the NE (winter) monsoon.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Worsen L/D","d":"flaps up always gives the best L/D; of the flap settings, the take-off setting is best. Max climb angle and max glide distance fall; glide steeper. Zero flap gives the best climb angle.","s":"Handbook 4","ch":"Aerofoils, Wings and High-Lift Devices","sec":"Lift augmentation (2-31)","h":"chapters/hb-04.html#n-lift-augmentation-2-31"},{"t":"Yellow","d":"moderate precipitation, very low visibility, moderate turbulence — avoid.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Airborne weather radar (p.209)","h":"chapters/met-22.html#n-airborne-weather-radar-p-209"}];